SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for smartlabos-module
-- ----------------------------
DROP TABLE IF EXISTS `smartlabos-module`;
CREATE TABLE `smartlabos-module`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '卡片ID，如 MOD-CC-001',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模块名称',
  `module_part_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模块物料号',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模块分类',
  `version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '版本',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态 active/...',
  `owner` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '负责人',
  `last_updated` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新(原文保留为字符串)',
  `tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签',
  `data_json` json NULL COMMENT 'front-matter 全量 JSON',
  `raw_frontmatter` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原始 YAML front-matter',
  `body_markdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Markdown 正文',
  `source_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源文件名',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_module_name`(`name` ASC) USING BTREE,
  INDEX `idx_module_category`(`category` ASC) USING BTREE,
  INDEX `idx_module_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'SmartLabOS 模块主数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of smartlabos-module
-- ----------------------------
INSERT INTO `smartlabos-module` VALUES ('MOD-CC-001', '800样品存储模块', 'HHM43E-002', '存储', '1.0', 'active', '杨宇', '2025/11/21', '样品存储，2ml西林瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"样品存储，2ml西林瓶\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 800, \"height_mm\": 600, \"length_mm\": 850, \"weight_kg\": 210, \"mount_type\": \"标准模块位\", \"tray_slots\": \"九十工位\", \"module_slots\": 3}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": 10, \"temperature_c_min\": 0}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"西林瓶-2ml\", \"function_code\": \"D210\", \"sub_functions\": [\"D210 存储\"], \"cycle_time_sec\": 31, \"operation_target\": \"2ml西林瓶\", \"operation_workflow\": \"初始化-预冷- 上样准备-带料托盘放至平台-传感器反馈-气缸动作定位销伸出-机械手从托盘夹取西林瓶 -移至冷藏口- 气缸动作冷藏门打开 -放料到转盘-机械手取下一个料-盖子盖好- 重复上料到上料完成 /  / 样品出库-下料准备-空托盘放至平台-传感器反馈-气缸动作定位销伸出-机械手移至冷藏口-气缸动作冷藏门打开 -机械手从转盘取料-放料到托盘-气缸动作推杆门关闭-重复下料动作到下料完成\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"该模块实现样品冷藏存储功能，并能够通过XYZ机械臂自动取放样品，可通过温度设置，控温0℃或10℃\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 2.4, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 1.44, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-CC-001\", \"name\": \"800样品存储模块\", \"owner\": \"杨宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"存储\", \"last_updated\": \"2025/11/21\", \"module_part_no\": \"HHM43E-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CC-001\n  module_part_no: HHM43E-002\n  name: 800样品存储模块\n  category: 存储\n  version: 1.0\n  status: active\n  last_updated: 2025/11/21\n  owner: 杨宇\nphysical_specs:\n  length_mm: 850\n  width_mm: 800\n  height_mm: 600\n  weight_kg: 210\n  module_slots: 3\n  tray_slots: \"九十工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: 0\n  temperature_c_max: 10\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: D210\n  function_description: 该模块实现样品冷藏存储功能，并能够通过XYZ机械臂自动取放样品，可通过温度设置，控温0℃或10℃\n  operation_target: 2ml西林瓶\n  operation_workflow: \"初始化-预冷- 上样准备-带料托盘放至平台-传感器反馈-气缸动作定位销伸出-机械手从托盘夹取西林瓶 -移至冷藏口- 气缸动作冷藏门打开 -放料到转盘-机械手取下一个料-盖子盖好- 重复上料到上料完成 /  / 样品出库-下料准备-空托盘放至平台-传感器反馈-气缸动作定位销伸出-机械手移至冷藏口-气缸动作冷藏门打开 -机械手从转盘取料-放料到托盘-气缸动作推杆门关闭-重复下料动作到下料完成\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 31\n  consumables: 西林瓶-2ml\n  sub_functions: [D210 存储]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [样品存储，2ml西林瓶]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 1.44\n  power_kva_peak: 2.4\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: true', '# 800样品存储模块\n\n## Purpose (用途说明)\n该模块实现样品冷藏存储功能，并能够通过XYZ机械臂自动取放样品。控温需求0~10℃\n\n## Typical Scenarios (典型应用场景)\n它解决的核心痛点是：在自动化流程中，让温度敏感的试剂/样本全程不离开冷链、不被人工触碰、不被温度波动影响——从临床免疫到分子诊断，从CGT到药物研发，凡是\"液体+低温+自动化\"的场景，都是它的主场\n\n## Working Principle (工作原理)\n800 样品存储模块（通常指可容纳约 800 支标准样本管 / 冻存管的自动化高密度存储单元），核心工作原理是：矩阵式高密度仓位存储 + 机械 / 气动自动存取 + 精确定位与环境控管 + 智能信息绑定，实现样本批量、稳定、可追溯、自动化存储与快速调取。\n\n## Limits & Cautions (限制与注意事项)\n2mL西林瓶90位0-10°C存储模块 = \"冷链不断裂\"的自动化中间站\n核心记住三个字：温（度精准）、洁（闭管防污）、序（FIFO追溯），做到这三点，90%的问题都不会发生\n\n## Remarks (备注)\n', 'MOD-CC-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CC-002', '落地式仓库模块', 'HHM43C-001', '存储', '1.0', 'active', '汪健', '2025/9/19', '落地式仓库', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"落地式仓库\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 850, \"height_mm\": 1800, \"length_mm\": 1400, \"weight_kg\": 200, \"mount_type\": \"平台外置\", \"tray_slots\": \"六十一工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"叉车机器人\", \"人工操作平台\"]}, \"process_capability_1\": {\"consumables\": \"\", \"function_code\": 627, \"sub_functions\": [\"628-预出仓\", \"629-出仓\", \"631-取料\", \"632-放料\", \"633-取放料\"], \"cycle_time_sec\": 30, \"operation_target\": \"标准托盘\", \"operation_workflow\": \"从接驳位取托盘，入到空闲库位，完成入库； / 从库位取托盘，出到接驳位，完成出库；\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"入仓\", \"absolute_accuracy_pct\": \"\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 1.014, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.6084, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-CC-002\", \"name\": \"落地式仓库模块\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 1.0, \"category\": \"存储\", \"last_updated\": \"2025/9/19\", \"module_part_no\": \"HHM43C-001\"}, \"platform_compatibility\": {\"compatible_platforms\": [], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CC-002\n  module_part_no: HHM43C-001\n  name: 落地式仓库模块\n  category: 存储\n  version: 1.0\n  status: active\n  last_updated: 2025/9/19\n  owner: 汪健\nphysical_specs:\n  length_mm: 1400\n  width_mm: 850\n  height_mm: 1800\n  weight_kg: 200\n  module_slots: 0\n  tray_slots: \"六十一工位\"\n  mount_type: 平台外置\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 627\n  function_description: 入仓\n  operation_target: 标准托盘\n  operation_workflow: \"从接驳位取托盘，入到空闲库位，完成入库； / 从库位取托盘，出到接驳位，完成出库；\"\n  absolute_accuracy_pct: \"\"\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 30\n  consumables: \"\"\n  sub_functions: [628-预出仓, 629-出仓, 631-取料, 632-放料, 633-取放料]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    []\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 叉车机器人\n    - 人工操作平台\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [落地式仓库]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.6084\n  power_kva_peak: 1.014\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 落地式仓库模块\n\n## Purpose (用途说明)\n样品耗材存储\n\n## Typical Scenarios (典型应用场景)\n落地式仓库模块主要用于实验室自动化、样品前处理、检测流水线、小型智能制造，实现样品托盘自动入库、暂存、出库、调度，对接轨道机器人，提高通量、稳定性与无人化水平\n\n## Working Principle (工作原理)\nXYZ 机械手 + 伸缩货叉，自动存取托盘，对接轨道机器人，实现样品托盘自动化仓储流转\n\n## Limits & Cautions (限制与注意事项)\n1.运行前检查货叉、电磁锁、传感器状态，托盘摆放平稳无突出\n2.运行中禁止进入作业区、触碰运动部件，防止夹伤、碰撞。\n定期校准X/Z 轴零点、货叉伸缩精度，保证 ±0.1mm 定位。\n3.保持库位与传感器清洁，避免粉尘遮挡导致误检。\n4.异常（卡滞、异响、传感器报错）立即停机断电，排查后再启动。\n5.长期停用需将货叉回零、断电防尘，防止受潮老化。\n\n## Remarks (备注)\n', 'MOD-CC-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CG-001', '30ml/125mlPP瓶拆装盖模块', 'HHM02F-901', '拆盖', '1.0', 'active', '黄文兴', '2025/3/14', '拆盖', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"拆盖\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 125, \"volume_ml_min\": 30, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"125mlPP瓶 / 30mlPP瓶 / \", \"function_code\": 91, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 80, \"operation_target\": \"125mlPP瓶，30mlPP瓶\", \"operation_workflow\": \"上料：2个带盖的125mlPP瓶/1个125mlPP瓶和1个30mlPP瓶；拆盖：2个带盖PP瓶拆盖；装盖：2个带盖PP瓶装盖；下料：2个带盖的125mlPP瓶/1个125mlPP瓶和1个30mlPP瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"完成125mlPP瓶和30mlPP瓶的拆装盖，可以拆同一个规格瓶，也可以左右两边拆装的不是同一个规格瓶\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.224, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.1344, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-CG-001\", \"name\": \"30ml/125mlPP瓶拆装盖模块\", \"owner\": \"黄文兴\", \"status\": \"active\", \"version\": 1.0, \"category\": \"拆盖\", \"last_updated\": \"2025/3/14\", \"module_part_no\": \"HHM02F-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CG-001\n  module_part_no: HHM02F-901\n  name: 30ml/125mlPP瓶拆装盖模块\n  category: 拆盖\n  version: 1.0\n  status: active\n  last_updated: 2025/3/14\n  owner: 黄文兴\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 30\n  volume_ml_max: 125\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 91\n  function_description: 完成125mlPP瓶和30mlPP瓶的拆装盖，可以拆同一个规格瓶，也可以左右两边拆装的不是同一个规格瓶\n  operation_target: 125mlPP瓶，30mlPP瓶\n  operation_workflow: 上料：2个带盖的125mlPP瓶/1个125mlPP瓶和1个30mlPP瓶；拆盖：2个带盖PP瓶拆盖；装盖：2个带盖PP瓶装盖；下料：2个带盖的125mlPP瓶/1个125mlPP瓶和1个30mlPP瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 80\n  consumables: \"125mlPP瓶 / 30mlPP瓶 / \"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [拆盖]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.1344\n  power_kva_peak: 0.224\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 30ml/125mlPP瓶拆装盖模块\n\n## Purpose (用途说明)\n用于实现有机样品净化，通过SPE色谱柱分离除去样品中杂质\n\n## Typical Scenarios (典型应用场景)\n无机金属离子检测\n\n## Working Principle (工作原理)\n模块主要由Y轴、Z轴滚珠丝杆电机、钧舵电爪、Y轴载台、光电传感器、手指气缸、电磁阀等组成。 其中手指气缸夹紧瓶身后，Y轴电机带动载台移动，Z轴电机带动电爪进行直线运动，下降到合适高度进行拆盖\n\n## Limits & Cautions (限制与注意事项)\n核心原则：速度不超50mm/s、精度守住±0.1mm、气压稳在0.5MPa、夹紧力必须反馈确认、单独测试必须手动按钮——任何一条红线都不能碰\n\n## Remarks (备注)\n', 'MOD-CG-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CG-002', '100ml试管拔塞模块', 'HHM02L-100', '拔塞', '1.0', 'active', '朱园林', '2025/5/19', '拔塞，盖塞，拆盖，装盖', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"拔塞，盖塞，拆盖，装盖\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"NA\"]}, \"process_capability_1\": {\"consumables\": \"试管-100ml\", \"function_code\": 550, \"sub_functions\": [\"551-启动拔塞 552-启动装塞\"], \"cycle_time_sec\": 90, \"operation_target\": \"100ml试管\", \"operation_workflow\": \"载台移至上下料位 - 放入试管 - 载台移至拆盖位 - 夹紧试管 - 气缸夹爪下降至试管塞处 - 夹爪夹住管塞 - 提起 - 载台移至上下料位 - 取走试管操作 - 试管返回 - 载台移至拆盖位 - 气缸夹爪下降 - 管塞塞进试管 - 气缸夹爪上升 - 载台移至上下料位 - 取下试管； / 停顿1分钟，重复工作流程\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"启动拔塞装塞\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.224, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.12, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-CG-002\", \"name\": \"100ml试管拔塞模块\", \"owner\": \"朱园林\", \"status\": \"active\", \"version\": 1.0, \"category\": \"拔塞\", \"last_updated\": \"2025/5/19\", \"module_part_no\": \"HHM02L-100\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CG-002\n  module_part_no: HHM02L-100\n  name: 100ml试管拔塞模块\n  category: 拔塞\n  version: 1.0\n  status: active\n  last_updated: 2025/5/19\n  owner: 朱园林\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 550\n  function_description: 启动拔塞装塞\n  operation_target: 100ml试管\n  operation_workflow: \"载台移至上下料位 - 放入试管 - 载台移至拆盖位 - 夹紧试管 - 气缸夹爪下降至试管塞处 - 夹爪夹住管塞 - 提起 - 载台移至上下料位 - 取走试管操作 - 试管返回 - 载台移至拆盖位 - 气缸夹爪下降 - 管塞塞进试管 - 气缸夹爪上升 - 载台移至上下料位 - 取下试管； / 停顿1分钟，重复工作流程\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 90\n  consumables: 试管-100ml\n  sub_functions: [551-启动拔塞\n552-启动装塞]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - NA\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [拔塞，盖塞，拆盖，装盖]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.12\n  power_kva_peak: 0.224\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 100ml试管拔塞模块\n\n## Purpose (用途说明)\n100ml试管的拆盖和装盖功能\n\n## Typical Scenarios (典型应用场景)\n1、全自动水样前处理产线中100ml 试管自动拔塞工位\n2、检测前试管开盖取样与取样后自动回塞封口一体化场景\n3、多工位联动流水线：试管拔塞→样品处理→试管装盖闭环作业\n4、机械手自动上下料的无人化试管拆盖 / 装盖场景\n5、水质 COD、总磷、总氮等项目标准 100ml 试管开盖前处理\n\n## Working Principle (工作原理)\n依靠 Y 轴、Z 轴步进模组配合气缸夹爪与夹紧模组，通过光电及传感器检测定位，自动完成试管移位、夹紧、拔塞、等待处理、自动回装瓶盖并送回下料位的全自动拆盖装盖流程\n\n## Limits & Cautions (限制与注意事项)\n1、定期清洁光电开关、传感器表面，保证检测准确。\n2、检查气缸感应线、电机线无松动、无破损，连接牢固。\n3、导轨与滑动部件定期润滑，保持运动顺畅无异响。\n4、电磁阀、气缸漏气、响应慢时立即更换，避免拔塞失败。\n5、步进电机丢步、定位不准时，重新回零校准再运行。\n6、气路保持排水、过滤，防止水分损坏气缸与电磁阀。\n\n## Remarks (备注)\n', 'MOD-CG-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CS-001', '10ML西林瓶多通道超声模块', 'HHM14E-010', '超声', '1.0', 'active', '王志', '2025/10/17', '超声，10ml西林瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"超声，10ml西林瓶\"]}, \"peripherals\": {\"required_peripherals\": \"冷水机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 400, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 10, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 30, \"temperature_c_min\": 20}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"西林瓶-10ml\", \"function_code\": 726, \"sub_functions\": [\"726 1#超声启动 727 2#超声启动 728 排废水\"], \"cycle_time_sec\": \"NA\", \"operation_target\": \"10ml西林瓶\", \"operation_workflow\": \"冷却循环水开启 - 超声水槽水温达标（25±5℃）- 放入西林瓶 - 超声振子开启 - 超声（60min）- 停止 - 取出西林瓶 - 置于蒸发槽内 - 西林瓶底部水珠吸入海绵并蒸干 - 取走西林瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"1#超声启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.574, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.3444, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-CS-001\", \"name\": \"10ML西林瓶多通道超声模块\", \"owner\": \"王志\", \"status\": \"active\", \"version\": 1.0, \"category\": \"超声\", \"last_updated\": \"2025/10/17\", \"module_part_no\": \"HHM14E-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CS-001\n  module_part_no: HHM14E-010\n  name: 10ML西林瓶多通道超声模块\n  category: 超声\n  version: 1.0\n  status: active\n  last_updated: 2025/10/17\n  owner: 王志\nphysical_specs:\n  length_mm: 400\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: 20\n  temperature_c_max: 30\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 冷水机\nprocess_capability_1:\n  function_code: 726\n  function_description: 1#超声启动\n  operation_target: 10ml西林瓶\n  operation_workflow: 冷却循环水开启 - 超声水槽水温达标（25±5℃）- 放入西林瓶 - 超声振子开启 - 超声（60min）- 停止 - 取出西林瓶 - 置于蒸发槽内 - 西林瓶底部水珠吸入海绵并蒸干 - 取走西林瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: NA\n  consumables: 西林瓶-10ml\n  sub_functions: [726 1#超声启动 727 2#超声启动 728 排废水]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [超声，10ml西林瓶]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.3444\n  power_kva_peak: 0.574\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: true', '# 10ML西林瓶多通道超声模块\n\n## Purpose (用途说明)\n按设定超声时间计时，取出已经达到超声时间的西林瓶，不需要停止其他超声中的西林瓶\n\n## Typical Scenarios (典型应用场景)\n1. 样品前处理消解加速\n2. 药物溶出/均匀化\n3. 放射性核素均匀分散\n4. 标准品/质控样制备\n\n## Working Principle (工作原理)\n模块搭载多组独立超声振子，精准对应 10ml 标准西林瓶工位，设备通电后超声换能器将电能转化为高频机械超声波振动；振动能量平稳传导至瓶内液体，形成空化效应、湍流效应与微射流作用，快速实现样品破壁、萃取、混匀、溶解、乳化等处理；多通道同步独立工作，可批量同步处理样品，能量均匀输出，保证各组样品处理效果一致，整体结构贴合瓶体，超声传导损耗低，处理效率高。\n\n## Limits & Cautions (限制与注意事项)\n核心限制 = 仅限10mL瓶 + 4瓶/批 + 噪音/电磁干扰大 + 无自动终点判断\n凡是\"瓶型不对、要大批量、要自动判断终点、不做防辐射处理\"的场景，都需重新评估是否适用本模块。\n\n## Remarks (备注)\n', 'MOD-CS-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CS-002', '15ml西林瓶多通道超声模块', 'HHM14E-015', '超声', '1.0', 'active', '唐宋', '2026/5/7', '15ml西林瓶，超声', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"15ml西林瓶，超声\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 15, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 28, \"temperature_c_min\": 22}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"西林瓶拆盖模块\"]}, \"process_capability_1\": {\"consumables\": \"15ml西林瓶\", \"function_code\": 726, \"sub_functions\": [\"727-2#超声启动\", \"728-排废水\"], \"cycle_time_sec\": 300, \"operation_target\": \"15ml西林瓶\", \"operation_workflow\": \"初始化-- 放入西林瓶 - 冷却循环水开启(- 超声水槽水温达标（25±3℃）) - 超声振子开启 - 超声（60min）- 停止 - 取出西林瓶 - 置于蒸发槽内 - 西林瓶底部水珠吸入海绵并蒸干 - 取走西林瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"1#超声启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 72, \"voltage_v\": 220, \"power_kva_peak\": 0.76, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.45, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-CS-002\", \"name\": \"15ml西林瓶多通道超声模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"超声\", \"last_updated\": \"2026/5/7\", \"module_part_no\": \"HHM14E-015\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CS-002\n  module_part_no: HHM14E-015\n  name: 15ml西林瓶多通道超声模块\n  category: 超声\n  version: 1.0\n  status: active\n  last_updated: 2026/5/7\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 15\n  temperature_c_min: 22\n  temperature_c_max: 28\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 726\n  function_description: 1#超声启动\n  operation_target: 15ml西林瓶\n  operation_workflow: 初始化-- 放入西林瓶 - 冷却循环水开启(- 超声水槽水温达标（25±3℃）) - 超声振子开启 - 超声（60min）- 停止 - 取出西林瓶 - 置于蒸发槽内 - 西林瓶底部水珠吸入海绵并蒸干 - 取走西林瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 300\n  consumables: 15ml西林瓶\n  sub_functions: [727-2#超声启动, 728-排废水]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 西林瓶拆盖模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [15ml西林瓶，超声]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.45\n  power_kva_peak: 0.76\n  voltage_v: 220\n  noise_db: 72\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: true', '# 15ml西林瓶多通道超声模块\n\n## Purpose (用途说明)\n本模块用于15ml 西林瓶样品的多通道并行超声处理，适配样品分散、溶解、萃取、混匀、脱气等前处理场景，支持不停机续料 / 取料，提升样品处理效率\n\n## Typical Scenarios (典型应用场景)\n1、药物样品超声溶解\n2、生物样品提取 / 混匀\n3、化学样品分散 / 脱气\n4、香精 / 精油 / 微量样品萃取\n\n## Working Principle (工作原理)\n通过超声空化效应处理样品，配合TEC 恒温 + 液位自控保障条件稳定，实现 15ml 西林瓶多通道并行、不停机上下料的自动化超声前处理\n\n## Limits & Cautions (限制与注意事项)\n1、水位控制：必须在设定液位范围内运行；严禁无水 / 低水位超声，会烧毁振子。\n2、放瓶要求：瓶子直立、平稳放置，避免倾倒、进水。\n3、动态上下料：中途取放瓶需确认工位到位、动作平稳，避免碰撞、溅水。\n4、温度监控：超声中实时关注水温，异常立即停机。\n5、后处理：取出后擦拭瓶底残留水，避免带入后续模块。\n6、维护：定期换水、清洁水槽；长期不用排空水、断电\n\n## Remarks (备注)\n', 'MOD-CS-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CS-003', '50-250ml容量瓶超声模块', 'HHM14A-902', '超声', '1.0', 'active', '唐宋', '2026/4/17', '超声，容量瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"超声，容量瓶\"]}, \"peripherals\": {\"required_peripherals\": \"半导体制冷\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 304, \"height_mm\": 162, \"length_mm\": 615, \"weight_kg\": 50, \"mount_type\": \"托盘位\", \"tray_slots\": \"十二工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 250, \"volume_ml_min\": 50, \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": 30, \"temperature_c_min\": 20}, \"delivery_maintenance\": {\"wear_parts\": \"超声振子\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\", \"称量模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"容量瓶-50ml / 容量瓶-100ml / 容量瓶-200ml / 容量瓶250ml\", \"function_code\": 110, \"sub_functions\": [], \"cycle_time_sec\": 1200, \"operation_target\": \"50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\", \"operation_workflow\": \"放入容量瓶至上料位 - 夹爪闭合夹紧 - 注水至设置水位-冷却循环水开启 - 超声水槽水温达标（25±5℃） - 超声（20min）- 排水 - 夹爪打开 - 取下容量瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \" 50ml-250ml 容量瓶超声\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 74, \"voltage_v\": 24, \"power_kva_peak\": 0.6, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.36, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-CS-003\", \"name\": \"50-250ml容量瓶超声模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"超声\", \"last_updated\": \"2026/4/17\", \"module_part_no\": \"HHM14A-902\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CS-003\n  module_part_no: HHM14A-902\n  name: 50-250ml容量瓶超声模块\n  category: 超声\n  version: 1.0\n  status: active\n  last_updated: 2026/4/17\n  owner: 唐宋\nphysical_specs:\n  length_mm: 615\n  width_mm: 304\n  height_mm: 162\n  weight_kg: 50\n  module_slots: 0\n  tray_slots: \"十二工位\"\n  mount_type: 托盘位\nmodule_performance:\n  volume_ml_min: 50\n  volume_ml_max: 250\n  temperature_c_min: 20\n  temperature_c_max: 30\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 半导体制冷\nprocess_capability_1:\n  function_code: 110\n  function_description: \" 50ml-250ml 容量瓶超声\"\n  operation_target: 50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\n  operation_workflow: 放入容量瓶至上料位 - 夹爪闭合夹紧 - 注水至设置水位-冷却循环水开启 - 超声水槽水温达标（25±5℃） - 超声（20min）- 排水 - 夹爪打开 - 取下容量瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 1200\n  consumables: \"容量瓶-50ml / 容量瓶-100ml / 容量瓶-200ml / 容量瓶250ml\"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n    - 称量模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 超声振子\ntags_meta:\n  tags: [超声，容量瓶]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.36\n  power_kva_peak: 0.6\n  voltage_v: 24\n  noise_db: 74\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 50-250ml容量瓶超声模块\n\n## Purpose (用途说明)\n本模块用于50~250ml 标准容量瓶的自动化超声溶解与清洗，替代人工手持操作，实现多瓶并行、标准化处理，适配样品前处理环节\n\n## Typical Scenarios (典型应用场景)\n1、环境样品前处理\n2、食品 / 化工样品溶解定容\n3、实验室批量样品高通量制备\n\n## Working Principle (工作原理)\n模块由三轴运动、气动夹持、超声振子、水槽温控组成，实现容量瓶自动上下料、超声溶解、恒温辅助的自动化流程。\n\n## Limits & Cautions (限制与注意事项)\n1、放瓶要求：容量瓶直立、放稳、夹持到位，防止倾斜、碰撞、掉落。\n2、水位要求：水槽水位需达标，严禁无水 / 低水位超声，避免振子烧毁。\n3、加热使用：加热时缓慢升温，避免骤热；容量瓶外壁保持干燥，防止温差炸裂。\n4、运动安全：运行中严禁伸手靠近夹持、升降、平移机构，避免夹伤、撞伤。\n5、日常维护：定期换水、清洁水槽、检查振子；长期不用排空水、断电\n\n## Remarks (备注)\n', 'MOD-CS-003.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CS-004', '50ml离心管多通道超声模块', 'HHM14D-050', '超声', '2.0', 'active', '蔡勤超/深圳', '2025/6/6', '50ml离心管，超声', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"50ml离心管，超声\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 175, \"length_mm\": 250, \"weight_kg\": 25, \"mount_type\": \"托盘位\", \"tray_slots\": \"十六工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 60, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\", \"称量模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"离心管拆盖模块\"]}, \"process_capability_1\": {\"consumables\": \"50ml离心管\", \"function_code\": 726, \"sub_functions\": [\"727-2#超声启动\", \"728-排废水\"], \"cycle_time_sec\": 300, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"冷却循环水开启 - 放入离心管 - 超声振子开启 - 超声 - 停止 - 取出离心管 - 置于蒸发槽内 - 离心管底部水珠吸入海绵并蒸干 - 取走离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"1#超声启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 72, \"voltage_v\": 220, \"power_kva_peak\": 0.37, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.23, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-CS-004\", \"name\": \"50ml离心管多通道超声模块\", \"owner\": \"蔡勤超/深圳\", \"status\": \"active\", \"version\": 2.0, \"category\": \"超声\", \"last_updated\": \"2025/6/6\", \"module_part_no\": \"HHM14D-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CS-004\n  module_part_no: HHM14D-050\n  name: 50ml离心管多通道超声模块\n  category: 超声\n  version: 2.0\n  status: active\n  last_updated: 2025/6/6\n  owner: 蔡勤超/深圳\nphysical_specs:\n  length_mm: 250\n  width_mm: 180\n  height_mm: 175\n  weight_kg: 25\n  module_slots: 0\n  tray_slots: \"十六工位\"\n  mount_type: 托盘位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: 25\n  temperature_c_max: 60\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 726\n  function_description: 1#超声启动\n  operation_target: 50ml离心管\n  operation_workflow: 冷却循环水开启 - 放入离心管 - 超声振子开启 - 超声 - 停止 - 取出离心管 - 置于蒸发槽内 - 离心管底部水珠吸入海绵并蒸干 - 取走离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 300\n  consumables: 50ml离心管\n  sub_functions: [727-2#超声启动, 728-排废水]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n    - 称量模块\n  typical_pairings:\n    - --和模块配合使用\n    - 离心管拆盖模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [50ml离心管，超声]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.23\n  power_kva_peak: 0.37\n  voltage_v: 220\n  noise_db: 72\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: true', '# 50ml离心管多通道超声模块\n\n## Purpose (用途说明)\n本模块用于50ml 离心管样品的多通道并行超声处理，适配样品分散、溶解、萃取、混匀、脱气等前处理场景，支持不停机续料 / 取料，提升样品处理效率。\n\n## Typical Scenarios (典型应用场景)\n1、药物样品超声溶解\n2、生物样品提取 / 混匀\n3、化学样品分散 / 脱气\n4、香精 / 精油 / 微量样品萃取\n\n## Working Principle (工作原理)\n通过超声空化效应处理样品，配合TEC 恒温 + 液位自控保障条件稳定，实现 50ml离心管多通道并行、不停机上下料的自动化超声前处理。\n\n## Limits & Cautions (限制与注意事项)\n1、水位控制：必须在设定液位范围内运行；严禁无水 / 低水位超声，会烧毁振子。\n2、放瓶要求：瓶子直立、平稳放置，避免倾倒、进水。\n3、动态上下料：中途取放瓶需确认工位到位、动作平稳，避免碰撞、溅水。\n4、温度监控：超声中实时关注水温，异常立即停机。\n5、后处理：取出后擦拭瓶底残留水，避免带入后续模块。\n6、维护：定期换水、清洁水槽；长期不用排空水、断电\n\n## Remarks (备注)\n', 'MOD-CS-004.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-CS-005', '50ml离心管超声模块', 'HHM14C-050', '超声', '2.0', 'active', '蔡勤超', '2026/1/23', '超声', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"超声\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 60, \"temperature_c_min\": 0}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml / \", \"function_code\": 726, \"sub_functions\": [\"726 1#超声启动 727 2#超声启动 728 排废水\"], \"cycle_time_sec\": \"动态\", \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"冷却循环水开启 - 超声水槽水温达标（25±5℃）- 放入离心管（有盖） - 超声振子开启 - 超声（20min）- 停止 - 取出离心管 - 置于蒸发槽内 - 离心管底部水珠吸入海绵并蒸干 - 取走离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"#1 启动超声\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 0.373, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.2238, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-CS-005\", \"name\": \"50ml离心管超声模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 2.0, \"category\": \"超声\", \"last_updated\": \"2026/1/23\", \"module_part_no\": \"HHM14C-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-CS-005\n  module_part_no: HHM14C-050\n  name: 50ml离心管超声模块\n  category: 超声\n  version: 2.0\n  status: active\n  last_updated: 2026/1/23\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: 0\n  temperature_c_max: 60\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 726\n  function_description: \"#1 启动超声\"\n  operation_target: 50ml离心管\n  operation_workflow: 冷却循环水开启 - 超声水槽水温达标（25±5℃）- 放入离心管（有盖） - 超声振子开启 - 超声（20min）- 停止 - 取出离心管 - 置于蒸发槽内 - 离心管底部水珠吸入海绵并蒸干 - 取走离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 动态\n  consumables: \"离心管-50ml / \"\n  sub_functions: [726 1#超声启动 727 2#超声启动 728 排废水]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [超声]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.2238\n  power_kva_peak: 0.373\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: false', '# 50ml离心管超声模块\n\n## Purpose (用途说明)\n50ml离心管，可通过外超声波震动的方式，实现超声溶解操作\n\n## Typical Scenarios (典型应用场景)\n食品 / 环境样品自动化超声提取前处理\n按照国标BJS202310、31658.17要求，对50ml 离心管内样品进行全自动超声提取、溶解、混匀，替代人工手扶超声，支持多工位并行，全程控温控水位，满足检测实验标准化作业。\n\n## Working Principle (工作原理)\n模块内置超声换能振子，将电能转换为高频机械振动，振动能量传导至贴合放置的 50ml 离心管；管内液体产生空化、湍流、微冲击效应，借助声波作用力，实现样品破碎、萃取、混匀、溶解、乳化处理，多工位同步作业可批量加工试样。\n\n## Limits & Cautions (限制与注意事项)\n1、仅适配50ml 离心管，必须带盖、拧紧、无漏液，禁止敞口超声。\n2、必须水位正常、温控正常才能启动，缺水、超温禁止运行。\n3、一次最多放4 个，需均匀放置，禁止偏载、空槽运行。\n4、运行中禁止开盖、伸手、触碰超声槽，防止烫伤、触电、机械夹伤。\n5、超声后必须擦干管底再下料，防止水滴污染平台。\n6、维护需断电、停水、降温后操作，定期清洁水槽与除垢。\n\n## Remarks (备注)\n', 'MOD-CS-005.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
