generating\": \"false\", \"power_kva_nominal\": 0.138, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-DR-003\", \"name\": \"注射器定容模块（250ul/1000ul）\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"定容\", \"last_updated\": \"2026/3/19\", \"module_part_no\": \"HHM08C-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-DR-003\n  module_part_no: HHM08C-901\n  name: 注射器定容模块（250ul/1000ul）\n  category: 定容\n  version: 1.0\n  status: active\n  last_updated: 2026/3/19\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 21\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.25\n  volume_ml_max: 1\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 660，661\n  function_description: 加标\n  operation_target: 50ml离心管\n  operation_workflow: 载台移至上下料位 - 放入西林瓶/离心管/样品瓶 - 载台移至吸样品位 - 样品针下降 - 润针-吸样品 - 样品针上升 - 载台旋转至加样品位 - 样品针下降 - 吐液 -移液针上升 -重复移液动作- 载台移至清洗位 - 清洗槽内加有机溶剂 - 移液针下降 - 清洗 -吸入吐出 -- 蠕动泵开启 - 清洗槽排空 - 蠕动泵关闭 - 移液针排空2次 - 移液针上升 - 清洗槽内加纯水 - 移液针下降 - 清洗-吸入吐出 -  - 蠕动泵开启 - 清洗槽排空 - 蠕动泵关闭 - 移液针排空2次 - 移液针上升 - 清洗槽内加有机溶剂 - 移液针下降 - 清洗-吸入吐出 - - 蠕动泵开启 - 清洗槽排空 - 蠕动泵关闭 - 移液针排空2次 - 移液针上升 - 载体移至上下料位 - 取下西林瓶/离心管/样品瓶\n  absolute_accuracy_pct: ±0.6%\n  repeat_accuracy_pct: ≤0.2%\n  cycle_time_sec: 270\n  consumables: \"西林瓶-10ml / 西林瓶-2ml / 离心管-15ml\"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 注射器\ntags_meta:\n  tags: [定容]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.138\n  power_kva_peak: 0.23\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: true', '# 注射器定容模块（250ul/1000ul）\n\n## Purpose (用途说明)\n往样品管定量注入试剂，支持试剂管的自动上料及位置旋转切换，自动洗针等功能\n\n## Typical Scenarios (典型应用场景)\n1、理化 / 化学分析标准溶液配制\n2、环境监测水样 / 土壤样品定量稀释\n3、食品检测微量样品定量分装\n4、生物医药试剂 / 培养基微量配制\n5、科研高通量微量反应体系构建\n\n## Working Principle (工作原理)\n通过进出旋转接料平台实现管路位置切换，搭配双组独立升降、抽液轴完成注射器吸液、定量注液动作，并由双工位洗针机构自动清洗进样器，以此实现精准、高效的样品与试剂移液定容作业。\n\n## Limits & Cautions (限制与注意事项)\n仅适配 25/100/250/1000μL 进样器与标准微量管；适用低粘度水相 / 常规试剂，禁高粘、结晶、强腐蚀、含颗粒液体。环境要求 18–28℃、湿度 40%–60% RH，DC24V 稳定供电。运行中禁止干预，定期校准进样器、更换针头；换试剂需充分洗针防交叉污染；堵针 / 漏液 / 卡顿先断电处理。\n\n## Remarks (备注)\n', 'MOD-DR-003.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-DR-004', '10ml比色管定容模块', 'HHM08B-010', '定容', '1.0', 'active', '唐宋', '2025/9/5', '定容', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"定容\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 10, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"比色管-10ml\", \"function_code\": 530, \"sub_functions\": [\"无\"], \"cycle_time_sec\": 60, \"operation_target\": \"10ml比色管\", \"operation_workflow\": \"载台移至上下料位 - 放入比色管- 移至加液位 - 气缸夹紧 - 加液口下降至加液位 - 加液 - 相机拍照 - 液面至刻度线齐平处停止加液- 称重 -加液口上升至初始位 - 气缸打开 - 载台移至上下料位 - 取下比色管\", \"repeat_accuracy_pct\": \"18mg\", \"function_description\": \"视觉定容\", \"absolute_accuracy_pct\": \"40mg\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.224, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.134, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-DR-004\", \"name\": \"10ml比色管定容模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"定容\", \"last_updated\": \"2025/9/5\", \"module_part_no\": \"HHM08B-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-DR-004\n  module_part_no: HHM08B-010\n  name: 10ml比色管定容模块\n  category: 定容\n  version: 1.0\n  status: active\n  last_updated: 2025/9/5\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 530\n  function_description: 视觉定容\n  operation_target: 10ml比色管\n  operation_workflow: 载台移至上下料位 - 放入比色管- 移至加液位 - 气缸夹紧 - 加液口下降至加液位 - 加液 - 相机拍照 - 液面至刻度线齐平处停止加液- 称重 -加液口上升至初始位 - 气缸打开 - 载台移至上下料位 - 取下比色管\n  absolute_accuracy_pct: 40mg\n  repeat_accuracy_pct: 18mg\n  cycle_time_sec: 60\n  consumables: 比色管-10ml\n  sub_functions: [无]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [定容]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.134\n  power_kva_peak: 0.224\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 10ml比色管定容模块\n\n## Purpose (用途说明)\n10ml 比色管定容模块是实验室样品前处理专用自动化设备，核心用于 10ml 比色管的精准自动加水定容，替代人工目视定容，保障实验精度与一致性，适配各类样品溶液定量制备场景\n\n## Typical Scenarios (典型应用场景)\n广泛用于环境监测、食品检测、化工、医药、科研实验室等领域，为水质、土壤、食品、化工原料等样品的比色分析、分光光度检测，提供精准定量的样品溶液。\n\n## Working Principle (工作原理)\n本模块由 PLC 控制，通过 Y 轴换工位、Z 轴控加液管升降，气缸固定比色管。电磁阀加水，视觉相机实时识别液面，液面与刻度线对齐即停，精度 ±0.1mm，自动完成夹紧、定容、下料全流程，替代人工，高效精准\n\n## Limits & Cautions (限制与注意事项)\n仅限 10ml 标准比色管，液体需透明、无沉淀气泡；环境需洁净、无强光振动。注意：避免腐蚀液体，定期清洁镜头与管路；严禁硬物碰撞，保持定位精度，防止漏水误检。\n\n## Remarks (备注)\n', 'MOD-DR-004.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-FY-001', '水质分样平台', 'HHM40Q-001', '分样', '1.0', 'active', '唐宋', '2026/4/24', '分液，分样', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"分液\", \"分样\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 850, \"height_mm\": 2055, \"length_mm\": 1200, \"weight_kg\": 348, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 6}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 1000, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"蠕动泵泵头软管\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"15ml比色管,25ml比色管,30mlPP瓶,50ml离心管,250ml锥型瓶,500ml培养瓶\", \"function_code\": 670, \"sub_functions\": [\"670-接样1(50ml离心管)移液\", \"671-接样2(比色管)移液\", \"672-接样3(比色管)移液\", \"673-接样4(锥形瓶)移液\", \"674-管路清洗\", \"675-500ml肖特瓶拆盖\", \"676-500ml肖特瓶装盖\", \"677-1#接样瓶装盖\", \"678-1接样瓶装盖\", \"680-2接样瓶拆盖\", \"681-2接样瓶装盖\", \"683-3接样瓶拆盖\", \"684-3接样瓶装盖\", \"686-4接样瓶拆盖\", \"687-4接样瓶装盖\", \"689-移液前准备\"], \"cycle_time_sec\": 180, \"operation_target\": \"15ml比色管,25ml比色管,30mlPP瓶,50ml离心管,250ml锥型瓶,500ml培养瓶,1000ml培养瓶\", \"operation_workflow\": \"初始化-根据感应器判断加水是否正常 / 来样瓶-来样瓶上样-扫码-拆盖-Y轴到吸液位置 / 接样瓶-接样瓶上样-扫码-拆盖-Y轴到接液位置 / 分液-吸液针到吸液位置-润洗管道-吸液-吐液针已到吐液位置-吐液-重复分样过程 / 下料-来样品拧盖-下料-接样瓶拧盖-下料 / 清洗-吸液针到洗针次-吐液针到洗针次-清洗\", \"repeat_accuracy_pct\": \"±2%\", \"function_description\": \"从来样瓶中抽取液体，通过出液针注入到多种的接样容器中，完成分样操作\", \"absolute_accuracy_pct\": \"±2%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 1.6, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 1, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-FY-001\", \"name\": \"水质分样平台\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"分样\", \"last_updated\": \"2026/4/24\", \"module_part_no\": \"HHM40Q-001\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-FY-001\n  module_part_no: HHM40Q-001\n  name: 水质分样平台\n  category: 分样\n  version: 1.0\n  status: active\n  last_updated: 2026/4/24\n  owner: 唐宋\nphysical_specs:\n  length_mm: 1200\n  width_mm: 850\n  height_mm: 2055\n  weight_kg: 348\n  module_slots: 6\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 1000\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 670\n  function_description: 从来样瓶中抽取液体，通过出液针注入到多种的接样容器中，完成分样操作\n  operation_target: 15ml比色管,25ml比色管,30mlPP瓶,50ml离心管,250ml锥型瓶,500ml培养瓶,1000ml培养瓶\n  operation_workflow: \"初始化-根据感应器判断加水是否正常 / 来样瓶-来样瓶上样-扫码-拆盖-Y轴到吸液位置 / 接样瓶-接样瓶上样-扫码-拆盖-Y轴到接液位置 / 分液-吸液针到吸液位置-润洗管道-吸液-吐液针已到吐液位置-吐液-重复分样过程 / 下料-来样品拧盖-下料-接样瓶拧盖-下料 / 清洗-吸液针到洗针次-吐液针到洗针次-清洗\"\n  absolute_accuracy_pct: ±2%\n  repeat_accuracy_pct: ±2%\n  cycle_time_sec: 180\n  consumables: 15ml比色管,25ml比色管,30mlPP瓶,50ml离心管,250ml锥型瓶,500ml培养瓶\n  sub_functions: [670-接样1(50ml离心管)移液, 671-接样2(比色管)移液, 672-接样3(比色管)移液, 673-接样4(锥形瓶)移液, 674-管路清洗, 675-500ml肖特瓶拆盖, 676-500ml肖特瓶装盖, 677-1#接样瓶装盖, 678-1接样瓶装盖, 680-2接样瓶拆盖, 681-2接样瓶装盖, 683-3接样瓶拆盖, 684-3接样瓶装盖, 686-4接样瓶拆盖, 687-4接样瓶装盖, 689-移液前准备]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 蠕动泵泵头软管\ntags_meta:\n  tags: [分液, 分样]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 1\n  power_kva_peak: 1.6\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 水质分样平台\n\n## Purpose (用途说明)\n用于液体样品的自动化精准分样，可适配带盖 / 无盖、大小规格接样容器，自动完成样品识别、定量分装、容器封盖及管路清洗，支持单一样品多分装，高效适配实验室或工业批量分样需求\n\n## Typical Scenarios (典型应用场景)\n长春工厂-智慧水质理化检测实验室\n\n## Working Principle (工作原理)\n依托多轴滑台、气动夹爪、旋转机构、蠕动泵及扫码组件协同运作，自动完成来样瓶扫码、拆盖、吸液，对接样容器分类完成扫码、拆盖 / 直放、精准定量注液、封盖，支持多样品配比分液，作业后自动洗针复位，全流程自动化流转。\n\n## Limits & Cautions (限制与注意事项)\n三个分液通道不能并发，需要一个一个完成\n\n## Remarks (备注)\n', 'MOD-FY-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-FY-002', '5m1离心管恒温振摇反应模块', 'HHM01J-005', '加热', '1.0', 'active', '唐宋', '2025/9/26', '恒温，振摇，反应', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"恒温\", \"振摇\", \"反应\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"二十四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 300, \"speed_rpm_min\": 0, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 90, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"温度传感器线路\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-5ml\", \"function_code\": 647, \"sub_functions\": [\"646-开盖停止平摇\", \"648启动预热\", \"649加热关闭\"], \"cycle_time_sec\": 3600, \"operation_target\": \"5ml离心管\", \"operation_workflow\": \"初始化-温度达到指定温度-加热底座移出 - 遮光盖打开 - 放入离心管 - 遮光盖关闭 -Y轴到平遥为止- 振摇 - 重复上料 -振摇时间到依此取出离心管-结束\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"(上下料完成)启动平摇并关盖\", \"absolute_accuracy_pct\": \"\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 0.94, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.564, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-FY-002\", \"name\": \"5m1离心管恒温振摇反应模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加热\", \"last_updated\": \"2025/9/26\", \"module_part_no\": \"HHM01J-005\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-FY-002\n  module_part_no: HHM01J-005\n  name: 5m1离心管恒温振摇反应模块\n  category: 加热\n  version: 1.0\n  status: active\n  last_updated: 2025/9/26\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"二十四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: 25\n  temperature_c_max: 90\n  speed_rpm_min: 0\n  speed_rpm_max: 300\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 647\n  function_description: (上下料完成)启动平摇并关盖\n  operation_target: 5ml离心管\n  operation_workflow: 初始化-温度达到指定温度-加热底座移出 - 遮光盖打开 - 放入离心管 - 遮光盖关闭 -Y轴到平遥为止- 振摇 - 重复上料 -振摇时间到依此取出离心管-结束\n  absolute_accuracy_pct: \"\"\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 3600\n  consumables: 离心管-5ml\n  sub_functions: [646-开盖停止平摇, 648启动预热, 649加热关闭]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 温度传感器线路\ntags_meta:\n  tags: [恒温, 振摇, 反应]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.564\n  power_kva_peak: 0.94\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# 5m1离心管恒温振摇反应模块\n\n## Purpose (用途说明)\n本模块为样品恒温混匀专用设备，适配 5ml 离心管，提供 24 通道并行处理，集成精准控温与平摇混匀功能，满足生物、化学样品恒温反应与混匀需求\n\n## Typical Scenarios (典型应用场景)\n该模块用于 5ml 离心管样品恒温振摇反应，提供 24 通道并行处理，控温室温至 60℃、精度 ±3℃，平摇转速 0–300rpm 可调。适配分子生物、临床检验、环境食品检测、生物制药等场景，满足核酸孵育、酶反应、样品混匀需求，自动化上下料，高效稳定、重复性好。\n\n## Working Principle (工作原理)\n加热控温 + 水平振摇，24 通道恒温混匀，实现样品自动孵育反应。\n\n## Limits & Cautions (限制与注意事项)\n本模块是面向实验室自动化的24 通道恒温混匀设备，专为 5ml 离心管设计，集成精准控温、水平振摇与自动上下料功能。控温范围室温至 60℃、精度 ±3℃，振摇转速 0–300rpm 可调，配合密闭遮光盖稳定反应环境。适配分子生物、临床检验、环境食品检测、生物制药等场景，满足核酸孵育、酶反应、样品混匀需求，自动化程度高、运行稳定、重复性好，助力实验室无人化高效作业。\n\n## Remarks (备注)\n', 'MOD-FY-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-GL-001', '2.5cc注射器过滤模块', 'HHM04M-002.5', '过滤', '1.0', 'active', '王志', '2026/2/6', '注射器过滤', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"注射器过滤\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 2.5, \"volume_ml_min\": 1, \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"注射针筒-2.5cc / 针式过滤器-25mm / 移液枪-1ml / 西林瓶接样瓶-2ml\", \"function_code\": 637, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 210, \"operation_target\": \"注射针筒-2.5cc / 针式过滤器-25mm / 西林瓶接样瓶-2ml\", \"operation_workflow\": \"搬臂移液枪从样品瓶吸样品液，注射泵往过滤器里打入空气，正压使样品液通过过滤器先排掉前面一部分清洗过滤器进行预过滤，然后再进行过滤，对滤后溶液进行接样收集\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"过滤启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.1636, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.09816, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-GL-001\", \"name\": \"2.5cc注射器过滤模块\", \"owner\": \"王志\", \"status\": \"active\", \"version\": 1.0, \"category\": \"过滤\", \"last_updated\": \"2026/2/6\", \"module_part_no\": \"HHM04M-002.5\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-GL-001\n  module_part_no: HHM04M-002.5\n  name: 2.5cc注射器过滤模块\n  category: 过滤\n  version: 1.0\n  status: active\n  last_updated: 2026/2/6\n  owner: 王志\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 2.5\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 637\n  function_description: 过滤启动\n  operation_target: \"注射针筒-2.5cc / 针式过滤器-25mm / 西林瓶接样瓶-2ml\"\n  operation_workflow: 搬臂移液枪从样品瓶吸样品液，注射泵往过滤器里打入空气，正压使样品液通过过滤器先排掉前面一部分清洗过滤器进行预过滤，然后再进行过滤，对滤后溶液进行接样收集\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 210\n  consumables: \"注射针筒-2.5cc / 针式过滤器-25mm / 移液枪-1ml / 西林瓶接样瓶-2ml\"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [注射器过滤]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.09816\n  power_kva_peak: 0.1636\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: true', '# 2.5cc注射器过滤模块\n\n## Purpose (用途说明)\n预期实现2.5cc 注射器过滤工艺，将样品液中杂质分离出来，回收得到纯清的液体\n\n## Typical Scenarios (典型应用场景)\n1、生物样本微量除菌除杂\n2、核酸 / 蛋白样品纯化前过滤\n3、试剂配制与缓冲液除菌过滤\n4、环境 / 食品微量样品前处理\n5、微量贵重样品保护过滤\n\n## Working Principle (工作原理)\n通过搬臂移液枪完成样品液精准加样；由注射泵向过滤器内泵入空气形成正压环境，驱动样品液在正压作用下穿过滤膜。先排出部分初滤液，实现滤器预冲洗与预过滤，去除滤器杂质、消除污染；后续继续正压过滤，最终收集经滤膜净化后的合格滤液。\n\n## Limits & Cautions (限制与注意事项)\n1、严禁运行中干预：设备运行时禁止伸手、触碰运动部件、打开防护，防止夹伤、漏液污染、设备损坏。\n2、定期校准：轴零点、注射泵流量、压力传感器、密封气缸行程需定期校准，防止定位不准、过滤失败、压力误报。\n3、密封件维护：O 型圈、密封板定期清洁、更换；老化会导致漏气、正压不足、过滤效率下降。\n4、滤膜更换：每批次更换新滤膜，防止交叉污染、堵塞；堵塞需及时停机更换，避免超压损坏。\n5、异常处理：压力报警、漏液、滴漏、位置异常时，先断电断气再处理，禁止带电排查。\n6、清洁要求：接触样品区域每次运行后清洁，防止残留结晶、污染样品、影响密封效果\n\n## Remarks (备注)\n', 'MOD-GL-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-GL-002', '5cc 针式过滤模块', 'HHM04J-005', '过滤', '1.0', 'active', '涂高祥', '2025/9/19', '针式过滤', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"针式过滤\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 5, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"加液电磁阀\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-15ml / 西林瓶-10ml / 离心管-2ml / 西林瓶-2ml / 针式过滤器-13mm\", \"function_code\": 310, \"sub_functions\": [\"251-清洗标针\"], \"cycle_time_sec\": 520, \"operation_target\": \"15ml离心管/10ml西林瓶，2ml西林瓶/2ml离心管，13mm针式过滤器\", \"operation_workflow\": \"初始化-载台移至上下料位-机械臂放入接样瓶-检测成功-机械臂放入针式过滤器-监测成功-机械臂放入样品瓶-检测成功-Y1轴载台移至取样位-注射泵吸液-Z2轴轴抬升-抽空气1ml / 预过滤-Y2轴移至过滤位-Y1轴原样瓶移至过滤位-Z2轴下降插入过滤器-过滤一定量样品至原样瓶-取样针Z2轴上升至安全位 / 过滤-接样瓶Y1轴移动到过滤位-过滤器Y2轴移动到过滤位-Z2轴下降插入过滤器-过滤剩余样品至接样瓶-取样针Z2轴上升至安全位 / 洗针-洗针池Y1轴移动到取样针正下方-注入洗针池3ml清洗剂-注射泵吸吐三次-排废-注入3ml纯水-注射泵吸吐三次-排废 / 空吹-注射泵吸满空气-空吹-取样针上升至安全位 / 下料-机械臂下料原样瓶-针式过滤器-接样品\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"启动针式过滤\", \"absolute_accuracy_pct\": \"\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.22, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.132, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-GL-002\", \"name\": \"5cc 针式过滤模块\", \"owner\": \"涂高祥\", \"status\": \"active\", \"version\": 1.0, \"category\": \"过滤\", \"last_updated\": \"2025/9/19\", \"module_part_no\": \"HHM04J-005\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-GL-002\n  module_part_no: HHM04J-005\n  name: 5cc 针式过滤模块\n  category: 过滤\n  version: 1.0\n  status: active\n  last_updated: 2025/9/19\n  owner: 涂高祥\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 5\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 310\n  function_description: 启动针式过滤\n  operation_target: 15ml离心管/10ml西林瓶，2ml西林瓶/2ml离心管，13mm针式过滤器\n  operation_workflow: \"初始化-载台移至上下料位-机械臂放入接样瓶-检测成功-机械臂放入针式过滤器-监测成功-机械臂放入样品瓶-检测成功-Y1轴载台移至取样位-注射泵吸液-Z2轴轴抬升-抽空气1ml / 预过滤-Y2轴移至过滤位-Y1轴原样瓶移至过滤位-Z2轴下降插入过滤器-过滤一定量样品至原样瓶-取样针Z2轴上升至安全位 / 过滤-接样瓶Y1轴移动到过滤位-过滤器Y2轴移动到过滤位-Z2轴下降插入过滤器-过滤剩余样品至接样瓶-取样针Z2轴上升至安全位 / 洗针-洗针池Y1轴移动到取样针正下方-注入洗针池3ml清洗剂-注射泵吸吐三次-排废-注入3ml纯水-注射泵吸吐三次-排废 / 空吹-注射泵吸满空气-空吹-取样针上升至安全位 / 下料-机械臂下料原样瓶-针式过滤器-接样品\"\n  absolute_accuracy_pct: \"\"\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 520\n  consumables: \"离心管-15ml / 西林瓶-10ml / 离心管-2ml / 西林瓶-2ml / 针式过滤器-13mm\"\n  sub_functions: [251-清洗标针]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 加液电磁阀\ntags_meta:\n  tags: [针式过滤]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.132\n  power_kva_peak: 0.22\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: true', '# 5cc 针式过滤模块\n\n## Purpose (用途说明)\n本模块为实验室样品前处理专用过滤设备，用于样品液精密过滤除杂，自动完成吸液、过滤、洗针、空吹全流程，适配微量样品净化需求。\n\n## Typical Scenarios (典型应用场景)\n广泛用于环境监测、食品检测、医药化工、科研实验室，适配水质、食品、生物样品、试剂溶液等过滤净化，为色谱、质谱分析提供洁净样品\n\n## Working Principle (工作原理)\n注射泵吸取样品液，注射泵套上针式过滤器，样品液通过针式过滤器进行过滤，对滤后溶液进行接样收集。\n\n## Limits & Cautions (限制与注意事项)\n清洗不彻底，活塞走到0位，注射器里还存在液体不能排出，排空气也不行\n\n## Remarks (备注)\n', 'MOD-GL-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-GL-003', '30ML过滤模块', 'HHM04A-030', '过滤', '1.0', 'active', '涂高祥', '2025/4/25', '过滤', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"过滤\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 30, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"定制过滤杯-30ml\", \"function_code\": 80, \"sub_functions\": [\"81-前后气缸伸出\", \"82-前后气缸缩回\"], \"cycle_time_sec\": 180, \"operation_target\": \"30ml定制过滤杯\", \"operation_workflow\": \"PP瓶载台移至上下料位 - 放入PP瓶 - 放入过滤杯 - 载台移至过滤位 - 压板下压 - 加压过滤 - 过滤完毕 - 压板上升 - 过滤杯载台移至上下料位 - 取下过滤杯 - PP瓶载台移至上下料位 - 取下PP瓶\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"过滤\", \"absolute_accuracy_pct\": \"\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.574, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.3444, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-GL-003\", \"name\": \"30ML过滤模块\", \"owner\": \"涂高祥\", \"status\": \"active\", \"version\": 1.0, \"category\": \"过滤\", \"last_updated\": \"2025/4/25\", \"module_part_no\": \"HHM04A-030\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-GL-003\n  module_part_no: HHM04A-030\n  name: 30ML过滤模块\n  category: 过滤\n  version: 1.0\n  status: active\n  last_updated: 2025/4/25\n  owner: 涂高祥\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 30\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 80\n  function_description: 过滤\n  operation_target: 30ml定制过滤杯\n  operation_workflow: PP瓶载台移至上下料位 - 放入PP瓶 - 放入过滤杯 - 载台移至过滤位 - 压板下压 - 加压过滤 - 过滤完毕 - 压板上升 - 过滤杯载台移至上下料位 - 取下过滤杯 - PP瓶载台移至上下料位 - 取下PP瓶\n  absolute_accuracy_pct: \"\"\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 180\n  consumables: 定制过滤杯-30ml\n  sub_functions: [81-前后气缸伸出, 82-前后气缸缩回]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [过滤]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.3444\n  power_kva_peak: 0.574\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 30ML过滤模块\n\n## Purpose (用途说明)\n30mlPP瓶的装载，过滤器的装载，实现往过滤器移样品后，微正压将样品透过滤膜，容器接收滤液的功能\n\n## Typical Scenarios (典型应用场景)\n盐湖所无机样品前处理系统\n\n## Working Principle (工作原理)\n模块通过 Y 轴滚珠丝杆电机实现PP 瓶与过滤筒的工位移动，光电传感器完成物料检测；气缸下压密封过滤筒后，以10kPa 微正压推动样品透过滤膜，实现固液分离；过滤完成后 Y 轴依次退回上下料位，完成滤筒与滤液瓶的自动出料，全程自动化运行。\n\n## Limits & Cautions (限制与注意事项)\n1、仅限30ml 标准 PP 瓶使用，过滤筒需匹配规格，禁止混用\n2、过滤前必须保证气缸压紧密封，防止微正压泄漏导致过滤失败。\n3、过滤气压严格控制在10kPa 左右，禁止超压导致漏液或爆膜。\n4、运行时严禁触碰Y 轴运动区、气缸下压区，避免夹伤与碰撞。\n\n## Remarks (备注)\n', 'MOD-GL-003.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-GS-001', '100ml石墨赶酸模块', 'HHM47A-100', '赶酸', '2.0', 'active', '汪健', '2025/9/5', '加液，拆装盖，加热赶酸，冷却，酸气排放', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液\", \"拆装盖，加热赶酸\", \"冷却\", \"酸气排放\"]}, \"peripherals\": {\"required_peripherals\": \"冷水机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"无\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"八工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 100, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 200, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液\"]}, \"process_capability_1\": {\"consumables\": \"消解管-100ml\", \"function_code\": 210, \"sub_functions\": [], \"cycle_time_sec\": 10800, \"operation_target\": \"100ml消解管\", \"operation_workflow\": \"石墨消解支座移至上下料位 - 消解管（8个）放入支座槽内 -支座移至前排加液位-加液-支座移至后排加液位-加液-支座移至赶酸工作位 - 防护罩下压与支座上端贴合 - 加热至200℃ - 恒温120分钟 - 持续排除酸雾 - 加热停止 - 冷却水开启 - 降温至室温 - 冷却水关闭 - 防护罩返回 - 石墨消解支座移至上下料位 - 取下消解管\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"石墨赶酸\", \"absolute_accuracy_pct\": \"±5%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 1.45, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.87, \"requires_ventilation\": true, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-GS-001\", \"name\": \"100ml石墨赶酸模块\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 2.0, \"category\": \"赶酸\", \"last_updated\": \"2025/9/5\", \"module_part_no\": \"HHM47A-100\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-GS-001\n  module_part_no: HHM47A-100\n  name: 100ml石墨赶酸模块\n  category: 赶酸\n  version: 2.0\n  status: active\n  last_updated: 2025/9/5\n  owner: 汪健\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"八工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 100\n  temperature_c_min: 25\n  temperature_c_max: 200\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 冷水机\nprocess_capability_1:\n  function_code: 210\n  function_description: 石墨赶酸\n  operation_target: 100ml消解管\n  operation_workflow: 石墨消解支座移至上下料位 - 消解管（8个）放入支座槽内 -支座移至前排加液位-加液-支座移至后排加液位-加液-支座移至赶酸工作位 - 防护罩下压与支座上端贴合 - 加热至200℃ - 恒温120分钟 - 持续排除酸雾 - 加热停止 - 冷却水开启 - 降温至室温 - 冷却水关闭 - 防护罩返回 - 石墨消解支座移至上下料位 - 取下消解管\n  absolute_accuracy_pct: ±5%\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 10800\n  consumables: 消解管-100ml\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [加液, 拆装盖，加热赶酸, 冷却, 酸气排放]\ndocumentation:\n  urs_url: 无\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.87\n  power_kva_peak: 1.45\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: true\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 100ml石墨赶酸模块\n\n## Purpose (用途说明)\n石墨赶酸模块是实验室样品前处理专用设备，核心用于消解管内样品的自动加液、高温加热赶酸、冷却排酸气全流程处理，适配元素分析等实验的样品消解预处理需求，提升实验效率与精度\n\n## Typical Scenarios (典型应用场景)\n石墨赶酸模块主要用于环境、地质、食品、化工、医药等实验室，对土壤、矿石、食品、材料等样品进行三酸消解 + 高温赶酸 + 自动排酸，为 ICP-MS/AAS/AFS 等仪器提供洁净、稳定、低空白的待测液，显著提升前处理效率与数据可靠性\n\n## Working Principle (工作原理)\n石墨赶酸模块本质是一套自动化、密闭式高温消解 + 赶酸 + 冷却排废系统，由三轴运动 + 加热系统 + 冷却系统 + 气路阀组 + 温控系统协同完成样品前处理\n\n## Limits & Cautions (限制与注意事项)\n石墨赶酸模块用于样品三酸消解、高温赶酸与冷却排废，自动化程度高、精度稳定。限制：最高 200℃、8 管通量，禁高氯酸 / 高爆样品。注意：强腐蚀高温风险，需通风防护、规范维护，严禁干烧与违规试剂\n\n## Remarks (备注)\n', 'MOD-GS-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HC-001', '50ml合成反应器模块-制热', 'HHM17A-050', '合成', '1.0', 'active', '唐宋', '2025/7/17', '合成反应', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"合成反应\"]}, \"peripherals\": {\"required_peripherals\": \"冷水机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 40, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": 200, \"temperature_c_min\": 26}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml斜二口烧瓶\", \"function_code\": 300, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 36000, \"operation_target\": \"50ml斜二口烧瓶\", \"operation_workflow\": \" 反应器治具达到设定温度 - 反应瓶放入治具 - 治具移至反应位 - 定位气缸夹紧反应瓶口 - 主口密封气缸下压 - 侧口密封气缸下压 - 抽真空至设定压力 - 通入氮气 - 重复3次 - 开始合成反应 - 添加反应试剂 - 反应完毕 - 停止吹氮气 - 停止加热 - 开启冷却吹气 - 反应器降至室温 - 冲洗冷凝管 - 密封气缸抬起 - 定位气缸松开瓶口 - 反应器治具移至上下料位 - 取下反应瓶；\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"启动制热反应\", \"absolute_accuracy_pct\": \"±1\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 0.65, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.36, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HC-001\", \"name\": \"50ml合成反应器模块-制热\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"合成\", \"last_updated\": \"2025/7/17\", \"module_part_no\": \"HHM17A-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HC-001\n  module_part_no: HHM17A-050\n  name: 50ml合成反应器模块-制热\n  category: 合成\n  version: 1.0\n  status: active\n  last_updated: 2025/7/17\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 40\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: 26\n  temperature_c_max: 200\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 冷水机\nprocess_capability_1:\n  function_code: 300\n  function_description: 启动制热反应\n  operation_target: 50ml斜二口烧瓶\n  operation_workflow: \" 反应器治具达到设定温度 - 反应瓶放入治具 - 治具移至反应位 - 定位气缸夹紧反应瓶口 - 主口密封气缸下压 - 侧口密封气缸下压 - 抽真空至设定压力 - 通入氮气 - 重复3次 - 开始合成反应 - 添加反应试剂 - 反应完毕 - 停止吹氮气 - 停止加热 - 开启冷却吹气 - 反应器降至室温 - 冲洗冷凝管 - 密封气缸抬起 - 定位气缸松开瓶口 - 反应器治具移至上下料位 - 取下反应瓶；\"\n  absolute_accuracy_pct: ±1\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 36000\n  consumables: 50ml斜二口烧瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [合成反应]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.36\n  power_kva_peak: 0.65\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 50ml合成反应器模块-制热\n\n## Purpose (用途说明)\n50ml斜二口玻璃瓶加热至200℃的合成反应器，本质上是一套\"微型有机合成工作站\"——主要用于小剂量有机合成反应、催化评价、反应条件优化，斜二口设计使其能同时实现控温+回流+通气，是制药、精细化工、新材料领域实验室最常用的小试反应装备之一\n\n## Typical Scenarios (典型应用场景)\n无\n\n## Working Principle (工作原理)\n通过电加热控温模块对斜二口玻璃反应瓶进行均匀加热，配合温度传感器实时采集瓶内 / 瓶壁温度，由控制系统自动调节加热功率，实现精准恒温、程序升温，为瓶内物料提供稳定高温反应环境，完成合成、催化、回流等化学反应\n\n## Limits & Cautions (限制与注意事项)\n这个模块最大的风险就两个：① 玻璃炸瓶（温差+暗伤），② 溶剂着火（没通N₂+没接冷凝管就加热）。只要记住\"干瓶慢升温、先通气再加热、先冷却水再开火、全程有人看\"，就能安全使用\n\n## Remarks (备注)\n', 'MOD-HC-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HC-002', '50ml合成反应制冷反应器模块', 'HHM17A-050', '合成', '1.0', 'active', '唐宋', '2025/9/12', '制冷合成反应，磁力搅拌', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"制冷合成反应\", \"磁力搅拌\"]}, \"peripherals\": {\"required_peripherals\": \"冷水机,空压机，氮气瓶\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 35, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 2000, \"speed_rpm_min\": 100, \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": 25, \"temperature_c_min\": -20}, \"delivery_maintenance\": {\"wear_parts\": \"半导体制冷片\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液\"]}, \"process_capability_1\": {\"consumables\": \"两口反应瓶-50ml\", \"function_code\": 301, \"sub_functions\": [], \"cycle_time_sec\": 36000, \"operation_target\": \"50ml两口反应瓶\", \"operation_workflow\": \"冷却循环水开启 - 反应器治具达到设定温度 - 反应瓶放入治具 - 治具移至反应位 - 定位气缸夹紧反应瓶口 - 主口密封气缸下压 - 侧口密封气缸下压 - 抽真空至设定压力 - 通入氮气 - 重复3次 -冷却循环水开启 - 反应器治具达到设定温度 开始合成反应 - 添加反应试剂 - 反应完毕 - 停止吹氮气 - 停止加热 - 开启冷却吹气 - 反应器降至室温 - 冲洗冷凝管 - 密封气缸抬起 - 定位气缸松开瓶口 - 反应器治具移至上下料位 - 取下反应瓶\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"制冷合成反应\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 1.065, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.639, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HC-002\", \"name\": \"50ml合成反应制冷反应器模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"合成\", \"last_updated\": \"2025/9/12\", \"module_part_no\": \"HHM17A-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HC-002\n  module_part_no: HHM17A-050\n  name: 50ml合成反应制冷反应器模块\n  category: 合成\n  version: 1.0\n  status: active\n  last_updated: 2025/9/12\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 35\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: -20\n  temperature_c_max: 25\n  speed_rpm_min: 100\n  speed_rpm_max: 2000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 冷水机,空压机，氮气瓶\nprocess_capability_1:\n  function_code: 301\n  function_description: 制冷合成反应\n  operation_target: 50ml两口反应瓶\n  operation_workflow: 冷却循环水开启 - 反应器治具达到设定温度 - 反应瓶放入治具 - 治具移至反应位 - 定位气缸夹紧反应瓶口 - 主口密封气缸下压 - 侧口密封气缸下压 - 抽真空至设定压力 - 通入氮气 - 重复3次 -冷却循环水开启 - 反应器治具达到设定温度 开始合成反应 - 添加反应试剂 - 反应完毕 - 停止吹氮气 - 停止加热 - 开启冷却吹气 - 反应器降至室温 - 冲洗冷凝管 - 密封气缸抬起 - 定位气缸松开瓶口 - 反应器治具移至上下料位 - 取下反应瓶\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 36000\n  consumables: 两口反应瓶-50ml\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 半导体制冷片\ntags_meta:\n  tags: [制冷合成反应, 磁力搅拌]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.639\n  power_kva_peak: 1.065\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 50ml合成反应制冷反应器模块\n\n## Purpose (用途说明)\n本模块是有机合成与精细化工自动化前处理设备，专为50ml 两口反应瓶设计，集成低温制冷、真空氮气置换、磁力搅拌、密闭反应功能，实现无氧低温合成反应自动化，保障反应可控、安全、高效。\n\n## Typical Scenarios (典型应用场景)\n广泛用于有机合成实验室、医药中间体研发、精细化工、新材料合成、高校科研院所，适配低温加成、缩合、氧化还原、格氏反应等需无氧低温环境的合成工艺。\n\n## Working Principle (工作原理)\n利用制冷（低温）把反应产物冷凝 / 液化分离，同时用制冷循环的余热预热原料，让合成反应在 “反应 — 制冷分离 — 预热循环” 下连续、低能耗进行。\n\n## Limits & Cautions (限制与注意事项)\n1.低温操作需佩戴防冻手套，防止冻伤；严禁触碰制冷台面。\n2.密封前确认瓶口干净无破损，避免漏气、漏液。\n3.外接氮气、真空、冷却水需符合规格，定期检查管路密封性\n4.运行中严禁开盖、触碰运动部件，防止夹伤、喷溅。\n5.定期清洁密封件、校准温度与压力，避免老化失效。\n6.强腐蚀、易结晶、高粘度液体慎用，易损坏制冷与密封组件\n\n## Remarks (备注)\n', 'MOD-HC-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HY-001', '10ml西林瓶加液混匀模块', 'HHM23H-010', '混匀', '1.0', 'active', '汪健', '2025/7/25', '加液，混匀', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液，混匀\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 0, \"volume_ml_max\": 10, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"涡旋电机\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"10ml西林瓶\", \"function_code\": 560, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 100, \"operation_target\": \"10ml西林瓶\", \"operation_workflow\": \"西林瓶座移至上下料位 - 机械臂从托盘取西林瓶放入瓶座 - 瓶座移至加液位 - 气缸下压 - 加液 - 气缸抬起 - 西林瓶座移至混匀位 - 气缸下压压紧瓶口 - 混匀 - 停止 - 气缸抬起 - 西林瓶座移至上下料位 - 机械臂取下西林瓶放入托盘\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"加液混匀\", \"absolute_accuracy_pct\": \"±1\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.22, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.13, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HY-001\", \"name\": \"10ml西林瓶加液混匀模块\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 1.0, \"category\": \"混匀\", \"last_updated\": \"2025/7/25\", \"module_part_no\": \"HHM23H-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HY-001\n  module_part_no: HHM23H-010\n  name: 10ml西林瓶加液混匀模块\n  category: 混匀\n  version: 1.0\n  status: active\n  last_updated: 2025/7/25\n  owner: 汪健\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 0\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 560\n  function_description: 加液混匀\n  operation_target: 10ml西林瓶\n  operation_workflow: 西林瓶座移至上下料位 - 机械臂从托盘取西林瓶放入瓶座 - 瓶座移至加液位 - 气缸下压 - 加液 - 气缸抬起 - 西林瓶座移至混匀位 - 气缸下压压紧瓶口 - 混匀 - 停止 - 气缸抬起 - 西林瓶座移至上下料位 - 机械臂取下西林瓶放入托盘\n  absolute_accuracy_pct: ±1\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 100\n  consumables: 10ml西林瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 涡旋电机\ntags_meta:\n  tags: [加液，混匀]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.13\n  power_kva_peak: 0.22\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 10ml西林瓶加液混匀模块\n\n## Purpose (用途说明)\n这是一套专为10ml西林瓶设计的\"精确加液 + 振荡混匀\"自动化模块，核心解决的是小体积（10ml级别）药液/试剂/生物样品的\"精确配制 + 快速混匀\"问题\n\n## Typical Scenarios (典型应用场景)\n10ml西林瓶加液混匀模块的应用场景 = 静配中心（量最大）+ 药物研发（精度要求最高）+ CGT生物制药（合规要求最高）+ 微生物/疾控（换型最频繁）+ 分析质控（防污染最严）+ 小批量试产（灵活性最高），六大场景的共同核心需求是：手工加液不准、振荡不匀、交叉污染、产气反应危险——这四个痛点，模块一个不留全部解决\n\n## Working Principle (工作原理)\n加液原理：靠气体压力把液体压出，实现定量加注\n\n混匀原理：西林瓶定位固定后，模块通过旋转混匀带动瓶内液体快速混合，使试剂充分溶解、反应、均一。\n\n## Limits & Cautions (限制与注意事项)\n10ml西林瓶加液混匀模块的限制 = 灌装≤8.5ml（起泡≤8.0ml）+ 混匀500~3000rpm + 精度±0.5% ；注意事项的核心 = 防炸瓶、防污染、防交叉污染（一次性+密封）、防失控。记住：这个模块最大的二个杀手是 ① 灌太满 → 灭菌炸瓶 ② 产气不排气\n\n## Remarks (备注)\n', 'MOD-HY-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HY-002', '50-250ml容量瓶翻转摇匀模块', 'HHM01C-904', '混匀', '1.0', 'active', '唐宋', '2026/4/17', '翻转，摇匀，容量瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"翻转\", \"摇匀\", \"容量瓶\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": -50, \"speed_rpm_max\": 650, \"speed_rpm_min\": 300, \"volume_ml_max\": 250, \"volume_ml_min\": 50, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"夹爪包胶\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\", \"function_code\": 500, \"sub_functions\": [], \"cycle_time_sec\": 8, \"operation_target\": \"50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\", \"operation_workflow\": \"放入容量瓶- 真空发生器打开 - 真空吸嘴吸住容量瓶 - 容量瓶升至等待位 - 夹紧手指移至夹料位 - 容量瓶升至夹料位 - 夹紧 - 真空发生器关闭 - 容量瓶移至翻转位 - 翻转180° - 停顿 - 返回0° - 停顿 - 重复翻转、停顿、返回和停顿动作至翻转摇匀周期 - 容量瓶移至夹料位 - 手指松开 - 容量瓶下降至等待位 - 等待Y轴退回避让位 - 容量瓶下降至上下料位 - 取下容量瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"容量瓶翻转/摇匀\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.39, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.23, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HY-002\", \"name\": \"50-250ml容量瓶翻转摇匀模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"混匀\", \"last_updated\": \"2026/4/17\", \"module_part_no\": \"HHM01C-904\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HY-002\n  module_part_no: HHM01C-904\n  name: 50-250ml容量瓶翻转摇匀模块\n  category: 混匀\n  version: 1.0\n  status: active\n  last_updated: 2026/4/17\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 50\n  volume_ml_max: 250\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 300\n  speed_rpm_max: 650\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: -50\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 500\n  function_description: 容量瓶翻转/摇匀\n  operation_target: 50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\n  operation_workflow: 放入容量瓶- 真空发生器打开 - 真空吸嘴吸住容量瓶 - 容量瓶升至等待位 - 夹紧手指移至夹料位 - 容量瓶升至夹料位 - 夹紧 - 真空发生器关闭 - 容量瓶移至翻转位 - 翻转180° - 停顿 - 返回0° - 停顿 - 重复翻转、停顿、返回和停顿动作至翻转摇匀周期 - 容量瓶移至夹料位 - 手指松开 - 容量瓶下降至等待位 - 等待Y轴退回避让位 - 容量瓶下降至上下料位 - 取下容量瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 8\n  consumables: 50ml容量瓶,100ml容量瓶,200ml容量瓶,250ml容量瓶\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 夹爪包胶\ntags_meta:\n  tags: [翻转, 摇匀, 容量瓶]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.23\n  power_kva_peak: 0.39\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50-250ml容量瓶翻转摇匀模块\n\n## Purpose (用途说明)\n本模块用于25～200ml 标准容量瓶的自动化上下料与180° 往复翻转摇匀，替代人工摇晃，实现溶液快速混匀、标准化处理，适配化学分析前处理流程\n\n## Typical Scenarios (典型应用场景)\n1、标准溶液配制后混匀\n2、样品定容后均质混匀\n3、难溶物质充分混合\n\n\n## Working Principle (工作原理)\n本模块依靠三轴运动 + 真空吸附 + 气动夹持 + 旋转驱动，实现容量瓶自动上下料与 180° 往复翻转摇匀\n\n## Limits & Cautions (限制与注意事项)\n上料放置：容量瓶直立放稳、瓶塞盖紧，真空吸附到位后再启动。\n2. 夹持调整：手指气缸夹紧力度适中，过紧夹碎、过松脱落。\n3. 参数设置：转速、时间按样品适配，低速启动、避免液体飞溅。\n4. 运行安全：运行中严禁伸手靠近翻转区、夹爪、运动部件。\n5. 日常维护：定期清洁吸嘴、夹爪；检查真空管路、气缸动作；长期不用断电关气\n\n## Remarks (备注)\n', 'MOD-HY-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HY-003', '25-200ml容量瓶翻转摇匀模块', 'HHM01C-901', '混匀', '3.0', 'active', '黄锐', '2025/8/8', '翻转摇匀、定容平台', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"翻转摇匀、定容平台\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": -50, \"speed_rpm_max\": 1000, \"speed_rpm_min\": 100, \"volume_ml_max\": 200, \"volume_ml_min\": 25, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"自动化称量模块\"], \"dependencies\": [], \"typical_pairings\": [\"25-200ml容量瓶加液定容模块\"]}, \"process_capability_1\": {\"consumables\": \"25ml容量瓶/50ml容量瓶/100ml容量瓶/200ml容量瓶\", \"function_code\": 500, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 10, \"operation_target\": \"25ml容量瓶/50ml容量瓶/100ml容量瓶/200ml容量瓶\", \"operation_workflow\": \"上料：1个带盖带样品的25/50/100/200ml容量瓶；翻转摇匀：拿起带料容量瓶，顶塞、托底，反复倒立颠摇 10～15 次； / 每次倒立停留 2～3 秒，确保上下完全混匀；下料：1个带盖带样品的25/50/100/200ml容量瓶；\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"兼容25ml-200ml容量瓶的上下料、翻转摇匀功能\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.156, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.09, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HY-003\", \"name\": \"25-200ml容量瓶翻转摇匀模块\", \"owner\": \"黄锐\", \"status\": \"active\", \"version\": 3.0, \"category\": \"混匀\", \"last_updated\": \"2025/8/8\", \"module_part_no\": \"HHM01C-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HY-003\n  module_part_no: HHM01C-901\n  name: 25-200ml容量瓶翻转摇匀模块\n  category: 混匀\n  version: 3.0\n  status: active\n  last_updated: 2025/8/8\n  owner: 黄锐\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 25\n  volume_ml_max: 200\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 100\n  speed_rpm_max: 1000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: -50\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 500\n  function_description: 兼容25ml-200ml容量瓶的上下料、翻转摇匀功能\n  operation_target: 25ml容量瓶/50ml容量瓶/100ml容量瓶/200ml容量瓶\n  operation_workflow: \"上料：1个带盖带样品的25/50/100/200ml容量瓶；翻转摇匀：拿起带料容量瓶，顶塞、托底，反复倒立颠摇 10～15 次； / 每次倒立停留 2～3 秒，确保上下完全混匀；下料：1个带盖带样品的25/50/100/200ml容量瓶；\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 10\n  consumables: 25ml容量瓶/50ml容量瓶/100ml容量瓶/200ml容量瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    - 自动化称量模块\n  typical_pairings:\n    - 25-200ml容量瓶加液定容模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [翻转摇匀、定容平台]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.09\n  power_kva_peak: 0.156\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 25-200ml容量瓶翻转摇匀模块\n\n## Purpose (用途说明)\n用于容量瓶定容后的翻转摇匀操作\n\n## Typical Scenarios (典型应用场景)\n理化检测、水质分析、中药理化、化工标液配制、实验室全自动样品前处理线，配套定容模块、液体转移模块组成完整自动化定容摇匀流水线\n\n## Working Principle (工作原理)\n防洒液原理、兼容多规格原理、均质混匀原理、平稳控速原理\n\n## Limits & Cautions (限制与注意事项)\n仅支持 25–200ml 标准容量瓶，固定 2 通道并行；仅做 360° 翻转摇匀，不可变速或改角度。DC24V 供电、总功率 156W，依赖机械手上下料；仅适配标准瓶型，禁异形 / 破损瓶，夹紧力需匹配，防滑落，安装需水平，定期校准传感器与气缸\n\n## Remarks (备注)\n', 'MOD-HY-003.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-HY-004', '250ml锥形瓶加液混匀模块', 'HHM01H-250', '混匀', '1.0', 'active', '许云燕', '2025/8/29', '加液混匀、磁力子搅拌', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液混匀、磁力子搅拌\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 500, \"speed_rpm_min\": 100, \"volume_ml_max\": 250, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"250ml锥形瓶、磁力子\", \"function_code\": 610, \"sub_functions\": [\"搅拌\"], \"cycle_time_sec\": 252, \"operation_target\": \"250ml锥形瓶，磁力子 \", \"operation_workflow\": \"上料：两个带盖的250ml锥形瓶； / 拆盖：逆时针旋转盖子拧开； / 加液：往锥形瓶加入试剂，加入体积可设置； / 装盖：顺时针拧紧盖子； / 下料：两个带盖的250ml锥形瓶；\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"实现250ml锥形瓶的拆盖、加液（包括温水、酸性溶液、碱性溶液）、混匀的操作\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.7, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.42, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-HY-004\", \"name\": \"250ml锥形瓶加液混匀模块\", \"owner\": \"许云燕\", \"status\": \"active\", \"version\": 1.0, \"category\": \"混匀\", \"last_updated\": \"2025/8/29\", \"module_part_no\": \"HHM01H-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-HY-004\n  module_part_no: HHM01H-250\n  name: 250ml锥形瓶加液混匀模块\n  category: 混匀\n  version: 1.0\n  status: active\n  last_updated: 2025/8/29\n  owner: 许云燕\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 250\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 100\n  speed_rpm_max: 500\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 610\n  function_description: 实现250ml锥形瓶的拆盖、加液（包括温水、酸性溶液、碱性溶液）、混匀的操作\n  operation_target: \"250ml锥形瓶，磁力子 \"\n  operation_workflow: \"上料：两个带盖的250ml锥形瓶； / 拆盖：逆时针旋转盖子拧开； / 加液：往锥形瓶加入试剂，加入体积可设置； / 装盖：顺时针拧紧盖子； / 下料：两个带盖的250ml锥形瓶；\"\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 252\n  consumables: 250ml锥形瓶、磁力子\n  sub_functions: [搅拌]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [加液混匀、磁力子搅拌]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.42\n  power_kva_peak: 0.7\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 250ml锥形瓶加液混匀模块\n\n## Purpose (用途说明)\n适配 250ml 标准锥形瓶，自动完成拆盖、多通道加液（温水 / 酸碱液）、磁力混匀、装盖全流程。用于样品前处理、试剂配制、反应体系制备、萃取 / 消解预处理等场景，实现标准化自动化操作，减少人工误差、降低污染风险，适配实验室高通量处理\n\n## Typical Scenarios (典型应用场景)\n1、食品检测：农残 / 重金属样品消解前自动加酸、混匀预处理；\n2、环境监测：水样 / 土壤样品加提取液、恒温混匀；\n3、医药化工：中间体配制、反应液酸碱调节与混匀；\n4、科研实验：多组分试剂配比、缓冲液配制、样品稀释混匀\n\n## Working Principle (工作原理)\n由 Y 轴移栽、Z 轴拆盖、6 通道加液、磁力混匀及压紧组件构成。Y 轴将瓶移至拆盖位，气缸压紧，Z 轴旋转拆盖；再移至加液位，多通道定量加液；底部磁力机构旋转混匀；最后回位装盖，完成自动化流程\n\n## Limits & Cautions (限制与注意事项)\n仅适配标准 250ml 锥形瓶，非标 / 异形瓶不可用；可加温水、稀酸碱液，禁强腐蚀、高粘度、易结晶 / 易燃易爆液体。磁力混匀力度固定，不适用含大量固体颗粒样品；DC24V 供电、依赖稳定气源，安装需水平，定期校准夹爪、管路与传感器。\n\n## Remarks (备注)\n', 'MOD-HY-004.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JB-001', '250m1锥形瓶恒温磁力搅拌模块', 'HHM23L-250', '搅拌', '1.0', 'active', '唐宋', '2025/7/18', '恒温，磁力搅拌', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"恒温，磁力搅拌\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 2000, \"speed_rpm_min\": 1, \"volume_ml_max\": 250, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": 80, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"250ml锥形瓶 / \", \"function_code\": 590, \"sub_functions\": [\"591-搅拌中途上料 592-预热开启 593-预热关闭\"], \"cycle_time_sec\": \"\", \"operation_target\": \"250ml锥形瓶\", \"operation_workflow\": \"初始化加热至设定温度-载台移至上下料位 - 机械手放入一组锥形瓶 - 移动至搅拌位 - 搅拌电机工作开始搅拌 -到达设定时间- 移动至上下料位 - 机械手放入第二组锥形瓶-移动至搅拌位 - 搅拌电机工作开始搅拌 -到达设定时间- 移动至上下料位 -依次取下锥形瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"搅拌启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 48, \"power_kva_peak\": 0.8, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.5, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JB-001\", \"name\": \"250m1锥形瓶恒温磁力搅拌模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"搅拌\", \"last_updated\": \"2025/7/18\", \"module_part_no\": \"HHM23L-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JB-001\n  module_part_no: HHM23L-250\n  name: 250m1锥形瓶恒温磁力搅拌模块\n  category: 搅拌\n  version: 1.0\n  status: active\n  last_updated: 2025/7/18\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 250\n  temperature_c_min: 25\n  temperature_c_max: 80\n  speed_rpm_min: 1\n  speed_rpm_max: 2000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 590\n  function_description: 搅拌启动\n  operation_target: 250ml锥形瓶\n  operation_workflow: 初始化加热至设定温度-载台移至上下料位 - 机械手放入一组锥形瓶 - 移动至搅拌位 - 搅拌电机工作开始搅拌 -到达设定时间- 移动至上下料位 - 机械手放入第二组锥形瓶-移动至搅拌位 - 搅拌电机工作开始搅拌 -到达设定时间- 移动至上下料位 -依次取下锥形瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: \"\"\n  consumables: \"250ml锥形瓶 / \"\n  sub_functions: [591-搅拌中途上料\n592-预热开启\n593-预热关闭]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [恒温，磁力搅拌]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.5\n  power_kva_peak: 0.8\n  voltage_v: 48\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 250m1锥形瓶恒温磁力搅拌模块\n\n## Purpose (用途说明)\n这是一套专为250ml锥形瓶设计的\"恒温加热 + 磁力搅拌\"集成模块，核心解决的是中大量（100~250ml）液体反应的\"精确控温 + 均匀混合\"问题，是有机合成、生物制药、分析检测领域最常用的基础反应装备之一。\n\n## Typical Scenarios (典型应用场景)\n250ml锥形瓶恒温磁力搅拌模块的典型案例 = 教学（蓝瓶子）+ 生物（酶催化37℃±0.3℃）+ 材料（环氧树脂300cP不跳磁）+ 有机合成（异丙醇20min提纯/己二酸45℃控温）+ 化工中试（50℃收率+15%）+ 分析检测（RSD≤0.3%），核心解决的是手工做不到的\"精度（±0.5℃）+ 均匀度（CV≤3%）+ 平行对比（6工位）+ 高粘度不跳磁\"四大难题\n\n## Working Principle (工作原理)\n250ml锥形瓶恒温磁力搅拌模块的工作原理 = 直流无刷电机产生旋转磁场 → PTFE钕铁硼搅拌子无接触同步旋转（100~1500rpm，CV≤3%）+PID算法动态调节功率 → 维持±0.5℃恒温，两大系统通过\"搅拌消除温差→测温准确→控温精准\"形成正向闭环\n\n## Limits & Cautions (限制与注意事项)\n250ml锥形瓶恒温磁力搅拌模块的限制 = 液量50~167ml（2/3以内）+ 温度≤80℃ + 转速100~1500rpm + 升温≤5℃/min + 不搅拌不加热 + 70℃以上≤2小时；注意事项的核心 = 防炸瓶（温差控制+不空烧）、防跳磁（低速启动+匹配搅拌子）、防触电（三孔接地）、记住：这个模块最大的三个杀手是 ① 不搅拌就加热 → 炸瓶 ② 高速直接启动 → 跳磁打瓶 ③ 液量超过2/3 → 沸腾溢出\n\n## Remarks (备注)\n', 'MOD-JB-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
