 noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 150ml面包瓶拔塞加液模块\n\n## Purpose (用途说明)\n150ml面包瓶拔塞，加液\n\n## Typical Scenarios (典型应用场景)\n中烟项目\n\n## Working Principle (工作原理)\n\n\n## Limits & Cautions (限制与注意事项)\n150ml面包瓶加工精度影响，会影响拆合盖成功率，需要对面包瓶做检查\n\n## Remarks (备注)\n', 'MOD-JY-001.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-002', '250ml锥形瓶加磁力搅拌子模块', 'HHM23K-250', '搅拌', '1.0', 'active', '汪健', '2025/10/17', '加液，加磁力子，搅拌', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液\", \"加磁力子\", \"搅拌\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 1000, \"speed_rpm_min\": 100, \"volume_ml_max\": 250, \"volume_ml_min\": 0, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"U型光电\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"锥形瓶-250ml\", \"function_code\": 610, \"sub_functions\": [\"611-拆盖/加液/装盖\", \"612-磁力子弹夹更换完成\"], \"cycle_time_sec\": 582, \"operation_target\": \"250ml锥形瓶\", \"operation_workflow\": \"载台移至上下料位 - 放入锥形瓶/ 搅拌子弹夹 - Y轴移动至取搅拌子位  -X轴移动到取搅拌子位置- 夹爪夹紧取搅拌子 - 前Z轴回至最高点零位-Y轴移动至拆盖位 - 拆盖 - Y轴移动至放搅拌子位 -前Z轴X轴移动放搅拌子伟- 前Z轴夹爪松开放搅拌子 - Y轴移动至装盖位 - 装盖 -Y轴 移动至下料位 - 机械臂取下锥形瓶/弹夹\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"拆盖/加液/加磁力子/混匀/装盖\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.7, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.42, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-JY-002\", \"name\": \"250ml锥形瓶加磁力搅拌子模块\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 1.0, \"category\": \"搅拌\", \"last_updated\": \"2025/10/17\", \"module_part_no\": \"HHM23K-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-002\n  module_part_no: HHM23K-250\n  name: 250ml锥形瓶加磁力搅拌子模块\n  category: 搅拌\n  version: 1.0\n  status: active\n  last_updated: 2025/10/17\n  owner: 汪健\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 250\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 100\n  speed_rpm_max: 1000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 610\n  function_description: 拆盖/加液/加磁力子/混匀/装盖\n  operation_target: 250ml锥形瓶\n  operation_workflow: 载台移至上下料位 - 放入锥形瓶/ 搅拌子弹夹 - Y轴移动至取搅拌子位  -X轴移动到取搅拌子位置- 夹爪夹紧取搅拌子 - 前Z轴回至最高点零位-Y轴移动至拆盖位 - 拆盖 - Y轴移动至放搅拌子位 -前Z轴X轴移动放搅拌子伟- 前Z轴夹爪松开放搅拌子 - Y轴移动至装盖位 - 装盖 -Y轴 移动至下料位 - 机械臂取下锥形瓶/弹夹\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 582\n  consumables: 锥形瓶-250ml\n  sub_functions: [611-拆盖/加液/装盖, 612-磁力子弹夹更换完成]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: U型光电\ntags_meta:\n  tags: [加液, 加磁力子, 搅拌]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.42\n  power_kva_peak: 0.7\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# 250ml锥形瓶加磁力搅拌子模块\n\n## Purpose (用途说明)\n完成锥形瓶拆盖，加液，自动加磁力子搅拌，将样品与试剂混匀\n\n## Typical Scenarios (典型应用场景)\n食品5009\n\n## Working Principle (工作原理)\n三轴联动 + 拆盖投子 + 多通道加液 + 磁力搅拌，实现锥形瓶全自动前处理。\n\n## Limits & Cautions (限制与注意事项)\n本模块为实验室自动化前处理设备，适配 250ml 锥形瓶，双工位并行作业，自动完成拆盖、投放磁力子、6 通道精准加液与磁力混匀。加液范围 10–100ml、精度 ±2%，搅拌转速 300–8000rpm 可调。广泛应用于环境、食品、化工、医药等领域，实现样品前处理全流程自动化，高效稳定、减少人工误差，助力实验室智能化升级\n\n## Remarks (备注)\n', 'MOD-JY-002.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
