compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 150ml锥形瓶加液\n\n## Purpose (用途说明)\n载台移至上下料位 - 机械臂从托盘取出锥形瓶 - 锥形瓶放入载台 - 载台移至加液位 - 加液口下降至加液位 - 排气开启 - 加液 - 停止 - 排气关闭（延迟）- 载台移至上下料位 - 机械臂取下锥形瓶 - 放入托盘 - 等待30min - 机械臂从托盘取出锥形瓶 - 锥形瓶放入载台 - 载台移至加液位 - 加液口下降至加液位 - 排气开启 - 加液 - 停止 - 排气关闭（延迟）- 载台移至上下料位 - 机械臂取下锥形瓶 - 放入托盘；\n\n## Typical Scenarios (典型应用场景)\n食品/环境/药品/工业检测中的酸消解前处理是本模块的核心战场——两组150ml锥形瓶 + 两种5ml酸液精确加液（±0.1ml）+ 30分钟间隔分步加液，专为需要标准酸消解流程的自动化实验室设计，是样品前处理链路中的加酸核心环节\n\n## Working Principle (工作原理)\n模块通过 Z轴+Y轴双轴联动，配合中航电磁阀精确控制流量，实现两组150ml锥形瓶的两种5ml酸液（硝酸-高氯酸混合液 / 盐酸溶液）分步定量加液，精度±0.1ml\n\n## Limits & Cautions (限制与注意事项)\n只认150ml锥形瓶、只准±0.1ml、必须等30分钟\n\n## Remarks (备注)\n', 'MOD-JY-003.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-004', '萃取瓶加内标模块', 'HHM10G-002', '加液', '1.0', 'active', '宾俊', '2025/11/17', '加内标，西林瓶，萃取瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加内标，西林瓶，萃取瓶\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 0.1, \"volume_ml_min\": 0.01, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"注射器\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"萃取瓶-250ml / 萃取瓶-500ml / 萃取瓶-1250ml / 西林瓶-2ml / 西林瓶-10ml\", \"function_code\": 250, \"sub_functions\": [\"250 加内标\"], \"cycle_time_sec\": 135, \"operation_target\": \"250ml萃取瓶，500ml萃取瓶，1250ml萃取瓶，2ml西林瓶，10ml西林瓶\", \"operation_workflow\": \"定位治具移至上下料位 - 放入萃取瓶/内标瓶 - 定位治具移至加内标品位 - 加标针对准内标瓶 - 加标针降至吸内标位 - 吸取内标准品 - 加标针上升 - 加标针对准萃取瓶 - 加标针降至加内标位 - 加内标准品 - 加标针上升 - 加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加纯水清洗加标针 - 排废液 - 注射泵排空（两次）-加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针- 排废液 - 注射泵排空（两次）-  加标针上升 - 定位治具移至上下料位 - 取下萃取瓶/内标瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"加内标\", \"absolute_accuracy_pct\": \"±2%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.424, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.2544, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-JY-004\", \"name\": \"萃取瓶加内标模块\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/11/17\", \"module_part_no\": \"HHM10G-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-004\n  module_part_no: HHM10G-002\n  name: 萃取瓶加内标模块\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/11/17\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.01\n  volume_ml_max: 0.1\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 250\n  function_description: 加内标\n  operation_target: 250ml萃取瓶，500ml萃取瓶，1250ml萃取瓶，2ml西林瓶，10ml西林瓶\n  operation_workflow: 定位治具移至上下料位 - 放入萃取瓶/内标瓶 - 定位治具移至加内标品位 - 加标针对准内标瓶 - 加标针降至吸内标位 - 吸取内标准品 - 加标针上升 - 加标针对准萃取瓶 - 加标针降至加内标位 - 加内标准品 - 加标针上升 - 加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加纯水清洗加标针 - 排废液 - 注射泵排空（两次）-加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针- 排废液 - 注射泵排空（两次）-  加标针上升 - 定位治具移至上下料位 - 取下萃取瓶/内标瓶\n  absolute_accuracy_pct: ±2%\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 135\n  consumables: \"萃取瓶-250ml / 萃取瓶-500ml / 萃取瓶-1250ml / 西林瓶-2ml / 西林瓶-10ml\"\n  sub_functions: [250 加内标]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 注射器\ntags_meta:\n  tags: [加内标，西林瓶，萃取瓶]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.2544\n  power_kva_peak: 0.424\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: true', '# 萃取瓶加内标模块\n\n## Purpose (用途说明)\nURD萃取瓶加内标模块 = 自动化内标定量添加站\n核心价值：精准（±2%）+ 闭管（防污染）+ 自清洗（三次清洗防交叉污染），专为250/500/1250mL萃取瓶的标准化内标添加而设计，是URD前处理流程中确保定量准确性与批间一致性的关键执行单元\n\n## Typical Scenarios (典型应用场景)\n北京海关\n\n## Working Principle (工作原理)\n通过精密定量泵送机构抽取固定体积内标溶液，配合精准瓶口定位机构，将内标液精准定量注入萃取瓶内；依靠伺服驱动控制吸排液行程与流速，保证每瓶加注量均匀一致，加注完成后自动吹扫清理管路，减少残留误差，实现自动化批量完成萃取瓶内标添加工序。\n\n## Limits & Cautions (限制与注意事项)\n无\n\n## Remarks (备注)\n', 'MOD-JY-004.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-005', '10ml注射泵加液模块', 'HHM10L-010', '加液', '1.0', 'active', '徐翔宇', '2025/10/17', '10ml注射泵，加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"10ml注射泵\", \"加液\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 10, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"10ml注射泵\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"500ml溶剂瓶\", \"function_code\": 650, \"sub_functions\": [\"651 启动右注射泵，652 清洗左注射泵，653 清洗右注射泵\"], \"cycle_time_sec\": 44, \"operation_target\": \"500ml溶剂瓶\", \"operation_workflow\": \"放入容量瓶/PP瓶 - 夹紧 - 上样针移至吸液位 - 针头伸入瓶内液面下 - 吸入样品液 - 上样针移至放液位 - 针头伸入瓶内（瓶颈） - 放液 - 排出管路体积 - 上样针移至清洗位 - 针头内外同时冲洗 - 上样针移至吹干位 - 吹干 - 取下容量瓶/PP瓶\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"启动左注射泵\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.075, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.045, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-JY-005\", \"name\": \"10ml注射泵加液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/10/17\", \"module_part_no\": \"HHM10L-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-005\n  module_part_no: HHM10L-010\n  name: 10ml注射泵加液模块\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/10/17\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 650\n  function_description: 启动左注射泵\n  operation_target: 500ml溶剂瓶\n  operation_workflow: 放入容量瓶/PP瓶 - 夹紧 - 上样针移至吸液位 - 针头伸入瓶内液面下 - 吸入样品液 - 上样针移至放液位 - 针头伸入瓶内（瓶颈） - 放液 - 排出管路体积 - 上样针移至清洗位 - 针头内外同时冲洗 - 上样针移至吹干位 - 吹干 - 取下容量瓶/PP瓶\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 44\n  consumables: 500ml溶剂瓶\n  sub_functions: [651 启动右注射泵，652 清洗左注射泵，653 清洗右注射泵]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 10ml注射泵\ntags_meta:\n  tags: [10ml注射泵, 加液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.045\n  power_kva_peak: 0.075\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: false', '# 10ml注射泵加液模块\n\n## Purpose (用途说明)\n依靠丝杆推动注射器柱塞匀速行进，实现高精度、小体积至大体积精准加注，满足实验严格配比要求，误差小、重复性好。\n\n## Typical Scenarios (典型应用场景)\n成都食检院\n\n## Working Principle (工作原理)\n由步进电机、丝杆传动机构、10ml 标准注射器及管路组件组成，电机驱动丝杆精准推动注射器推杆做直线往复运动；后退行程形成负压自动抽取试剂，前进行程匀速推送液体，依靠精准行程控制固定出液体积，实现10ml 量程内精准定量、恒速平稳加液，可精准控制加液流量与启停节奏，完成自动化定量加注。\n\n## Limits & Cautions (限制与注意事项)\n无\n\n## Remarks (备注)\n', 'MOD-JY-005.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-006', '25ml注射泵加液模块', 'HHM10B-025-UD', '加液', '1.0', 'active', '徐翔宇', '2026/3/20', '注射泵加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"注射泵加液\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 410, \"length_mm\": 220, \"weight_kg\": 13.6, \"mount_type\": \"平台外置\", \"tray_slots\": \"六工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 25, \"volume_ml_min\": 0, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"试剂瓶-500ml / \", \"function_code\": 650, \"sub_functions\": [\"651-清洗\"], \"cycle_time_sec\": 44, \"operation_target\": \"试剂瓶-500ml\", \"operation_workflow\": \"润管- 启动 -吸取溶剂1 - 阀体切换到注液1通道 - 排液 - 切换到吸液口 -吸取溶剂1 - 阀体切换到注液2通道 - 排液 - 溶剂2加液过程和溶剂1一样-实验结束-阀体切换到清洗4通道- 满量程吸取清洗液1 - 从5号通道排废-满量程吸取清洗液2- 从5号通道排废- - 满量程吸取清洗液1 - 从5号通道排废-结束\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"吸吐液\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.072, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.0432, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-JY-006\", \"name\": \"25ml注射泵加液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2026/3/20\", \"module_part_no\": \"HHM10B-025-UD\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-006\n  module_part_no: HHM10B-025-UD\n  name: 25ml注射泵加液模块\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2026/3/20\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 220\n  width_mm: 180\n  height_mm: 410\n  weight_kg: 13.6\n  module_slots: 0\n  tray_slots: \"六工位\"\n  mount_type: 平台外置\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 25\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 650\n  function_description: 吸吐液\n  operation_target: 试剂瓶-500ml\n  operation_workflow: 润管- 启动 -吸取溶剂1 - 阀体切换到注液1通道 - 排液 - 切换到吸液口 -吸取溶剂1 - 阀体切换到注液2通道 - 排液 - 溶剂2加液过程和溶剂1一样-实验结束-阀体切换到清洗4通道- 满量程吸取清洗液1 - 从5号通道排废-满量程吸取清洗液2- 从5号通道排废- - 满量程吸取清洗液1 - 从5号通道排废-结束\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 44\n  consumables: \"试剂瓶-500ml / \"\n  sub_functions: [651-清洗]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [注射泵加液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.0432\n  power_kva_peak: 0.072\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: true', '# 25ml注射泵加液模块\n\n## Purpose (用途说明)\n将储液瓶内的液体精准加入到对应加液位置瓶内\n\n## Typical Scenarios (典型应用场景)\n实验室自动化前处理、体外诊断、食品安全检测、环境监测、生物制药、科研高通量实验\n\n## Working Principle (工作原理)\n依靠电机驱动带动注射器推杆匀速直线推进 / 后退，精准控制推杆位移，从而定量推送 / 抽取注射器内液体，实现高精度加液、排液\n\n## Limits & Cautions (限制与注意事项)\n注射泵针管内可能有气泡附着\n\n## Remarks (备注)\n', 'MOD-JY-006.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-007', '自动补液系统', 'HHM10K-901', '加液', '1.0', 'active', '徐翔宇', '2025/8/22', '补液、加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"补液、加液\"]}, \"peripherals\": {\"required_peripherals\": \"真空泵\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 450, \"height_mm\": 400, \"length_mm\": 450, \"weight_kg\": 50, \"mount_type\": \"平台外置\", \"tray_slots\": \"四工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": -70, \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"试剂瓶\", \"function_code\": \"xxx\", \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 300, \"operation_target\": \"试剂瓶\", \"operation_workflow\": \"液位传感器反馈检测不到液面-通气电磁阀切换到负压-补液电磁阀连通-从补液试剂瓶向正压加液试剂瓶内补液-液面到达液位传感器位置-补液电磁阀关闭-通气电磁阀切换到正压\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"检测试剂瓶液位，自动完成补液\", \"absolute_accuracy_pct\": \"±2%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.625, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.375, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-007\", \"name\": \"自动补液系统\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/8/22\", \"module_part_no\": \"HHM10K-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-007\n  module_part_no: HHM10K-901\n  name: 自动补液系统\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/8/22\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 450\n  width_mm: 450\n  height_mm: 400\n  weight_kg: 50\n  module_slots: 0\n  tray_slots: \"四工位\"\n  mount_type: 平台外置\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: -70\nperipherals:\n  required_peripherals: 真空泵\nprocess_capability_1:\n  function_code: xxx\n  function_description: 检测试剂瓶液位，自动完成补液\n  operation_target: 试剂瓶\n  operation_workflow: 液位传感器反馈检测不到液面-通气电磁阀切换到负压-补液电磁阀连通-从补液试剂瓶向正压加液试剂瓶内补液-液面到达液位传感器位置-补液电磁阀关闭-通气电磁阀切换到正压\n  absolute_accuracy_pct: ±2%\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 300\n  consumables: 试剂瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [补液、加液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.375\n  power_kva_peak: 0.625\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 自动补液系统\n\n## Purpose (用途说明)\n自动液位检测，完成补液\n\n## Typical Scenarios (典型应用场景)\n适用于实验室高通量前处理，包括 SPE 柱活化 / 淋洗 / 洗脱补液、容量瓶定容、色谱流动相补给、恒温振荡试剂添加及样品稀释 / 内标加注。覆盖环境、食品、医药等检测场景，实现精准定量、防污染、降误差、标准化流程，适配自动化工作站\n\n## Working Principle (工作原理)\n液位传感器检测高低液位，当低于低液位时，开启自动补液，抽真空降低 瓶内压力，把液体从补液中抽取回来；达到高液位，自动停止补液\n\n## Limits & Cautions (限制与注意事项)\n仅适配指定规格容器与试剂类型，不适用于高粘度、易结晶、强腐蚀或易燃易爆液体。补液精度受温湿度、气压影响，管路易堵需定期维护；依赖稳定电源与洁净气源，防交叉污染需规范管路清洗，不可超量程补液，安装需水平稳固。\n\n## Remarks (备注)\n', 'MOD-JY-007.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-008', '5ml注射泵加液模块', 'HHM10L-005', '加液', '1.0', 'active', '徐翔宇', '2025/10/17', '加液，注射泵', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液，注射泵\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 300, \"length_mm\": 250, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 5, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"\", \"function_code\": 650, \"sub_functions\": [\"651-启动右注射泵\", \"652-清洗左注射泵，653-清洗右注射泵\"], \"cycle_time_sec\": 30, \"operation_target\": \"500ml溶剂瓶\", \"operation_workflow\": \"润管- 启动 -吸取溶剂1 - 阀体切换到注液1通道 - 排液 - 切换到吸液口 -吸取溶剂1 - 阀体切换到注液2通道 - 排液 - 溶剂2加液过程和溶剂1一样-实验结束-阀体切换到清洗4通道- 满量程吸取清洗液1 - 从5号通道排废-满量程吸取清洗液2- 从5号通道排废- - 满量程吸取清洗液1 - 从5号通道排废-结束\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"启动左注射泵\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.072, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.0432, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-JY-008\", \"name\": \"5ml注射泵加液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/10/17\", \"module_part_no\": \"HHM10L-005\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-008\n  module_part_no: HHM10L-005\n  name: 5ml注射泵加液模块\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/10/17\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 250\n  width_mm: 180\n  height_mm: 300\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 5\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 650\n  function_description: 启动左注射泵\n  operation_target: 500ml溶剂瓶\n  operation_workflow: 润管- 启动 -吸取溶剂1 - 阀体切换到注液1通道 - 排液 - 切换到吸液口 -吸取溶剂1 - 阀体切换到注液2通道 - 排液 - 溶剂2加液过程和溶剂1一样-实验结束-阀体切换到清洗4通道- 满量程吸取清洗液1 - 从5号通道排废-满量程吸取清洗液2- 从5号通道排废- - 满量程吸取清洗液1 - 从5号通道排废-结束\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 30\n  consumables: \"\"\n  sub_functions: [651-启动右注射泵, 652-清洗左注射泵，653-清洗右注射泵]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [加液，注射泵]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.0432\n  power_kva_peak: 0.072\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# 5ml注射泵加液模块\n\n## Purpose (用途说明)\n用注射泵从试剂瓶吸取一定量的液体，加入到样品管里\n\n## Typical Scenarios (典型应用场景)\n广泛用于实验室自动化、环境食品检测、医药生物、精细化工及分析仪器配套，实现试剂精准定量加注。\n\n## Working Principle (工作原理)\n由两套一体式注射泵 + 6 通切换阀 + PLC组成，实现两路液体精准定量输送、自动润管与清洗\n\n## Limits & Cautions (限制与注意事项)\n注射泵加液模块适用于洁净、低粘度液体的高精度加液，精度≤1%、重复性≤0.5%、单次≤20 秒；不可用于强腐蚀、高粘度、含颗粒液体及超量程工况。使用前需检查密封与气泡、先润管再加液、定期校准与清洗，避免空转和误接管路，保障稳定、洁净、精准供液\n\n## Remarks (备注)\n', 'MOD-JY-008.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-009', '15ml离心管拆装盖加液模块', 'HHM02M-015', '加液', '2.0', 'active', '何向东', '2025/1/16', '15ml离心管，拧盖，合盖，加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"15ml离心管，拧盖，合盖，加液\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 15, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指胶皮，胶条\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"离心管-15ml\", \"function_code\": 169, \"sub_functions\": [\"165 拆盖，166 装盖，167 加液\"], \"cycle_time_sec\": 106, \"operation_target\": \"15ml离心管\", \"operation_workflow\": \"载台移动到上下料位-放入离心管-载台移动到拆盖-夹紧离心管-Z轴向下移动到达离心管拆盖位置-钧舵夹爪夹紧瓶盖-旋转并向上运动打开管盖-夹持管盖-旋转并向下运动盖上管盖-载台移动到上下料位-取下离心管；\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"拆盖-加液-装盖\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-009\", \"name\": \"15ml离心管拆装盖加液模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 2.0, \"category\": \"加液\", \"last_updated\": \"2025/1/16\", \"module_part_no\": \"HHM02M-015\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-009\n  module_part_no: HHM02M-015\n  name: 15ml离心管拆装盖加液模块\n  category: 加液\n  version: 2.0\n  status: active\n  last_updated: 2025/1/16\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 15\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 169\n  function_description: 拆盖-加液-装盖\n  operation_target: 15ml离心管\n  operation_workflow: 载台移动到上下料位-放入离心管-载台移动到拆盖-夹紧离心管-Z轴向下移动到达离心管拆盖位置-钧舵夹爪夹紧瓶盖-旋转并向上运动打开管盖-夹持管盖-旋转并向下运动盖上管盖-载台移动到上下料位-取下离心管；\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 106\n  consumables: 离心管-15ml\n  sub_functions: [165 拆盖，166 装盖，167 加液]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指胶皮，胶条\ntags_meta:\n  tags: [15ml离心管，拧盖，合盖，加液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 15ml离心管拆装盖加液模块\n\n## Purpose (用途说明)\n本模块是专为 15ml 尖底离心管设计的自动化开合盖执行单元，用于实验室、自动化产线中离心管的开盖、合盖、夹紧、取放瓶等标准化操作，可配合机械手或人工实现无人 / 少人化拆盖作业\n\n## Typical Scenarios (典型应用场景)\n1.实验室自动化样本处理工作站\n2. 生物制药样品制备线\n3. 疾控 / 检测中心样本前处理\n4. 科研实验室高通量处理平台\n5. 体外诊断试剂灌装产线\n\n## Working Principle (工作原理)\n本模块通过Y 轴送料定位 + Z 轴旋盖升降 + 夹爪夹紧旋转 + 光电传感检测协同动作，自动完成 50ml 尖底离心管的夹紧、开盖、取瓶、合盖全流程\n\n## Limits & Cautions (限制与注意事项)\n专用性：仅适配 15ml 尖底离心管，不可混用其他规格\n运动参数：Y 轴 100mm、Z 轴 50mm，速度 50mm/s，定位 ±0.1mm\n动作逻辑：先定位→再夹紧→同步旋转 + 轴向移动完成旋盖\n安全限制：严禁超程超速、屏蔽传感器、无瓶空旋、伸手入工作区\n使用前提：传感器正常、夹紧有效、供电稳定方可运行\n\n## Remarks (备注)\n', 'MOD-JY-009.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
