_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml离心管拆装盖加液模块\n\n## Purpose (用途说明)\n本模块是专为 50ml 尖底离心管设计的自动化开合盖执行单元，用于实验室、自动化产线中离心管的开盖、合盖、夹紧、取放瓶等标准化操作，可配合机械手或人工实现无人 / 少人化拆盖作业\n\n## Typical Scenarios (典型应用场景)\n1.实验室自动化样本处理工作站\n2. 生物制药样品制备线\n3. 疾控 / 检测中心样本前处理\n4. 科研实验室高通量处理平台\n5. 体外诊断试剂灌装产线\n\n## Working Principle (工作原理)\n本模块通过Y 轴送料定位 + Z 轴旋盖升降 + 夹爪夹紧旋转 + 光电传感检测协同动作，自动完成 50ml 尖底离心管的夹紧、开盖、取瓶、合盖全流程\n\n## Limits & Cautions (限制与注意事项)\n专用性：仅适配 50ml 尖底离心管，不可混用其他规格\n运动参数：Y 轴 100mm、Z 轴 50mm，速度 50mm/s，定位 ±0.1mm\n动作逻辑：先定位→再夹紧→同步旋转 + 轴向移动完成旋盖\n安全限制：严禁超程超速、屏蔽传感器、无瓶空旋、伸手入工作区\n使用前提：传感器正常、夹紧有效、供电稳定方可运行\n\n## Remarks (备注)\n', 'MOD-JY-010.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-011', '25-200ml容量瓶拆盖加液模块', 'HHM10F-901', '加液', '2.0', 'active', '何向东', '2024/12/23', '容量瓶，拧盖，合盖，加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"容量瓶，拧盖，合盖，加液\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 200, \"volume_ml_min\": 25, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指胶皮，胶条\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"容量瓶-25ml / 容量瓶-50ml / 容量瓶-100ml / 容量瓶-200ml\", \"function_code\": 523, \"sub_functions\": [\"520 拆盖，521 加液，522 装盖\"], \"cycle_time_sec\": 120, \"operation_target\": \"25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶\", \"operation_workflow\": \"夹紧组件移至上下料位 - 放入容量瓶（同规格2个）- 夹紧 - 夹紧组件移至拔瓶塞位 -  钧舵夹爪下降至拔瓶塞位 - 夹紧瓶赛并旋转向上拔出瓶塞 - 夹爪保持夹住瓶塞 - 夹紧组件移至加液位 - 加液管下降至刻度线以下 - 加液（加液至瓶颈）- 夹紧组件移至拔瓶塞位 - 钧舵夹爪旋转并向下运动塞入瓶塞 - 夹紧组件移至上下料位 - 夹爪打开 - 取下容量瓶\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"拆盖-加液-装盖\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.42, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.252, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-011\", \"name\": \"25-200ml容量瓶拆盖加液模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 2.0, \"category\": \"加液\", \"last_updated\": \"2024/12/23\", \"module_part_no\": \"HHM10F-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-011\n  module_part_no: HHM10F-901\n  name: 25-200ml容量瓶拆盖加液模块\n  category: 加液\n  version: 2.0\n  status: active\n  last_updated: 2024/12/23\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 25\n  volume_ml_max: 200\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 523\n  function_description: 拆盖-加液-装盖\n  operation_target: 25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶\n  operation_workflow: 夹紧组件移至上下料位 - 放入容量瓶（同规格2个）- 夹紧 - 夹紧组件移至拔瓶塞位 -  钧舵夹爪下降至拔瓶塞位 - 夹紧瓶赛并旋转向上拔出瓶塞 - 夹爪保持夹住瓶塞 - 夹紧组件移至加液位 - 加液管下降至刻度线以下 - 加液（加液至瓶颈）- 夹紧组件移至拔瓶塞位 - 钧舵夹爪旋转并向下运动塞入瓶塞 - 夹紧组件移至上下料位 - 夹爪打开 - 取下容量瓶\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 120\n  consumables: \"容量瓶-25ml / 容量瓶-50ml / 容量瓶-100ml / 容量瓶-200ml\"\n  sub_functions: [520 拆盖，521 加液，522 装盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指胶皮，胶条\ntags_meta:\n  tags: [容量瓶，拧盖，合盖，加液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.252\n  power_kva_peak: 0.42\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 25-200ml容量瓶拆盖加液模块\n\n## Purpose (用途说明)\n本模块实现：25-200ml容量瓶的上下料、拔瓶塞、加液、盖瓶塞等功能。\n\n## Typical Scenarios (典型应用场景)\n1. 第三方检测机构样本前处理工作站\n2. 制药企业标准溶液配制线\n3. 疾控 / 医院检验中心自动化配液系统\n4. 高校 / 科研院所高通量化学实验平台\n5. 体外诊断（IVD）试剂生产配液线\n6. 计量 / 质检院所容量分析自动化系统\n\n## Working Principle (工作原理)\n本模块通过Y 轴工位移动 + Z 轴拔塞 / 盖塞 + 加液 Z 轴定深加液 + 气缸夹紧定位，全自动完成容量瓶上料→拔塞→加液→盖塞→下料全流程\n\n## Limits & Cautions (限制与注意事项)\n运动区域禁止伸手，防止夹伤、撞机！\n\n## Remarks (备注)\n', 'MOD-JY-011.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-012', '8通道-正压加液模块', 'HHM10A-001', '加液', '2.0', 'active', '徐翔宇', '2024/12/23', '正压加液，溶剂瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"正压加液，溶剂瓶\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 300, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"平台外置\", \"tray_slots\": \"八工位\", \"module_slots\": 0}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"溶剂瓶\", \"function_code\": \"XXX\", \"sub_functions\": [], \"cycle_time_sec\": 10, \"operation_target\": \"溶剂瓶\", \"operation_workflow\": \"通气-电磁阀打开-加液-电磁阀关闭\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"加液\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.42, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.252, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-012\", \"name\": \"8通道-正压加液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 2.0, \"category\": \"加液\", \"last_updated\": \"2024/12/23\", \"module_part_no\": \"HHM10A-001\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-012\n  module_part_no: HHM10A-001\n  name: 8通道-正压加液模块\n  category: 加液\n  version: 2.0\n  status: active\n  last_updated: 2024/12/23\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 300\n  weight_kg: 15\n  module_slots: 0\n  tray_slots: \"八工位\"\n  mount_type: 平台外置\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: XXX\n  function_description: 加液\n  operation_target: 溶剂瓶\n  operation_workflow: 通气-电磁阀打开-加液-电磁阀关闭\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 10\n  consumables: 溶剂瓶\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [正压加液，溶剂瓶]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.252\n  power_kva_peak: 0.42\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 8通道-正压加液模块\n\n## Purpose (用途说明)\n给模块提供气源，溶剂瓶，通过电磁阀控制加液量\n\n## Typical Scenarios (典型应用场景)\n1. 实验室标准液 / 缓冲液配制\n2. 体外诊断试剂（IVD）生产\n3. 制药行业药液 / 中间液定量加注\n4. 食品 / 环境 / 水质检测前处理\n5. 精细化工 / 化妆品微量配液\n6. 易起泡 / 易结晶液体专用加注\n\n## Working Principle (工作原理)\n密闭加压 → 液体被稳定推出 → 流量由气压 / 阀门精准控制 → 无脉动、无气泡、高精度加液\n\n## Limits & Cautions (限制与注意事项)\n1.压力稳、密封好，压力不能超过瓶子、管路的极限\n2.先排气、再运行\n3.不喷液、不滴漏\n4.开盖先泄压\n\n## Remarks (备注)\n', 'MOD-JY-012.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-013', '2ml离心管带磁拆装盖加液模块V3.0', NULL, '加液', '3.0', 'active', '何向东', '2025/3/14', '带磁，加液，离心管', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"带磁，加液，离心管\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 2, \"volume_ml_min\": 0, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"离心管-2ml / \", \"function_code\": 177, \"sub_functions\": [\"175 拆盖，176 装盖，178 加液\"], \"cycle_time_sec\": 105, \"operation_target\": \"2ml离心管\", \"operation_workflow\": \"上料：两个带盖的2ml离心管；拆盖：带盖2ml离心管拆盖；加液：加液；装盖：离心管装盖；下料：2个带盖带料的2ml离心管。\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"本模块预期实现：2ml离心管的上下料、开合盖和加液功能。\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.52, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.31, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-013\", \"name\": \"2ml离心管带磁拆装盖加液模块V3.0\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 3.0, \"category\": \"加液\", \"last_updated\": \"2025/3/14\", \"module_part_no\": \"\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-013\n  module_part_no: \"\"\n  name: 2ml离心管带磁拆装盖加液模块V3.0\n  category: 加液\n  version: 3.0\n  status: active\n  last_updated: 2025/3/14\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 2\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 177\n  function_description: 本模块预期实现：2ml离心管的上下料、开合盖和加液功能。\n  operation_target: 2ml离心管\n  operation_workflow: 上料：两个带盖的2ml离心管；拆盖：带盖2ml离心管拆盖；加液：加液；装盖：离心管装盖；下料：2个带盖带料的2ml离心管。\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 105\n  consumables: \"离心管-2ml / \"\n  sub_functions: [175 拆盖，176 装盖，178 加液]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [带磁，加液，离心管]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.31\n  power_kva_peak: 0.52\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 2ml离心管带磁拆装盖加液模块V3.0\n\n## Purpose (用途说明)\n\n\n## Typical Scenarios (典型应用场景)\n1、制药研发对照品、注射液小体积配液\n2、食品安全 / 农残 / 重金属检测前处理\n3、疾控 / 医院检验样本自动化开盖加液\n4、蛋白提取、细胞裂解、样本稀释工作站\n5、标准溶液、标样、质控品自动配制\n6、微流控、免疫检测试剂自动化分装\n7、科研实验室 2ml 管批量处理平台\n\n## Working Principle (工作原理)\n通过Y 轴工位流转 + Z 轴旋盖夹爪 + 多通道定量加液 + 气缸夹紧定位，全自动完成上料→开盖→加液→关盖→下料-吸磁全流程\n\n## Limits & Cautions (限制与注意事项)\n运动区域禁止伸手：Y/Z 轴、夹爪动作时严禁伸入，防止夹伤\n定期清洁：传感器、夹爪、治具保持干净，避免漏检、打滑\n禁止空旋：无瓶时禁止夹爪旋转，防止磨损、损坏\n\n## Remarks (备注)\n', 'MOD-JY-013.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-014', '消解管拆盖加液模块(100ML)', 'HHM10E-100', '加液', '1.0', 'active', '汪健', '2025/3/28', '加液，拆装盖，100ml消解管，喷淋式加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液\", \"拆装盖\", \"100ml消解管，喷淋式加液\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 100, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液\", \"微波消解\", \"石墨赶酸\"]}, \"process_capability_1\": {\"consumables\": \"消解管-100ml\", \"function_code\": 145, \"sub_functions\": [\"146-拆盖加液\", \"147-加液\", \"148-拆盖\", \"149-装盖\"], \"cycle_time_sec\": 60, \"operation_target\": \"100ml消解管\", \"operation_workflow\": \"载台移至上下料位 - 放入消解管 - 载台移至拆盖位 - 夹紧消解管 - 气缸夹爪下降至消解管塞处 - 夹爪夹住管塞 - 提起 - 载台移至上下料位 - 取走消解管操作 - 消解管返回 - 载台移至拆盖位 - 气缸夹爪下降 - 管塞塞进消解管 - 气缸夹爪上升 - 载台移至上下料位 - 取下消解管\", \"repeat_accuracy_pct\": \"\", \"function_description\": \"拆盖加液装盖\", \"absolute_accuracy_pct\": \"±5%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.574, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.344, \"requires_ventilation\": true, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-014\", \"name\": \"消解管拆盖加液模块(100ML)\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/3/28\", \"module_part_no\": \"HHM10E-100\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-014\n  module_part_no: HHM10E-100\n  name: 消解管拆盖加液模块(100ML)\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/3/28\n  owner: 汪健\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 100\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 145\n  function_description: 拆盖加液装盖\n  operation_target: 100ml消解管\n  operation_workflow: 载台移至上下料位 - 放入消解管 - 载台移至拆盖位 - 夹紧消解管 - 气缸夹爪下降至消解管塞处 - 夹爪夹住管塞 - 提起 - 载台移至上下料位 - 取走消解管操作 - 消解管返回 - 载台移至拆盖位 - 气缸夹爪下降 - 管塞塞进消解管 - 气缸夹爪上升 - 载台移至上下料位 - 取下消解管\n  absolute_accuracy_pct: ±5%\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 60\n  consumables: 消解管-100ml\n  sub_functions: [146-拆盖加液, 147-加液, 148-拆盖, 149-装盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液\n    - 微波消解\n    - 石墨赶酸\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [加液, 拆装盖, 100ml消解管，喷淋式加液]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.344\n  power_kva_peak: 0.574\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: true\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: true', '# 消解管拆盖加液模块(100ML)\n\n## Purpose (用途说明)\n100ml消解管拆盖加酸装盖，可喷淋式加液\n\n## Typical Scenarios (典型应用场景)\n1、水质 COD 检测100ml 消解管自动拆盖 + 喷淋加强酸前处理\n2、总磷、总氮、总重金属检测5 种消解液自动定量添加\n\n## Working Principle (工作原理)\n本模块通过Y 轴与 Z 轴联动定位，配合气缸夹爪完成消解管自动拆盖；采用喷淋式加液结构与多路电磁阀控制，实现5 种强酸 / 易挥发消解液的定量加注（精度 ±5%）；加液过程中密封压紧 + 外部抽雾，防止酸雾泄漏与腐蚀；反应完成后自动复位出料，停机前可自动冲洗管路并收集废液，全程自动化完成拆盖、密封加液、抽雾、冲洗等一体化作业。\n\n## Limits & Cautions (限制与注意事项)\n1、加液前必须启动外部抽风系统，并确保喷淋模组压紧密封管口，防止酸雾泄漏。\n2、拆盖与加液前，必须将消解管完全夹紧，避免管体转动、倾斜或漏液。\n3、操作强酸、易挥发消解液时，严禁打开防护罩，严禁将手伸入设备运动区域。\n4、长时间停机前必须执行管路自动冲洗，并将废液排入收集盒，防止结晶与腐蚀。\n5、开机必须完成轴回零、气缸复位等初始化流程，运行中禁止随意修改参数或手动触发阀件。\n\n## Remarks (备注)\n', 'MOD-JY-014.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-JY-015', '4ml西林瓶拆盖正压加液模块', 'HHM02G-004', '加液', '1.0', 'active', '何向东', '2025/4/10', '加液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 4, \"volume_ml_min\": 0.2, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指包胶\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"西林瓶-4ml\", \"function_code\": 177, \"sub_functions\": [\"175-拆盖\", \"176-装盖\"], \"cycle_time_sec\": 40, \"operation_target\": \"4ml西林瓶\", \"operation_workflow\": \"载台移至上下料位 - 放入西林瓶- 移至拆盖位 - 电动夹爪下行 - 拆盖 -电动夹爪上行-移至加液位 - 加液- 移至拆盖位 - 电动夹爪下行 - 装盖 -电动夹爪上行-移至下料位\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"拆盖/加液/装盖\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-JY-015\", \"name\": \"4ml西林瓶拆盖正压加液模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加液\", \"last_updated\": \"2025/4/10\", \"module_part_no\": \"HHM02G-004\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-JY-015\n  module_part_no: HHM02G-004\n  name: 4ml西林瓶拆盖正压加液模块\n  category: 加液\n  version: 1.0\n  status: active\n  last_updated: 2025/4/10\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.2\n  volume_ml_max: 4\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 177\n  function_description: 拆盖/加液/装盖\n  operation_target: 4ml西林瓶\n  operation_workflow: 载台移至上下料位 - 放入西林瓶- 移至拆盖位 - 电动夹爪下行 - 拆盖 -电动夹爪上行-移至加液位 - 加液- 移至拆盖位 - 电动夹爪下行 - 装盖 -电动夹爪上行-移至下料位\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 40\n  consumables: 西林瓶-4ml\n  sub_functions: [175-拆盖, 176-装盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指包胶\ntags_meta:\n  tags: [加液]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 4ml西林瓶拆盖正压加液模块\n\n## Purpose (用途说明)\n4ml西林瓶拆盖加液\n\n## Typical Scenarios (典型应用场景)\n1、水质 / 环境检测4ml 西林瓶自动拧盖、定量加液前处理\n2、实验室试剂、标准液、缓冲液自动开盖 + 加注 + 封盖一体化作业\n3、药品 / 生物样品微量试剂（0.5–2ml）精准加液场景\n\n## Working Principle (工作原理)\n模块通过 Y 轴、Z 轴联动定位，在拆盖位由电动旋转夹爪自动完成西林瓶拧盖与封盖；Y 轴移送至加液位后，6 路直通阀实现 0.5–2ml 试剂定量加注；全程由光电传感器检测瓶体与瓶盖，异常自动报警，完成拆盖、加液、装盖全自动作业\n\n## Limits & Cautions (限制与注意事项)\n1、仅限4ml 标准西林瓶使用，禁止混用其他规格容器。\n2、拆盖 / 拧盖前必须夹紧瓶体，防止打滑、破损或旋盖失败。\n3、加液时确保瓶口与加液头对准，避免液体溅出、腐蚀器件\n4、运行时严禁伸手进入Y/Z 轴、电动夹爪、加液区域，防止夹伤\n\n## Remarks (备注)\n', 'MOD-JY-015.md', '2026-06-11 18:33:12', '2026-06-12 11:33:37');
