me\": \"2ml-6孔位高速离心模块V4.0（带XYZ）\", \"owner\": \"杨宇/深圳\", \"status\": \"active\", \"version\": 1.0, \"category\": \"离心\", \"last_updated\": \"2025/6/6\", \"module_part_no\": \"HHM15B-602\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-LX-004\n  module_part_no: HHM15B-602\n  name: 2ml-6孔位高速离心模块V4.0（带XYZ）\n  category: 离心\n  version: 1.0\n  status: active\n  last_updated: 2025/6/6\n  owner: 杨宇/深圳\nphysical_specs:\n  length_mm: 800\n  width_mm: 850\n  height_mm: 2055\n  weight_kg: 45\n  module_slots: 3\n  tray_slots: \"六工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.5\n  volume_ml_max: 2\n  temperature_c_min: 1\n  temperature_c_max: 10\n  speed_rpm_min: 1000\n  speed_rpm_max: 14000\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: -75\nperipherals:\n  required_peripherals: 真空泵\nprocess_capability_1:\n  function_code: 188\n  function_description: 离心机启动\n  operation_target: 2ml离心管\n  operation_workflow: 放入离心管1-点击按钮-放入离心管2-点击按钮-放入离心管3-点击按钮-放入离心管4-点击按钮-放入离心管5-点击按钮-放入离心管6-盖塞盖-气缸推出-卡紧塞盖-真空泵开启-合开开启(提制)-离心5min-停止-气缸退回-打开塞盖-依次取出离心管\n  absolute_accuracy_pct: \"\"\n  repeat_accuracy_pct: \"\"\n  cycle_time_sec: 420\n  consumables: 离心管-2ml\n  sub_functions: [185-离心机定位, 186-离心机预冷, 187-离心机取盖, 188-离心机启动, 189-离心机除水, 190-离心机停止]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [2ml离心管，离心]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 1\n  power_kva_peak: 1.5\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 2ml-6孔位高速离心模块V4.0（带XYZ）\n\n## Purpose (用途说明)\n实现多个2ml离心管带盖溶液离心，离心转速和时长可设定、调节。\n\n## Typical Scenarios (典型应用场景)\n血样\n\n## Working Principle (工作原理)\n设备先完成电机轴回零、提篮对位下料口、上下料门开启的初始化；通过机械手交替向离心机提篮投放待处理 离心管，满负荷后关门启动离心，电机按设定转速（14000r/min）和时长（5min）运行，振动传感器实时监测三轴位移，超阈值（300um）则降速停机报警；离心结束后，提篮归位、开门，机械手取出成品，完成自动化离心作业循环。\n\n## Limits & Cautions (限制与注意事项)\n1、仅用/2ml 离心管，4 孔对称装样，禁止偏载、破损管、无盖管。\n2、转速≤14000r/min，振动＞300μm、真空未达标禁止离心。\n3、必须塞盖密封 + 抽真空后启动，运行中严禁开门、撬盖。\n4、停机必做 2000 转 / 30 分钟除水，不可省略。\n5、异常立即急停，断电破真空再检修，禁止强掰、硬撬、改参数。\n\n## Remarks (备注)\n', 'MOD-LX-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-LX-005', '50ml*4孔位离心机模块（不带XYZ）', 'HHM15A-050', '离心', '3.0', 'active', '杨宇/深圳', '2025/4/25', '离心', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"离心\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 460, \"height_mm\": 230, \"length_mm\": 460, \"weight_kg\": 55, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 3}, \"module_performance\": {\"vacuum_kpa\": -80, \"speed_rpm_max\": 8000, \"speed_rpm_min\": 500, \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": 10, \"temperature_c_min\": 1}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": 188, \"sub_functions\": [\"185-离心机定位\", \"186-离心机预冷\", \"187-离心机取盖\", \"188-离心机启动\", \"189-离心机除水\", \"190-离心机停止\"], \"cycle_time_sec\": 420, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"入口开启 - 放入离心管1 - 转盘旋转 - 提篮对准入口 - 放入离心管2 - 转盘旋转 - 提篮对准入口 - 放入离心管3 - 转盘旋转 - 提篮对准入口 - 放入离心管4 - 入口关闭 - 离心5min - 停止 - 打开塞盖 - 依次取出离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"离心机启动\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 1.5, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"true\", \"power_kva_nominal\": 1, \"requires_ventilation\": true, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-LX-005\", \"name\": \"50ml*4孔位离心机模块（不带XYZ）\", \"owner\": \"杨宇/深圳\", \"status\": \"active\", \"version\": 3.0, \"category\": \"离心\", \"last_updated\": \"2025/4/25\", \"module_part_no\": \"HHM15A-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-LX-005\n  module_part_no: HHM15A-050\n  name: 50ml*4孔位离心机模块（不带XYZ）\n  category: 离心\n  version: 3.0\n  status: active\n  last_updated: 2025/4/25\n  owner: 杨宇/深圳\nphysical_specs:\n  length_mm: 460\n  width_mm: 460\n  height_mm: 230\n  weight_kg: 55\n  module_slots: 3\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: 1\n  temperature_c_max: 10\n  speed_rpm_min: 500\n  speed_rpm_max: 8000\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: -80\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 188\n  function_description: 离心机启动\n  operation_target: 50ml离心管\n  operation_workflow: 入口开启 - 放入离心管1 - 转盘旋转 - 提篮对准入口 - 放入离心管2 - 转盘旋转 - 提篮对准入口 - 放入离心管3 - 转盘旋转 - 提篮对准入口 - 放入离心管4 - 入口关闭 - 离心5min - 停止 - 打开塞盖 - 依次取出离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 420\n  consumables: 离心管-50ml\n  sub_functions: [185-离心机定位, 186-离心机预冷, 187-离心机取盖, 188-离心机启动, 189-离心机除水, 190-离心机停止]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [离心]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 1\n  power_kva_peak: 1.5\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: true\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# 50ml*4孔位离心机模块（不带XYZ）\n\n## Purpose (用途说明)\n实现2-4个50ml带盖溶液离心，离心转速和时长可设定、调节。\n\n## Typical Scenarios (典型应用场景)\n适用于生物、医药、检测实验室，对50ml 带盖 离心管内液体样本进行自动化离心分离，替代人工操作，实现样本处理全流程无人化\n\n## Working Principle (工作原理)\n核心原理：电气控制 + 气动执行 + 高速离心分离，通过 PLC 统一协调，实现自动上料→定位→关门→高速离心→开门→取料全流程自动化\n\n## Limits & Cautions (限制与注意事项)\n仅适配50ml 带盖 离心管，单次最多4个，必须对称放置。\n转速最高8000r/min，振动＞300μm必须停机报警。\n门未关严禁止离心，运行中禁止开门。\n禁止非指定容器、超载、偏载、无盖运行\n\n## Remarks (备注)\n', 'MOD-LX-005.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-NS-001', '10ml大容量连续浓缩模块', 'HHM05H-010', '浓缩', '1.0', 'active', '蔡勤超', '2025/7/10', '连续浓缩，大容量', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"连续浓缩，大容量\"]}, \"peripherals\": {\"required_peripherals\": \"真空泵，空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 380, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 50, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 2}, \"module_performance\": {\"vacuum_kpa\": -95, \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 4, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"胶条，底部胶皮，顶部胶皮，密封圈\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"10ml西林瓶,50ml尖底（圆底）瓶，100ml尖底（圆底）瓶，200ml尖底（圆底）瓶 / \", \"function_code\": 200, \"sub_functions\": [\"202-浓缩排空，203-预热，204-退出预热\"], \"cycle_time_sec\": \"\", \"operation_target\": \"10ml西林瓶,50ml尖底（圆底）瓶，100ml尖底（圆底）瓶，200ml尖底（圆底）瓶\", \"operation_workflow\": \"载台移至上下料位 - 放入样品瓶/西林瓶 - 加热吹风达到设定温度 - 真空泵开启 - 抽真空/加液管路准备就绪 - 载台移至取液位/浓缩位 - 压紧西林瓶瓶口 - 钢针伸入样品瓶底部 - 吸取样品 - 加样品进西林瓶 - 离心浓缩 - 至浓缩终点 - 吸取样品 - 加样品进西林瓶 - 离心浓缩 - 重复至全部样品浓缩完毕 - 停止 - 真空电磁阀关闭 - 破真空 - 载台移至上下料位 - 取下西林瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"浓缩\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 70, \"voltage_v\": 48, \"power_kva_peak\": 0.64, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.38, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-NS-001\", \"name\": \"10ml大容量连续浓缩模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 1.0, \"category\": \"浓缩\", \"last_updated\": \"2025/7/10\", \"module_part_no\": \"HHM05H-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-NS-001\n  module_part_no: HHM05H-010\n  name: 10ml大容量连续浓缩模块\n  category: 浓缩\n  version: 1.0\n  status: active\n  last_updated: 2025/7/10\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 380\n  height_mm: 600\n  weight_kg: 50\n  module_slots: 2\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 4\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: -95\nperipherals:\n  required_peripherals: 真空泵，空压机\nprocess_capability_1:\n  function_code: 200\n  function_description: 浓缩\n  operation_target: 10ml西林瓶,50ml尖底（圆底）瓶，100ml尖底（圆底）瓶，200ml尖底（圆底）瓶\n  operation_workflow: 载台移至上下料位 - 放入样品瓶/西林瓶 - 加热吹风达到设定温度 - 真空泵开启 - 抽真空/加液管路准备就绪 - 载台移至取液位/浓缩位 - 压紧西林瓶瓶口 - 钢针伸入样品瓶底部 - 吸取样品 - 加样品进西林瓶 - 离心浓缩 - 至浓缩终点 - 吸取样品 - 加样品进西林瓶 - 离心浓缩 - 重复至全部样品浓缩完毕 - 停止 - 真空电磁阀关闭 - 破真空 - 载台移至上下料位 - 取下西林瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: \"\"\n  consumables: \"10ml西林瓶,50ml尖底（圆底）瓶，100ml尖底（圆底）瓶，200ml尖底（圆底）瓶 / \"\n  sub_functions: [202-浓缩排空，203-预热，204-退出预热]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 胶条，底部胶皮，顶部胶皮，密封圈\ntags_meta:\n  tags: [连续浓缩，大容量]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.38\n  power_kva_peak: 0.64\n  voltage_v: 48\n  noise_db: 70\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 10ml大容量连续浓缩模块\n\n## Purpose (用途说明)\n这个模块 = \"大瓶取液 → 小瓶离心浓缩蒸干\" 的自动化工作站，核心解决的是：把50~200ml大瓶中的有机溶剂样品，安全、可控、自动地浓缩蒸干到10ml西林瓶中，替代人工旋转蒸发操作\n\n## Typical Scenarios (典型应用场景)\n这个模块的典型应用 = 把50~200ml大瓶有机溶剂样品，通过\"抽真空+高速离心+45~50℃热风\"三重手段，安全、可控、自动地浓缩蒸干到10ml西林瓶，核心替代的是：人工旋转蒸发（危险、费时、不一致），四大场景的共同痛点是：样品量大、溶剂有毒、需低温防分解、蒸干终点难判断——模块全部解决\n\n## Working Principle (工作原理)\n原理 = 注射泵抽排转移 + 离心贴壁（5000~8000rpm）+ 真空降沸点 + 45~50℃热风加速 + 红外测温安全监控 + 流量/温度/真空度曲线判断终点，六位一体实现大瓶有机溶剂 → 10ml西林瓶的自动化浓缩蒸干\n\n## Limits & Cautions (限制与注意事项)\n六大红线不可碰：转速不超8000rpm、温度不超50℃、仅限尖底/圆底瓶+10ml西林瓶、必须初始化回零、必须先关真空再破真空再升Z轴、必须执行清洗工序——其余皆可调，但蒸干终点必须靠曲线判断，不可只靠时间。\n\n## Remarks (备注)\n', 'MOD-NS-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-NS-002', '50ml西林瓶离心浓缩模块', 'HHM05D-050', '浓缩', '2.0', 'active', '宾俊', '2025/5/23', '浓缩', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"浓缩\"]}, \"peripherals\": {\"required_peripherals\": \"真空泵，空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 27, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": -95, \"speed_rpm_max\": 8000, \"speed_rpm_min\": 1000, \"volume_ml_max\": 30, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": 55, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"胶条，底部胶皮，顶部胶皮，密封圈\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml西林瓶\", \"function_code\": 200, \"sub_functions\": [\"202-浓缩排空，203-预热，204-退出预热\"], \"cycle_time_sec\": 0, \"operation_target\": \"50ml西林瓶\", \"operation_workflow\": \"西林瓶载台移至放料位-加热吹风达到设定温度-真空泵开启-抽真空/加液管路准备就绪-安装西林瓶至载台-载台移至加液位-加液20ml-载台移至浓缩位-压紧瓶口-离心浓缩-停止-真空电磁阀关闭-破真空-载台移至放料位-取下西林瓶\", \"repeat_accuracy_pct\": \"±0.5\", \"function_description\": \"浓缩\", \"absolute_accuracy_pct\": \"±1\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 70, \"voltage_v\": 48, \"power_kva_peak\": 0.64, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.38, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-NS-002\", \"name\": \"50ml西林瓶离心浓缩模块\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 2.0, \"category\": \"浓缩\", \"last_updated\": \"2025/5/23\", \"module_part_no\": \"HHM05D-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-NS-002\n  module_part_no: HHM05D-050\n  name: 50ml西林瓶离心浓缩模块\n  category: 浓缩\n  version: 2.0\n  status: active\n  last_updated: 2025/5/23\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 27\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 30\n  temperature_c_min: 25\n  temperature_c_max: 55\n  speed_rpm_min: 1000\n  speed_rpm_max: 8000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: -95\nperipherals:\n  required_peripherals: 真空泵，空压机\nprocess_capability_1:\n  function_code: 200\n  function_description: 浓缩\n  operation_target: 50ml西林瓶\n  operation_workflow: 西林瓶载台移至放料位-加热吹风达到设定温度-真空泵开启-抽真空/加液管路准备就绪-安装西林瓶至载台-载台移至加液位-加液20ml-载台移至浓缩位-压紧瓶口-离心浓缩-停止-真空电磁阀关闭-破真空-载台移至放料位-取下西林瓶\n  absolute_accuracy_pct: ±1\n  repeat_accuracy_pct: ±0.5\n  cycle_time_sec: 0\n  consumables: 50ml西林瓶\n  sub_functions: [202-浓缩排空，203-预热，204-退出预热]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 胶条，底部胶皮，顶部胶皮，密封圈\ntags_meta:\n  tags: [浓缩]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.38\n  power_kva_peak: 0.64\n  voltage_v: 48\n  noise_db: 70\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 50ml西林瓶离心浓缩模块\n\n## Purpose (用途说明)\n该模块用于将 50ml西林瓶内的有机溶剂样品，通过 抽真空 + 高速旋转离心 + 加热吹热风 的方式，直接在瓶内浓缩蒸干，实现小体积样品的自动化蒸干处理\n\n## Typical Scenarios (典型应用场景)\n这个模块 = \"50ml西林瓶上料 → 瓶内真空离心热风蒸干 → 放料\" 的全自动工作站，核心解决的是：把50ml西林瓶中的有机溶剂样品，不转移、不倒瓶、低温可控地浓缩蒸干，替代人工旋转蒸发，特别适合药物残留、农药检测、环境监测等需要批量处理小体积有机样品的场景\n\n## Working Principle (工作原理)\n离心贴壁（增大面积）+ 真空降压（降低沸点）+ 45~50℃热风（提供能量），三效协同实现低温快速蒸干，通过真空度+流量+温度三条曲线实时判断终点，全程自动化，替代人工旋转蒸发\n\n## Limits & Cautions (限制与注意事项)\n本模块限制少、操作简单，最核心的注意事项就是三条——温度不超50℃、转速5000~6000r/min、蒸干终点必须靠曲线判断不可靠时间，其余按流程执行即可安全运行\n\n## Remarks (备注)\n', 'MOD-NS-002.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
