pressed_air: true\n  requires_water: true\n  requires_drain: true', '# 4ml西林瓶离心浓缩模块V1.0\n\n## Purpose (用途说明)\n该模块用于将 4ml西林瓶内的有机溶剂样品，通过 抽真空 + 高速旋转离心 + 加热吹热风 的方式，直接在瓶内浓缩蒸干，实现小体积样品的自动化蒸干处理\n\n## Typical Scenarios (典型应用场景)\n这个模块 = \"4ml西林瓶上料 → 瓶内真空离心热风蒸干 → 放料\" 的全自动工作站，核心解决的是：把4ml西林瓶中的有机溶剂样品，不转移、不倒瓶、低温可控地浓缩蒸干，替代人工旋转蒸发，特别适合药物残留、农药检测、环境监测等需要批量处理小体积有机样品的场景\n\n## Working Principle (工作原理)\n离心贴壁（增大面积）+ 真空降压（降低沸点）+ 45~50℃热风（提供能量），三效协同实现低温快速蒸干，通过真空度+流量+温度三条曲线实时判断终点，全程自动化，替代人工旋转蒸发\n\n## Limits & Cautions (限制与注意事项)\n本模块限制少、操作简单，最核心的注意事项就是三条——温度不超50℃、转速5000~6000r/min、蒸干终点必须靠曲线判断不可靠时间，其余按流程执行即可安全运行\n\n## Remarks (备注)\n', 'MOD-NS-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-NS-004', '50ml西林瓶连续离心浓缩', 'HHM05J-050', '浓缩', '1.0', 'active', '宾俊', '2026/5/13', '浓缩，复溶，连续', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"浓缩\", \"复溶，连续\"]}, \"peripherals\": {\"required_peripherals\": \"真空泵\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 380, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 45, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 2}, \"module_performance\": {\"vacuum_kpa\": -95, \"speed_rpm_max\": 8000, \"speed_rpm_min\": 1000, \"volume_ml_max\": 30, \"volume_ml_min\": 1, \"pressure_bar_max\": 7, \"pressure_bar_min\": 0.1, \"temperature_c_max\": 55, \"temperature_c_min\": 25}, \"delivery_maintenance\": {\"wear_parts\": \"底座胶皮,胶条,定位胶垫，密封圈\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml西林瓶/125mlpp瓶/50ml尖底瓶/100ml/200ml尖底瓶\", \"function_code\": 200, \"sub_functions\": [\"201-复溶\", \"202-浓缩排空\", \"203-预热\", \"204-退出预热\", \"205-浓缩+复溶\"], \"cycle_time_sec\": 1800, \"operation_target\": \"50ml西林瓶\", \"operation_workflow\": \"载台移至上下料位 - 放入西林瓶 - 加热吹风达到设定温度 - 真空泵开启 - 抽真空/加液管路准备就绪 - 载台移至浓缩位 - 压紧瓶口 - 加样品 - 离心浓缩 - 至浓缩终点(按浓缩时间) -破真空- 加样品 - 离心浓缩 - 重复至全部样品浓缩完毕 -最后一次按流量判断浓缩终点- 停止 - 真空电磁阀关闭 - 破真空 - 载台移至上下料位 - 取下西林瓶\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"浓缩\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 48, \"power_kva_peak\": 1, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.56, \"requires_ventilation\": true, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-NS-004\", \"name\": \"50ml西林瓶连续离心浓缩\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 1.0, \"category\": \"浓缩\", \"last_updated\": \"2026/5/13\", \"module_part_no\": \"HHM05J-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-NS-004\n  module_part_no: HHM05J-050\n  name: 50ml西林瓶连续离心浓缩\n  category: 浓缩\n  version: 1.0\n  status: active\n  last_updated: 2026/5/13\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 380\n  height_mm: 600\n  weight_kg: 45\n  module_slots: 2\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 30\n  temperature_c_min: 25\n  temperature_c_max: 55\n  speed_rpm_min: 1000\n  speed_rpm_max: 8000\n  pressure_bar_min: 0.1\n  pressure_bar_max: 7\n  vacuum_kpa: -95\nperipherals:\n  required_peripherals: 真空泵\nprocess_capability_1:\n  function_code: 200\n  function_description: 浓缩\n  operation_target: 50ml西林瓶\n  operation_workflow: 载台移至上下料位 - 放入西林瓶 - 加热吹风达到设定温度 - 真空泵开启 - 抽真空/加液管路准备就绪 - 载台移至浓缩位 - 压紧瓶口 - 加样品 - 离心浓缩 - 至浓缩终点(按浓缩时间) -破真空- 加样品 - 离心浓缩 - 重复至全部样品浓缩完毕 -最后一次按流量判断浓缩终点- 停止 - 真空电磁阀关闭 - 破真空 - 载台移至上下料位 - 取下西林瓶\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 1800\n  consumables: 50ml西林瓶/125mlpp瓶/50ml尖底瓶/100ml/200ml尖底瓶\n  sub_functions: [201-复溶, 202-浓缩排空, 203-预热, 204-退出预热, 205-浓缩+复溶]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 底座胶皮,胶条,定位胶垫，密封圈\ntags_meta:\n  tags: [浓缩, 复溶，连续]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.56\n  power_kva_peak: 1\n  voltage_v: 48\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: true\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 50ml西林瓶连续离心浓缩\n\n## Purpose (用途说明)\n该模块用于有机溶剂样品的自动化移液 + 离心浓缩蒸干，适配多种样品瓶与目标西林瓶，实现连续化前处理\n\n## Typical Scenarios (典型应用场景)\n案例 1：有机污染物样品浓缩\n案例 2：农药残留样品前处理\n案例 3：药物研发样品蒸干（药物合成 / 中间体）\n案例 4：食品添加剂与香精香料浓缩\n案例 5：批量样品自动化前处理（高通量）\n\n## Working Principle (工作原理)\n1、移液：注射泵 + 电磁阀切换，自动抽排、清洗，实现无污染精准转移。\n2、浓缩：离心（扩面积）+ 加热（提温度）+ 真空（降沸点） 三效合一，快速蒸干有机溶剂。\n3、全程自动化：三轴运动、定位、夹紧、密封、抽真空、加热、旋转、清洗、出料，全流程无人值守\n\n## Limits & Cautions (限制与注意事项)\n1、装瓶与定位\n瓶子必须放正、夹紧到位，偏心会导致高速旋转振动、漏液、碎瓶。\n西林瓶必须瓶口完好、无裂纹、无崩边，否则密封不严、抽不上真空。\n2、移液与清洗\n移液前确认管路无气泡、电磁阀切换正常，避免空抽、不准量。\n每次样品后必须自动清洗管路与针头，防止交叉污染。\n禁止干抽、空转注射泵，易磨损泵芯。\n3、浓缩过程\n浓缩前确认：真空管路不漏、加热风扇正常、密封轴干净无杂质。\n运行中严禁开盖、伸手、靠近旋转区，防高速飞溅、夹伤。\n红外测温异常时立即停机，防止超温。\n4、结束与维护\n蒸干后必须先破真空、再抬压头、再取瓶，防止负压倒吸。\n长期不用：排空管路、清洗腔体、断电关气、干燥存放。\n\n## Remarks (备注)\n', 'MOD-NS-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
