1, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.18, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-SPE-002\", \"name\": \"20cc SPE模块V2.0\", \"owner\": \"王志/深圳\", \"status\": \"active\", \"version\": 2.0, \"category\": \"SPE\", \"last_updated\": \"2025/5/23\", \"module_part_no\": \"HHM04F-020\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-SPE-002\n  module_part_no: HHM04F-020\n  name: 20cc SPE模块V2.0\n  category: SPE\n  version: 2.0\n  status: active\n  last_updated: 2025/5/23\n  owner: 王志/深圳\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 20\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 121\n  function_description: 活化/上样/淋洗/洗脱/\n  operation_target: 20ml固相萃取柱,35ml钳口瓶,10ml钳口瓶\n  operation_workflow: \"活化：钳口瓶载台移至上下料位 - 钳口瓶放入载台 - SPE柱载台移至排废位 - 密封板下压 - 排废池移至排废位 -  加5ml甲醇 - 正压吹气 - 加5ml纯化水 - 正压吹气 -密封板抬起 / 预洗：SPE柱载台移至上下料位 - 排废池移至SPE柱下方 - 加样品进SPE柱 - SPE柱移至排废位 - 正压吹气 / 淋洗：SPE柱载台移至加液位 - SPE柱移至排废位 - 密封板下压 - 加5ml纯水 - 正压吹气 - 加5ml20%j甲醇 - 正压吹气 - SPE柱吹干 - 密封板抬起 / 洗脱：钳口瓶载台移至接液位 - 加5ml洗脱液 -密封板下压 - 正压吹气 - 密封板抬起 - 钳口瓶载台移至上下料位 - 取下钳口瓶\"\n  absolute_accuracy_pct: 0.1\n  repeat_accuracy_pct: 0.2\n  cycle_time_sec: 900\n  consumables: \"固相萃取柱-20ml / 钳口瓶-35ml / 钳口瓶-10ml / \"\n  sub_functions: [122-活化, 123-SPE底座到过柱位, 124-extra 30cc spe全流程, 125-过滤&接液]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 浓缩模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [SPE, 20cc]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.18\n  power_kva_peak: 0.31\n  voltage_v: 48\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 20cc SPE模块V2.0\n\n## Purpose (用途说明)\n本模块用于实现20ml SPE工艺—上料>>活化>>预柱>>淋洗>>洗脱>>收集，参考31658具体描述为：固相萃取柱依次用甲醇5ml和水5ml活化，取备用液过柱，依次用水5ml和20%甲醇水溶液5ml淋洗，抽干，用洗脱液10ml洗脱，收集洗脱液。\n\n## Typical Scenarios (典型应用场景)\n1、环境样品前处理\n2、食品 / 化工样品净化\n\n\n## Working Principle (工作原理)\n设备通过多轴机械手自动完成样品瓶上下料，依靠气缸压紧实现萃取柱密封，通过多路电磁阀控液、正压气体施压，依次完成萃取柱活化、样品上柱、杂质淋洗、目标物质洗脱流程，借助气压状态判断液体排净情况，整套工序循环运转，实现样品自动化固相萃取分离提纯。\n\n## Limits & Cautions (限制与注意事项)\n1、仅适配 20ml SPE 柱、35ml/10ml 钳口瓶，严禁用其他规格容器。\n2、密封必须到位才能加液 / 加压，漏气、密封不良禁止运行。3、加液、吹气、压力、时间严格按工艺参数执行，不可随意修改。\n4、管路、电磁阀、加液口严禁混用、错接，防止交叉污染。\n5、运行中禁止触碰密封压板、SPE 柱、载台、针头，异常立即急停。\n6、维护需断电、断气、泄压，排净管路残留液体再检修。\n\n## Remarks (备注)\n', 'MOD-SPE-002.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-SPE-003', '10cc自动上样SPE模块', 'HHM04G-901', 'SPE', '1.0', 'active', '王志', '2025/8/1', 'SPE，净化，浓缩', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"SPE，净化，浓缩\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"正压加液\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml/西林瓶-50ml / SPE柱-10ml / \", \"function_code\": 121, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 360, \"operation_target\": \"SPE柱：10ccHLB固相柱（通过更换载具可适配3cc、6ccSPE柱），样品瓶：125PP瓶、50离心管、15ml离心管、20ml西林瓶、10ml西林瓶（可通过更换载具适配不同的容器对象），接收瓶：50离心管或西林瓶（可通过更换载具适配不同的容器对象）\", \"operation_workflow\": \"1.离心管/西林瓶/SPE柱载台移至上下料位 -机械臂将离心管/西林瓶/SPE柱（带填料）放入载台 -Y1轴移至注液位-机械臂1200萃取瓶放入载台- 缓冲池移至取液针下方 -缓存池注入活化液5ml- 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部活化液-切换三通阀 - 将液体注入SPE柱（按照指定速度-重复加活化液2-吹气-Z1轴抬升； / 2.取样针Y轴伸出-取液针Z1轴下降1200ml样品萃取瓶底部-注射泵吸取样品液- 切换三通阀- 注射针插入SPE柱-按照8-10ml/min的速度吐液-重复取样瓶液动作直至取完-吹气-Z1轴抬升-Z2轴抬升 /  / 洗针-取样针Y轴缩回-洗针池移至正下方-注入一定量的液体-取样针下探到洗针次底部-吸吐5次-液体吸入注射泵-Z1轴抬升-Y1轴SPE柱移至注液针下方-Z2轴下降注液针插入SPE柱-三通阀切换-液体注入SPE柱-吹干； / 3. 缓存池移动到取液针下方- 正压加液向缓存池注入20ml甲醇 -  取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部淋洗液-切换三通阀 - 将液体注入SPE柱-按照设定次数重复注液动作-20ml纯水同样动作注入SPE柱-吹气； / 4. 50ml接样瓶移至SPE柱下方- 正压加液向缓存池注入20ml洗脱液 - 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部洗脱液-切换三通阀 - 将液体注入SPE柱---吹气-Z1轴抬升-Z2轴抬升； / 5. Y1轴移动到洗针位- 正压加液向洗针池内注入10ml纯水-取液针下探-吸吐-排废-Z1轴抬升；\", \"repeat_accuracy_pct\": \"±1%\", \"function_description\": \"实现将样品富集和洗脱的功能\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.28, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.168, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-SPE-003\", \"name\": \"10cc自动上样SPE模块\", \"owner\": \"王志\", \"status\": \"active\", \"version\": 1.0, \"category\": \"SPE\", \"last_updated\": \"2025/8/1\", \"module_part_no\": \"HHM04G-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-SPE-003\n  module_part_no: HHM04G-901\n  name: 10cc自动上样SPE模块\n  category: SPE\n  version: 1.0\n  status: active\n  last_updated: 2025/8/1\n  owner: 王志\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 121\n  function_description: 实现将样品富集和洗脱的功能\n  operation_target: SPE柱：10ccHLB固相柱（通过更换载具可适配3cc、6ccSPE柱），样品瓶：125PP瓶、50离心管、15ml离心管、20ml西林瓶、10ml西林瓶（可通过更换载具适配不同的容器对象），接收瓶：50离心管或西林瓶（可通过更换载具适配不同的容器对象）\n  operation_workflow: \"1.离心管/西林瓶/SPE柱载台移至上下料位 -机械臂将离心管/西林瓶/SPE柱（带填料）放入载台 -Y1轴移至注液位-机械臂1200萃取瓶放入载台- 缓冲池移至取液针下方 -缓存池注入活化液5ml- 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部活化液-切换三通阀 - 将液体注入SPE柱（按照指定速度-重复加活化液2-吹气-Z1轴抬升； / 2.取样针Y轴伸出-取液针Z1轴下降1200ml样品萃取瓶底部-注射泵吸取样品液- 切换三通阀- 注射针插入SPE柱-按照8-10ml/min的速度吐液-重复取样瓶液动作直至取完-吹气-Z1轴抬升-Z2轴抬升 /  / 洗针-取样针Y轴缩回-洗针池移至正下方-注入一定量的液体-取样针下探到洗针次底部-吸吐5次-液体吸入注射泵-Z1轴抬升-Y1轴SPE柱移至注液针下方-Z2轴下降注液针插入SPE柱-三通阀切换-液体注入SPE柱-吹干； / 3. 缓存池移动到取液针下方- 正压加液向缓存池注入20ml甲醇 -  取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部淋洗液-切换三通阀 - 将液体注入SPE柱-按照设定次数重复注液动作-20ml纯水同样动作注入SPE柱-吹气； / 4. 50ml接样瓶移至SPE柱下方- 正压加液向缓存池注入20ml洗脱液 - 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部洗脱液-切换三通阀 - 将液体注入SPE柱---吹气-Z1轴抬升-Z2轴抬升； / 5. Y1轴移动到洗针位- 正压加液向洗针池内注入10ml纯水-取液针下探-吸吐-排废-Z1轴抬升；\"\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±1%\n  cycle_time_sec: 360\n  consumables: \"离心管-50ml/西林瓶-50ml / SPE柱-10ml / \"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 正压加液\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [SPE，净化，浓缩]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.168\n  power_kva_peak: 0.28\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 10cc自动上样SPE模块\n\n## Purpose (用途说明)\n用于实现有机样品净化，通过SPE色谱柱分离除去样品中杂质\n\n## Typical Scenarios (典型应用场景)\n中药样品农残检测过程中的样品净化，生物样本的提取净化，中药成分分析的样品净化，食品样品农药残留检测样品净化\n\n## Working Principle (工作原理)\n10cc自动连续上样SPE模块，首先是在标准10cc SPE柱（含上下塞板+填料）里面塞入一个密封胶塞，目的使SPE柱处于密封状态，降低干扰物和液体残留的影响，提高目标物的回收率。通过注射泵吸取缓存池中的活化液注射到密封SPE柱里，润湿和活化SPE柱填料;注射泵从样口瓶里吸取样品液注射到密封SPE柱里，样品中的目标物被吸附在SPE柱填料上；然后注射泵从缓存池吸取淋洗液，淋洗填料上的干扰物和杂质，最后注射泵从缓存池吸取洗脱液，将吸附在填料上的目标物洗脱出来，接样瓶收集洗脱液。\n\n## Limits & Cautions (限制与注意事项)\n本模块固定 2 路并行，适配 10cc HLB 柱，换载具可用 3cc/6cc 柱；样品 / 接收瓶需匹配指定类型。仅 1–50ml、0.1–15ml/min 保证 ±1% 精度；禁高粘、强腐蚀、易堵样品。DC24V、6mm 气源，仅支持 MODBUS TCP，流程模板固定，共用针头需规范洗针，每 6 个月维护\n\n## Remarks (备注)\n', 'MOD-SPE-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-SPE-004', '6cc自动上样SPE模块', 'HHM04H-901', 'SPE', '1.0', 'active', '王志', '2025/8/1', 'SPE，净化，浓缩', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"SPE，净化，浓缩\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"正压加液\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml/西林瓶-50ml / SPE柱-10ml / \", \"function_code\": 121, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 360, \"operation_target\": \"SPE柱：6ccHLB固相柱（通过更换载具可适配3cc、10ccSPE柱），样品瓶：125PP瓶、50离心管、15ml离心管、20ml西林瓶、10ml西林瓶（可通过更换载具适配不同的容器对象），接收瓶：50离心管或西林瓶（可通过更换载具适配不同的容器对象）\", \"operation_workflow\": \"1.离心管/西林瓶/SPE柱载台移至上下料位 -机械臂将离心管/西林瓶/SPE柱（带填料）放入载台 -Y1轴移至注液位-机械臂1200萃取瓶放入载台- 缓冲池移至取液针下方 -缓存池注入活化液5ml- 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部活化液-切换三通阀 - 将液体注入SPE柱（按照指定速度-重复加活化液2-吹气-Z1轴抬升； / 2.取样针Y轴伸出-取液针Z1轴下降1200ml样品萃取瓶底部-注射泵吸取样品液- 切换三通阀- 注射针插入SPE柱-按照8-10ml/min的速度吐液-重复取样瓶液动作直至取完-吹气-Z1轴抬升-Z2轴抬升 /  / 洗针-取样针Y轴缩回-洗针池移至正下方-注入一定量的液体-取样针下探到洗针次底部-吸吐5次-液体吸入注射泵-Z1轴抬升-Y1轴SPE柱移至注液针下方-Z2轴下降注液针插入SPE柱-三通阀切换-液体注入SPE柱-吹干； / 3. 缓存池移动到取液针下方- 正压加液向缓存池注入20ml甲醇 -  取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部淋洗液-切换三通阀 - 将液体注入SPE柱-按照设定次数重复注液动作-20ml纯水同样动作注入SPE柱-吹气； / 4. 50ml接样瓶移至SPE柱下方- 正压加液向缓存池注入20ml洗脱液 - 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部洗脱液-切换三通阀 - 将液体注入SPE柱---吹气-Z1轴抬升-Z2轴抬升； / 5. Y1轴移动到洗针位- 正压加液向洗针池内注入10ml纯水-取液针下探-吸吐-排废-Z1轴抬升；\", \"repeat_accuracy_pct\": \"±1%\", \"function_description\": \"实现将样品富集和洗脱的功能\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.28, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.168, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-SPE-004\", \"name\": \"6cc自动上样SPE模块\", \"owner\": \"王志\", \"status\": \"active\", \"version\": 1.0, \"category\": \"SPE\", \"last_updated\": \"2025/8/1\", \"module_part_no\": \"HHM04H-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-SPE-004\n  module_part_no: HHM04H-901\n  name: 6cc自动上样SPE模块\n  category: SPE\n  version: 1.0\n  status: active\n  last_updated: 2025/8/1\n  owner: 王志\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 121\n  function_description: 实现将样品富集和洗脱的功能\n  operation_target: SPE柱：6ccHLB固相柱（通过更换载具可适配3cc、10ccSPE柱），样品瓶：125PP瓶、50离心管、15ml离心管、20ml西林瓶、10ml西林瓶（可通过更换载具适配不同的容器对象），接收瓶：50离心管或西林瓶（可通过更换载具适配不同的容器对象）\n  operation_workflow: \"1.离心管/西林瓶/SPE柱载台移至上下料位 -机械臂将离心管/西林瓶/SPE柱（带填料）放入载台 -Y1轴移至注液位-机械臂1200萃取瓶放入载台- 缓冲池移至取液针下方 -缓存池注入活化液5ml- 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部活化液-切换三通阀 - 将液体注入SPE柱（按照指定速度-重复加活化液2-吹气-Z1轴抬升； / 2.取样针Y轴伸出-取液针Z1轴下降1200ml样品萃取瓶底部-注射泵吸取样品液- 切换三通阀- 注射针插入SPE柱-按照8-10ml/min的速度吐液-重复取样瓶液动作直至取完-吹气-Z1轴抬升-Z2轴抬升 /  / 洗针-取样针Y轴缩回-洗针池移至正下方-注入一定量的液体-取样针下探到洗针次底部-吸吐5次-液体吸入注射泵-Z1轴抬升-Y1轴SPE柱移至注液针下方-Z2轴下降注液针插入SPE柱-三通阀切换-液体注入SPE柱-吹干； / 3. 缓存池移动到取液针下方- 正压加液向缓存池注入20ml甲醇 -  取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部淋洗液-切换三通阀 - 将液体注入SPE柱-按照设定次数重复注液动作-20ml纯水同样动作注入SPE柱-吹气； / 4. 50ml接样瓶移至SPE柱下方- 正压加液向缓存池注入20ml洗脱液 - 取液针插入缓冲池-注液针插入SPE柱-注射泵吸取全部洗脱液-切换三通阀 - 将液体注入SPE柱---吹气-Z1轴抬升-Z2轴抬升； / 5. Y1轴移动到洗针位- 正压加液向洗针池内注入10ml纯水-取液针下探-吸吐-排废-Z1轴抬升；\"\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±1%\n  cycle_time_sec: 360\n  consumables: \"离心管-50ml/西林瓶-50ml / SPE柱-10ml / \"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 正压加液\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [SPE，净化，浓缩]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.168\n  power_kva_peak: 0.28\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 6cc自动上样SPE模块\n\n## Purpose (用途说明)\n用于实现有机样品净化，通过SPE色谱柱分离除去样品中杂质\n\n## Typical Scenarios (典型应用场景)\n中药样品农残检测过程中的样品净化，生物样本的提取净化，中药成分分析的样品净化，食品样品农药残留检测样品净化\n\n## Working Principle (工作原理)\n6cc自动连续上样SPE模块，首先是在标准6cc SPE柱（含上下塞板+填料）里面塞入一个密封胶塞，目的使SPE柱处于密封状态，降低干扰物和液体残留的影响，提高目标物的回收率。通过注射泵吸取缓存池中的活化液注射到密封SPE柱里，润湿和活化SPE柱填料;注射泵从样口瓶里吸取样品液注射到密封SPE柱里，样品中的目标物被吸附在SPE柱填料上；然后注射泵从缓存池吸取淋洗液，淋洗填料上的干扰物和杂质，最后注射泵从缓存池吸取洗脱液，将吸附在填料上的目标物洗脱出来，接样瓶收集洗脱液。\n\n## Limits & Cautions (限制与注意事项)\n本模块固定 2 路并行，适配 6cc HLB 柱，换载具可用 3cc/6cc 柱；样品 / 接收瓶需匹配指定类型。仅 1–50ml、0.1–15ml/min 保证 ±1% 精度；禁高粘、强腐蚀、易堵样品。DC24V、6mm 气源，仅支持 MODBUS TCP，流程模板固定，共用针头需规范洗针，每 6 个月维护\n\n## Remarks (备注)\n', 'MOD-SPE-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-TDS-001', 'TDS测定模块', '3256000077', 'TDS', '2.0', 'active', '朱园林', '2025/5/9', '测TDS，TDS校准', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"测TDS\", \"TDS校准\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"无\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"塑料瓶-30ml / 塑料瓶-125ml\", \"function_code\": 60, \"sub_functions\": [\"60 测TDS ，61 TDS校准\"], \"cycle_time_sec\": 270, \"operation_target\": \"30ml塑料瓶，125ml塑料瓶\", \"operation_workflow\": \"电极移至高位等待 - 校正液放入校正液载台 - 电极移至校正位 - 深入使校正液没过电极头 - 自动校准（使用不同浓度校正液重复校准过程） - 电极移出至冲洗位 -冲洗吹干（参考冲洗吹干效果测试结果） - 电极移出至冲洗位 - 冲洗吹干 - 样品放入样品载台- 电极移到检测位 - 深入使样品没过电极头 - 检测 - 电极移出至冲洗位 - 冲洗吹干 - 电极移至高位 - 取下样品\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"测TDS\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.244, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.1464, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-TDS-001\", \"name\": \"TDS测定模块\", \"owner\": \"朱园林\", \"status\": \"active\", \"version\": 2.0, \"category\": \"TDS\", \"last_updated\": \"2025/5/9\", \"module_part_no\": 3256000077}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-TDS-001\n  module_part_no: 3256000077\n  name: TDS测定模块\n  category: TDS\n  version: 2.0\n  status: active\n  last_updated: 2025/5/9\n  owner: 朱园林\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 60\n  function_description: 测TDS\n  operation_target: 30ml塑料瓶，125ml塑料瓶\n  operation_workflow: 电极移至高位等待 - 校正液放入校正液载台 - 电极移至校正位 - 深入使校正液没过电极头 - 自动校准（使用不同浓度校正液重复校准过程） - 电极移出至冲洗位 -冲洗吹干（参考冲洗吹干效果测试结果） - 电极移出至冲洗位 - 冲洗吹干 - 样品放入样品载台- 电极移到检测位 - 深入使样品没过电极头 - 检测 - 电极移出至冲洗位 - 冲洗吹干 - 电极移至高位 - 取下样品\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 270\n  consumables: \"塑料瓶-30ml / 塑料瓶-125ml\"\n  sub_functions: [60 测TDS ，61 TDS校准]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [测TDS, TDS校准]\ndocumentation:\n  urs_url: 无\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.1464\n  power_kva_peak: 0.244\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# TDS测定模块\n\n## Purpose (用途说明)\n自动化控制电导率电极对样本液测定，并实现电极的清洗\n\n## Typical Scenarios (典型应用场景)\n水样 / 溶液 TDS（电导率）自动化检测 + 电极自动维护\n适用于水质检测、环境监测、实验室样本分析，对待测样本液进行全自动 TDS 测定，全程自动完成电极校准→样本检测→清洗→吹干，无需人工值守，保证测量准确、无交叉污染。\n\n## Working Principle (工作原理)\n模块基于电导率换算原理开展检测，电极探头浸入水样后，水体中溶解离子可传导微弱电流，模块电路实时检测水体电导率数值。\n\n## Limits & Cautions (限制与注意事项)\n1、检测前必须完成三点校准，校准失效 / 电极异常禁止测样。2、电极必须清洗 + 吹干后再测下一样本，防止交叉污染。\n3、运行中禁止触碰电极、XYZ 运动轴、清洗位，避免撞针与损坏。\n4、确保清洗液、气源、废液排放正常，无水、无气禁止运行\n5、异常立即急停，断电断气后再维护，禁止湿手操作电控部件。\n6、电极轻拿轻放，禁止碰撞、划伤探头，保持探头清洁\n\n## Remarks (备注)\n', 'MOD-TDS-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-001', '2ml离心管拆装盖涡旋模块', 'HHM03H-002', '涡旋', '3.0', 'active', '蔡勤超', '2026/1/30', '拆盖，装盖，涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"拆盖，装盖，涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": 2, \"volume_ml_min\": 1, \"pressure_bar_max\": 3, \"pressure_bar_min\": 1.5, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"涡旋底部胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"2ml 离心管\", \"function_code\": 169, \"sub_functions\": [\"165-拆盖\", \"166-装盖\"], \"cycle_time_sec\": 295, \"operation_target\": \"2ml离心管\", \"operation_workflow\": \"载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 拆盖（保持夹住瓶盖）- 载台移至加液位 - 加液（纯水）- 载台移至拆合盖位 - 合盖 - 载台移至涡旋位 - 涡旋（3000rpm，100s）- 载台移至上下料位 - 取下离心管；更换离心管，重复测试\", \"repeat_accuracy_pct\": \"±0.5\", \"function_description\": \"2ml离心管  加液/装盖/涡旋/拆盖：\", \"absolute_accuracy_pct\": \"±1\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 230, \"requires_drain\": true, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 380, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-001\", \"name\": \"2ml离心管拆装盖涡旋模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 3.0, \"category\": \"涡旋\", \"last_updated\": \"2026/1/30\", \"module_part_no\": \"HHM03H-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-001\n  module_part_no: HHM03H-002\n  name: 2ml离心管拆装盖涡旋模块\n  category: 涡旋\n  version: 3.0\n  status: active\n  last_updated: 2026/1/30\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 2\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1.5\n  pressure_bar_max: 3\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 169\n  function_description: 2ml离心管  加液/装盖/涡旋/拆盖：\n  operation_target: 2ml离心管\n  operation_workflow: 载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 拆盖（保持夹住瓶盖）- 载台移至加液位 - 加液（纯水）- 载台移至拆合盖位 - 合盖 - 载台移至涡旋位 - 涡旋（3000rpm，100s）- 载台移至上下料位 - 取下离心管；更换离心管，重复测试\n  absolute_accuracy_pct: ±1\n  repeat_accuracy_pct: ±0.5\n  cycle_time_sec: 295\n  consumables: 2ml 离心管\n  sub_functions: [165-拆盖, 166-装盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 涡旋底部胶皮\ntags_meta:\n  tags: [拆盖，装盖，涡旋]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 380\n  power_kva_peak: 230\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: true', '# 2ml离心管拆装盖涡旋模块\n\n## Purpose (用途说明)\n利用 2ml 离心管拆装盖涡旋模块完成试管拆盖作业，再按规范作业流程完成封盖复位装盖\n\n## Typical Scenarios (典型应用场景)\n血样\n\n## Working Principle (工作原理)\n该模块搭配涡旋主机使用，依靠偏心圆周旋转动力，配合顶部弹性压紧限位结构，实现拆盖、涡旋混匀、复位装盖一体化作业。工作时将 2ml 离心管整齐定位放置，压紧机构抵住管盖使其保持静止，设备带动管身做圆周偏心转动，利用管身与管盖之间形成的相对扭转力，完成自动松盖拆盖；松开压紧限位后，管盖与管体同步跟随模块做高频涡旋运动，管内液体形成漩涡流动，快速完成样品混匀；混匀结束后再次压紧固定管盖，调整运转方向与扭力，使管身反向旋转，匀速将管盖旋紧密封，整套流程借助同一组涡旋驱动结构，通过压紧限位的切换，依次完成拆盖、混匀、装盖全流程作业。\n\n## Limits & Cautions (限制与注意事项)\n涡旋不着超过3000，一般在2000-2500\n\n## Remarks (备注)\n', 'MOD-WX-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-003', '15ml离心管拆盖正压加液涡旋模块', 'HHM03H-015', '涡旋', '2.0', 'active', '蔡勤超', '2026/1/30', '正压加液、加液涡旋、涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"正压加液、加液涡旋、涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": 15, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"工位硅胶条，涡旋下压胶皮，涡旋胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"正压加液系统\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": 171, \"sub_functions\": [\"165-拆盖\", \"166-装盖\", \"167-去加液位，168-去待机位，169-拆盖/去加液，170-装盖/涡旋\"], \"cycle_time_sec\": 300, \"operation_target\": \"15ml离心管\", \"operation_workflow\": \"1.拆盖：载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪向下移动到达离心管位置 - 夹紧瓶盖 - 旋转并向上打开瓶盖（保持夹住瓶盖）； / 2.加液：松开离心管 - 载台移至加液位 - 加液 / 3.关盖：载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 松开离心管 / 4.涡旋\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"离心管装盖涡旋混匀拆盖\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-003\", \"name\": \"15ml离心管拆盖正压加液涡旋模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 2.0, \"category\": \"涡旋\", \"last_updated\": \"2026/1/30\", \"module_part_no\": \"HHM03H-015\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-003\n  module_part_no: HHM03H-015\n  name: 15ml离心管拆盖正压加液涡旋模块\n  category: 涡旋\n  version: 2.0\n  status: active\n  last_updated: 2026/1/30\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 15\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 171\n  function_description: 离心管装盖涡旋混匀拆盖\n  operation_target: 15ml离心管\n  operation_workflow: \"1.拆盖：载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪向下移动到达离心管位置 - 夹紧瓶盖 - 旋转并向上打开瓶盖（保持夹住瓶盖）； / 2.加液：松开离心管 - 载台移至加液位 - 加液 / 3.关盖：载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 松开离心管 / 4.涡旋\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 300\n  consumables: 离心管-50ml\n  sub_functions: [165-拆盖, 166-装盖, 167-去加液位，168-去待机位，169-拆盖/去加液，170-装盖/涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 正压加液系统\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 工位硅胶条，涡旋下压胶皮，涡旋胶皮\ntags_meta:\n  tags: [正压加液、加液涡旋、涡旋]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 15ml离心管拆盖正压加液涡旋模块\n\n## Purpose (用途说明)\n用于实验室样本前处理，实现试剂添加与样本混匀全流程自动化，减少人工干预、避免污染、提升处理一致性与效率\n\n## Typical Scenarios (典型应用场景)\n1、核酸检测前处理（PCR 样本制备）\n2、生化 / 免疫检测试剂配制与样本混匀\n3、生物制药细胞上清 / 发酵液处理\n4、微生物 / 环境检测样品前处理\n\n## Working Principle (工作原理)\n利用电机驱动离心管水平圆周偏心运动，使管内液体受离心力作用沿管壁形成螺旋涡流，产生层流剪切力 + 湍流扰动，打破颗粒团聚、加速试剂溶解均匀\n\n## Limits & Cautions (限制与注意事项)\n涡旋速度最高3000\n\n## Remarks (备注)\n', 'MOD-WX-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-004', '50ml离心管单涡旋模块', 'HHM03K-050', '涡旋', '1.0', 'active', '蔡勤超', '2026/3/27', '涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1000, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"涡旋下胶皮，涡旋上胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": 223, \"sub_functions\": [], \"cycle_time_sec\": 220, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"载台移至上下料位-样品离心管放入卡槽-载台移至瓶盖检测位-确认上料成功--载台移至涡旋位-涡旋-载台移至上下料位-取走离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"涡旋\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-004\", \"name\": \"50ml离心管单涡旋模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 1.0, \"category\": \"涡旋\", \"last_updated\": \"2026/3/27\", \"module_part_no\": \"HHM03K-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-004\n  module_part_no: HHM03K-050\n  name: 50ml离心管单涡旋模块\n  category: 涡旋\n  version: 1.0\n  status: active\n  last_updated: 2026/3/27\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1000\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 223\n  function_description: 涡旋\n  operation_target: 50ml离心管\n  operation_workflow: 载台移至上下料位-样品离心管放入卡槽-载台移至瓶盖检测位-确认上料成功--载台移至涡旋位-涡旋-载台移至上下料位-取走离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 220\n  consumables: 离心管-50ml\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 涡旋下胶皮，涡旋上胶皮\ntags_meta:\n  tags: [涡旋]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml离心管单涡旋模块\n\n## Purpose (用途说明)\n实现50ml离心管通过涡旋的方式使样品液充分混合/溶解\n\n## Typical Scenarios (典型应用场景)\n实验室前处理、生化 / 免疫检测、环境 / 食品检测、生物制药、科研实验\n\n## Working Principle (工作原理)\n模块依靠Y 轴定位 + 气动压紧 + 高速偏心涡旋 + 传感器闭环，实现 50ml 离心管自动对位、压紧、高速涡旋混匀、松压复位，核心是偏心旋转振动 + 气动稳定夹持 + 精准时序控制。\n\n## Limits & Cautions (限制与注意事项)\n仅适配标准 50ml 尖底离心管；适用低粘度水相 / 常规试剂，禁高粘、结晶、含颗粒、强腐蚀液体。最高 3000rpm、振幅 ±2mm，单次连续不超 10 分钟，单管液体≤45ml。环境 10–35℃、湿度 30%–70% RH，DC24V 供电、稳定气源。运行中禁干预；试管需卡紧；定期更换橡胶垫、校准转速；异响 / 漏液先断电处理\n\n## Remarks (备注)\n', 'MOD-WX-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-005', '5ml离心管拆盖加液涡旋吸磁模块', 'HHM50B-005', '涡旋', '1.0', 'active', '涂高祥', '2025/9/12', '加液、涡旋、吸磁', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液、涡旋、吸磁\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": 4, \"volume_ml_min\": 0.02, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"涡旋压紧件上的海绵\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"离心管-5ml\", \"function_code\": 167, \"sub_functions\": [\"165-拆盖，166-装盖，168-拆盖/加液/装盖/涡旋/拆盖，169-加液/装盖/涡旋/拆盖，170-装盖/涡旋，171-加液/装盖/涡旋\"], \"cycle_time_sec\": 60, \"operation_target\": \"5ml离心管\", \"operation_workflow\": \"初始化-上料离心管-传感器检测反馈上料成功-Y轴到拆盖位置-气缸动作夹紧离心管-拧盖-Y轴到上下料位-移液-Y轴到加液为止-加液-Y轴到拧盖位-拧盖-Y轴到涡旋位-涡旋-Y轴到下料位-下料-结束\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"拆盖/加液/装盖/涡旋\", \"absolute_accuracy_pct\": \"(1)1ml：±0.7％ / (2)0.3~0.5ml：±2％ / (3)0.02~0.1ml：±3％\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.574, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.344, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-005\", \"name\": \"5ml离心管拆盖加液涡旋吸磁模块\", \"owner\": \"涂高祥\", \"status\": \"active\", \"version\": 1.0, \"category\": \"涡旋\", \"last_updated\": \"2025/9/12\", \"module_part_no\": \"HHM50B-005\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-005\n  module_part_no: HHM50B-005\n  name: 5ml离心管拆盖加液涡旋吸磁模块\n  category: 涡旋\n  version: 1.0\n  status: active\n  last_updated: 2025/9/12\n  owner: 涂高祥\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.02\n  volume_ml_max: 4\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 167\n  function_description: 拆盖/加液/装盖/涡旋\n  operation_target: 5ml离心管\n  operation_workflow: 初始化-上料离心管-传感器检测反馈上料成功-Y轴到拆盖位置-气缸动作夹紧离心管-拧盖-Y轴到上下料位-移液-Y轴到加液为止-加液-Y轴到拧盖位-拧盖-Y轴到涡旋位-涡旋-Y轴到下料位-下料-结束\n  absolute_accuracy_pct: \"(1)1ml：±0.7％ / (2)0.3~0.5ml：±2％ / (3)0.02~0.1ml：±3％\"\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 60\n  consumables: 离心管-5ml\n  sub_functions: [165-拆盖，166-装盖，168-拆盖/加液/装盖/涡旋/拆盖，169-加液/装盖/涡旋/拆盖，170-装盖/涡旋，171-加液/装盖/涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 涡旋压紧件上的海绵\ntags_meta:\n  tags: [加液、涡旋、吸磁]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.344\n  power_kva_peak: 0.574\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 5ml离心管拆盖加液涡旋吸磁模块\n\n## Purpose (用途说明)\n5ml离心管拆盖，加入一定液体，装盖，涡旋混匀，拆盖吸磁，弃掉废液。\n\n## Typical Scenarios (典型应用场景)\n本模块主要用于生物样本前处理、核酸提取、蛋白纯化、免疫磁分离、IVD 检测，实现离心管自动拆盖、吸磁、多通道加液、盖盖、涡旋混匀，显著提升自动化水平与实验稳定性\n\n## Working Principle (工作原理)\n模块由平移 / Z 轴电机、电爪、吸磁机构、4 通道加液电磁阀、涡旋电机组成，PLC 全流程控制。\n平移电机将 5ml 离心管移至拆盖位，吸磁机构吸附管内磁珠，电爪旋开管盖；移至加液位，电磁阀精准加注 20μL–4ml 试剂；随后旋紧管盖，移至涡旋位高速混匀（0–3000rpm），最后送回上下料位，完成拆盖、吸磁、加液、旋盖、涡旋全自动化作业。\n\n## Limits & Cautions (限制与注意事项)\n限制：仅适配 5ml 尖底离心管；液体需兼容材质、无强腐蚀；磁珠粒径 / 磁性需匹配吸磁机构；加液范围 20μL–4ml、涡旋≤3000rpm。\n\n## Remarks (备注)\n', 'MOD-WX-005.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-006', '50ml离心管正压加液涡旋模块', 'HHM03H-050', '涡旋', '2.0', 'active', '何向东', '2025/1/17', '正压加液、加液涡旋、涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"正压加液、加液涡旋、涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": 171, \"sub_functions\": [\"165-拆盖\", \"166-装盖\", \"167-去加液位，168-去待机位，169-拆盖/去加液，170-装盖/涡旋\"], \"cycle_time_sec\": 300, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"1.拆盖：载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪向下移动到达离心管位置 - 夹紧瓶盖 - 旋转并向上打开瓶盖（保持夹住瓶盖）； / 2.加液：松开离心管 - 载台移至加液位 - 加液 / 3.关盖：载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 松开离心管 / 4.涡旋\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"离心管装盖涡旋混匀拆盖\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-006\", \"name\": \"50ml离心管正压加液涡旋模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 2.0, \"category\": \"涡旋\", \"last_updated\": \"2025/1/17\", \"module_part_no\": \"HHM03H-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-006\n  module_part_no: HHM03H-050\n  name: 50ml离心管正压加液涡旋模块\n  category: 涡旋\n  version: 2.0\n  status: active\n  last_updated: 2025/1/17\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 171\n  function_description: 离心管装盖涡旋混匀拆盖\n  operation_target: 50ml离心管\n  operation_workflow: \"1.拆盖：载台移至上下料位 - 放入离心管 - 载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪向下移动到达离心管位置 - 夹紧瓶盖 - 旋转并向上打开瓶盖（保持夹住瓶盖）； / 2.加液：松开离心管 - 载台移至加液位 - 加液 / 3.关盖：载台移至拆合盖位 - 夹紧离心管 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 松开离心管 / 4.涡旋\"\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 300\n  consumables: 离心管-50ml\n  sub_functions: [165-拆盖, 166-装盖, 167-去加液位，168-去待机位，169-拆盖/去加液，170-装盖/涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [正压加液、加液涡旋、涡旋]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml离心管正压加液涡旋模块\n\n## Purpose (用途说明)\n用于实验室样本前处理，实现试剂添加与样本混匀全流程自动化，减少人工干预、避免污染、提升处理一致性与效率\n\n## Typical Scenarios (典型应用场景)\n1、核酸检测前处理（PCR 样本制备）\n2、生化 / 免疫检测试剂配制与样本混匀\n3、生物制药细胞上清 / 发酵液处理\n4、微生物 / 环境检测样品前处理\n\n## Working Principle (工作原理)\n利用电机驱动离心管水平圆周偏心运动，使管内液体受离心力作用沿管壁形成螺旋涡流，产生层流剪切力 + 湍流扰动，打破颗粒团聚、加速试剂溶解均匀\n\n## Limits & Cautions (限制与注意事项)\n涡旋速度最高3000\n\n## Remarks (备注)\n', 'MOD-WX-006.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-007', '2ml离心管正压加液涡旋模块V3.0', 'HHM03H-002', '涡旋', '3.0', 'active', '何向东', '2025/3/14', '加液，涡旋，2ml离心管', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液，涡旋，2ml离心管\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1000, \"volume_ml_max\": 2, \"volume_ml_min\": 0, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"离心管-2ml / \", \"function_code\": 222, \"sub_functions\": [\"加液，涡旋\"], \"cycle_time_sec\": 290, \"operation_target\": \"2ml离心管\", \"operation_workflow\": \"上料：两个带盖的2ml离心管；拆盖：带盖2ml离心管拆盖；加液：加液；装盖：离心管装盖；涡旋：按照转速和时间进行涡旋；下料：2个带盖带料的2ml离心管。\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"本模块预期实现：2ml离心管正压加液涡旋功能。\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.52, \"requires_drain\": false, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.31, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-007\", \"name\": \"2ml离心管正压加液涡旋模块V3.0\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 3.0, \"category\": \"涡旋\", \"last_updated\": \"2025/3/14\", \"module_part_no\": \"HHM03H-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-007\n  module_part_no: HHM03H-002\n  name: 2ml离心管正压加液涡旋模块V3.0\n  category: 涡旋\n  version: 3.0\n  status: active\n  last_updated: 2025/3/14\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 2\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1000\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 222\n  function_description: 本模块预期实现：2ml离心管正压加液涡旋功能。\n  operation_target: 2ml离心管\n  operation_workflow: 上料：两个带盖的2ml离心管；拆盖：带盖2ml离心管拆盖；加液：加液；装盖：离心管装盖；涡旋：按照转速和时间进行涡旋；下料：2个带盖带料的2ml离心管。\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 290\n  consumables: \"离心管-2ml / \"\n  sub_functions: [加液，涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [加液，涡旋，2ml离心管]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.31\n  power_kva_peak: 0.52\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: false', '# 2ml离心管正压加液涡旋模块V3.0\n\n## Purpose (用途说明)\n\n\n## Typical Scenarios (典型应用场景)\n1.PCR / 荧光定量 PCR 体系自动配制\n3.IVD 试剂：样本保存液、裂解液、缓冲液自动分装\n4.抗原抗体反应、免疫检测加液 + 混匀\n5.血清 / 血浆 / 尿液样本加液与涡旋混匀\n6.食品安全、农残、重金属检测前处理\n7.疾控 / 医院检验自动化样本处理系统\n\n## Working Principle (工作原理)\n通过Y 轴工位移动 + 电动夹爪旋盖 + 正压定量加液 + 涡旋混匀，全自动完成开盖 — 加液 — 混匀 — 关盖一体化流程。\n\n## Limits & Cautions (限制与注意事项)\n1.仅限2ml 离心管，加液0.5–2ml\n2.正压压力稳定、密封完好、先泄压再操作\n3.必须先夹紧，再旋盖 / 加液 / 涡旋\n4.无瓶不运行、异常立即停机\n5.运动区禁伸手，管路用完及时清洗\n\n## Remarks (备注)\n', 'MOD-WX-007.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-WX-008', '10ml比色管拔塞摇匀模块', 'HHM01E-010', '涡旋', '1.0', 'active', '何向东', '2025/5/23', '涡旋，拔塞，装塞', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"涡旋，拔塞，装塞\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指胶皮、涡旋胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"比色管-10ml / \", \"function_code\": 270, \"sub_functions\": [], \"cycle_time_sec\": 100, \"operation_target\": \"10ml比色管\", \"operation_workflow\": \"比色管放入载台 - 载台移至拆盖位 - 夹紧比色管 - 拆盖夹爪下降 - 拆盖 - 夹爪夹持管盖上升 - 松开比色管 - 载台移至上下料位 - 取走比色管 装什么液体 - 比色管放回载台 - 载台移至拆盖位 -  夹紧比色管 - 拆盖夹爪下降 - 装盖 - 夹爪上升 - 松开比色管 - 载台移至混匀位 - 涡旋气缸下压 - 混匀100s - 停止 - 涡旋气缸抬起 - 载台移至上下料位 - 取下比色管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"启动摇匀\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-WX-008\", \"name\": \"10ml比色管拔塞摇匀模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 1.0, \"category\": \"涡旋\", \"last_updated\": \"2025/5/23\", \"module_part_no\": \"HHM01E-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-WX-008\n  module_part_no: HHM01E-010\n  name: 10ml比色管拔塞摇匀模块\n  category: 涡旋\n  version: 1.0\n  status: active\n  last_updated: 2025/5/23\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 270\n  function_description: 启动摇匀\n  operation_target: 10ml比色管\n  operation_workflow: 比色管放入载台 - 载台移至拆盖位 - 夹紧比色管 - 拆盖夹爪下降 - 拆盖 - 夹爪夹持管盖上升 - 松开比色管 - 载台移至上下料位 - 取走比色管 装什么液体 - 比色管放回载台 - 载台移至拆盖位 -  夹紧比色管 - 拆盖夹爪下降 - 装盖 - 夹爪上升 - 松开比色管 - 载台移至混匀位 - 涡旋气缸下压 - 混匀100s - 停止 - 涡旋气缸抬起 - 载台移至上下料位 - 取下比色管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 100\n  consumables: \"比色管-10ml / \"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指胶皮、涡旋胶皮\ntags_meta:\n  tags: [涡旋，拔塞，装塞]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 10ml比色管拔塞摇匀模块\n\n## Purpose (用途说明)\n10ml比色管的上下料、涡旋、拔塞装塞功能\n\n## Typical Scenarios (典型应用场景)\n1、水质检测10ml 比色管自动拔塞、装塞、涡旋混匀一体化处理\n2、水样前处理产线开盖取样 + 混匀 + 回盖全自动工位\n3、COD、总磷、总氮等指标比色管样品快速涡旋摇匀前处理\n4、实验室小体积试剂自动开盖 + 高速涡旋混匀场景\n5、机械手联动10ml 比色管全自动上下料、拔塞、摇匀流水线\n\n## Working Principle (工作原理)\n通过 Y 轴、Z 轴步进模组配合电动旋转夹爪与夹紧、下压气缸，自动完成比色管上下料、拔塞、装塞及涡旋混匀的一体化流程\n\n## Limits & Cautions (限制与注意事项)\n1、定期清洁光电开关、夹爪、涡旋台面，保持无液体、无粉尘\n2、检查电机线、传感器线、气缸线无松动、无破损。\n3、导轨、滑动部件定期润滑，保证运动顺畅。\n4、涡旋电机、电动夹爪不可长时间连续满载运行，避免过热\n5、定位不准、丢步时，重新回零校准再启动。\n6、气路需定期排水排污，防止损坏气缸与电磁阀。\n\n## Remarks (备注)\n', 'MOD-WX-008.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-XC-001', '2ml离心管/西林瓶拆盖吸磁模块', 'HHM02Q-002', '吸磁', '1.0', 'active', '蔡勤超', '2026/4/3', '拆装盖吸磁', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"拆装盖吸磁\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"夹爪胶条\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"离心管-2ml / 西林瓶-2ml\", \"function_code\": \"165,166\", \"sub_functions\": [], \"cycle_time_sec\": 97, \"operation_target\": \"2ml离心管，2ml西林瓶\", \"operation_workflow\": \"1.2ml离心管或2ml西林瓶进行拆盖 / 2.2ml离心管或2ml西林瓶进行装盖\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"拆装盖\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-XC-001\", \"name\": \"2ml离心管/西林瓶拆盖吸磁模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 1.0, \"category\": \"吸磁\", \"last_updated\": \"2026/4/3\", \"module_part_no\": \"HHM02Q-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-XC-001\n  module_part_no: HHM02Q-002\n  name: 2ml离心管/西林瓶拆盖吸磁模块\n  category: 吸磁\n  version: 1.0\n  status: active\n  last_updated: 2026/4/3\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 165,166\n  function_description: 拆装盖\n  operation_target: 2ml离心管，2ml西林瓶\n  operation_workflow: \"1.2ml离心管或2ml西林瓶进行拆盖 / 2.2ml离心管或2ml西林瓶进行装盖\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 97\n  consumables: \"离心管-2ml / 西林瓶-2ml\"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 夹爪胶条\ntags_meta:\n  tags: [拆装盖吸磁]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 2ml离心管/西林瓶拆盖吸磁模块\n\n## Purpose (用途说明)\n用于2ml西林瓶或2ml离心管进行拆装盖操作，同时瓶壁两侧带磁吸可将样品中磁性物质吸附在壁上\n\n## Typical Scenarios (典型应用场景)\n血样\n\n## Working Principle (工作原理)\n通过电动夹爪下降至拆/拧盖位，夹紧瓶子，旋转电爪逆时针或顺时针旋转约3圈后，瓶盖拧开或盖上，另外在瓶壁两侧加装磁铁，将瓶内样品中磁性物质吸附至两侧\n\n## Limits & Cautions (限制与注意事项)\n仅适配标准 2ml 离心管 / 西林瓶及配套螺纹盖；高紧固 / 锈蚀瓶盖慎用。工作环境 10–35℃、湿度 30%–70% RH，DC24V 供电、0.5MPa 洁净气源。运行中禁干预；瓶管需直立卡紧；定期更换夹爪胶条、校准定位与力矩；打滑 / 异响先断电排查\n\n## Remarks (备注)\n', 'MOD-XC-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-XJ-001', '150ml锥形瓶电热板加热消解', 'NA', '消解', '1.0', 'active', '汪健', '2025/5/9', '加热消解', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加热消解\"]}, \"peripherals\": {\"required_peripherals\": \"抽风机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": 300, \"temperature_c_min\": 0}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液模块\"]}, \"process_capability_1\": {\"consumables\": \"150ml锥形瓶\", \"function_code\": 540, \"sub_functions\": [\"540-启动锥形瓶加热消解\"], \"cycle_time_sec\": 1800, \"operation_target\": \"150ml锥形瓶\", \"operation_workflow\": \"加热台移至上下料位 - 放入锥形瓶 - 瓶座移至消解位 - 加热台与防护罩贴合 - 排气扇开启 - 加热开启 -保温- 消解 - 持续排除酸雾 - 按时间固定工艺 - 加热停止 - 排气扇关闭 - 加热台移至上下料位 - 取下锥形瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"150ml锥形瓶的加热、将酸气引入通风厨排放功能\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 1.8, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"true\", \"power_kva_nominal\": 1.08, \"requires_ventilation\": true, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-XJ-001\", \"name\": \"150ml锥形瓶电热板加热消解\", \"owner\": \"汪健\", \"status\": \"active\", \"version\": 1.0, \"category\": \"消解\", \"last_updated\": \"2025/5/9\", \"module_part_no\": \"NA\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-XJ-001\n  module_part_no: NA\n  name: 150ml锥形瓶电热板加热消解\n  category: 消解\n  version: 1.0\n  status: active\n  last_updated: 2025/5/9\n  owner: 汪健\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: 0\n  temperature_c_max: 300\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 抽风机\nprocess_capability_1:\n  function_code: 540\n  function_description: 150ml锥形瓶的加热、将酸气引入通风厨排放功能\n  operation_target: 150ml锥形瓶\n  operation_workflow: 加热台移至上下料位 - 放入锥形瓶 - 瓶座移至消解位 - 加热台与防护罩贴合 - 排气扇开启 - 加热开启 -保温- 消解 - 持续排除酸雾 - 按时间固定工艺 - 加热停止 - 排气扇关闭 - 加热台移至上下料位 - 取下锥形瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 1800\n  consumables: 150ml锥形瓶\n  sub_functions: [540-启动锥形瓶加热消解]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [加热消解]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 1.08\n  power_kva_peak: 1.8\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: true\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 150ml锥形瓶电热板加热消解\n\n## Purpose (用途说明)\n锥形瓶的加热、将酸气引入通风厨排放功能\n\n## Typical Scenarios (典型应用场景)\n实验室样品自动化加热消解与酸气处理\n面向食品、环境、水质、土壤等检测实验室，对150ml 锥形瓶内样品进行高温加热消解，同时自动密封、抽风排酸气，实现无人值守、安全高效的样品前处理。\n\n## Working Principle (工作原理)\n150mL 锥形瓶搭配电热板加热消解，依靠电热板内部电阻丝通电后将电能转化为热能，热量通过板面以热传导形式贴合锥形瓶瓶底传递至瓶内消解试样，瓶内液体受热产生自然对流，让整体物料均匀升温，设备温控组件实时监测板面温度并动态调节加热功率，稳定维持设定消解温度，高温环境下消解试剂与样品充分发生氧化、分解、溶出等化学反应，破坏样品原有基体结构，使待测组分分离析出，锥形瓶敞口结构可顺畅排出反应产生的废气与气体，保障消解反应持续稳定进行，整体操作需在通风环境下开展，加热过程循序渐进控温，避免液体暴沸溅出，保证消解作业安全与检测结果准确性。\n\n## Limits & Cautions (限制与注意事项)\n1、仅适配150ml 锥形瓶，必须放正、无破损、无漏液，禁止空瓶高温干烧。\n2、加热温度 **≤300℃**，PT100 传感器异常、温控失效禁止加热。\n3、加热前必须防护罩合盖到位，并开启排气扇排酸气，严禁敞开加热。\n4、运行中禁止触碰高温加热台、防护罩、运动轴，防止烫伤与夹伤。\n5、消解完成必须自然降温后再取瓶，维护需断电冷却后操作。\n6、禁止在无通风、易燃、腐蚀性超标环境使用，保持排气通畅。\n\n## Remarks (备注)\n', 'MOD-XJ-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YJ-001', '250ml锥形瓶连续加盐模块', 'HHM11B-250', '加盐', '1.0', 'active', '王志', '2025/11/7', '加盐', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加盐\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 250, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"锥形瓶-250ml\", \"function_code\": 225, \"sub_functions\": [\"225 加盐\"], \"cycle_time_sec\": \"(1)1g  30S / (2)5g  90S / (3)10g  120\", \"operation_target\": \"250ml锥形瓶\", \"operation_workflow\": \"盐罐放入浮动载台 - 齿盘啮合 - 250ml锥形瓶载台移至上下料位 - 称重传感器清零 - 250ml锥形瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 250ml锥形瓶载台移至上下料位 - 取下250ml锥形瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换250ml锥形瓶，重复测试\", \"repeat_accuracy_pct\": \"(1)0.1-1g  ±10% / (2)1-10g  ±3%\", \"function_description\": \"加盐\", \"absolute_accuracy_pct\": \"(1)0.1-1g  ±10% / (2)1-10g  ±3%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 48, \"power_kva_peak\": 0.14, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.084, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YJ-001\", \"name\": \"250ml锥形瓶连续加盐模块\", \"owner\": \"王志\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加盐\", \"last_updated\": \"2025/11/7\", \"module_part_no\": \"HHM11B-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YJ-001\n  module_part_no: HHM11B-250\n  name: 250ml锥形瓶连续加盐模块\n  category: 加盐\n  version: 1.0\n  status: active\n  last_updated: 2025/11/7\n  owner: 王志\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 250\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 225\n  function_description: 加盐\n  operation_target: 250ml锥形瓶\n  operation_workflow: \"盐罐放入浮动载台 - 齿盘啮合 - 250ml锥形瓶载台移至上下料位 - 称重传感器清零 - 250ml锥形瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 250ml锥形瓶载台移至上下料位 - 取下250ml锥形瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换250ml锥形瓶，重复测试\"\n  absolute_accuracy_pct: \"(1)0.1-1g  ±10% / (2)1-10g  ±3%\"\n  repeat_accuracy_pct: \"(1)0.1-1g  ±10% / (2)1-10g  ±3%\"\n  cycle_time_sec: \"(1)1g  30S / (2)5g  90S / (3)10g  120\"\n  consumables: 锥形瓶-250ml\n  sub_functions: [225 加盐]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [加盐]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.084\n  power_kva_peak: 0.14\n  voltage_v: 48\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 250ml锥形瓶连续加盐模块\n\n## Purpose (用途说明)\n本模块实现往250ml锥形瓶中加入指定重量的固体试剂，锥形瓶不需要拆装盖，装载入模组后加入固体执行称重操作，并且可以更换盐罐。\n\n## Typical Scenarios (典型应用场景)\n无\n\n## Working Principle (工作原理)\n模块由储料仓、定量送料机构、下料导向机构、瓶体定位工装组成，依靠电机驱动定量分度 / 螺旋送料结构，精准控制单次出料盐料重量；250ml 锥形瓶完成精准定位对位后，机构按程序连续定量投放固体盐类试剂，通过匀速送料、稳流下料方式将盐料平稳送入瓶内，可实现多瓶依次连续自动加盐，全程统一投料量，保障实验配比一致性。\n\n## Limits & Cautions (限制与注意事项)\n无\n\n## Remarks (备注)\n', 'MOD-YJ-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YJ-002', '50ml离心管加盐涡旋模块（无触摸屏版）', 'HHM03B-050-V3.0', '加盐', '3.0', 'active', '蔡勤超', '2026/2/27', '加液，加盐，涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加液，加盐，涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 21.4, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1000, \"volume_ml_max\": 50, \"volume_ml_min\": 0, \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"涡旋底部胶皮，涡旋限位胶皮，拆盖爪指\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"正压加液系统\"]}, \"process_capability_1\": {\"consumables\": \"尖底离心管-50ml / 盐管\", \"function_code\": 223, \"sub_functions\": [\"220-拆盖，221-装盖，222-拆盖加液装盖涡旋，223-拆盖加盐装盖涡旋，224-加液，225-加盐，227-装盖涡旋\"], \"cycle_time_sec\": 97, \"operation_target\": \"50ml离心管,8g盐管\", \"operation_workflow\": \"离心管放入载台 - 载台移至拆合盖位 - 夹紧离心管 - 拆盖（保持夹住瓶盖）- 松开离心管 - 载台移至加盐位/加液位 - 加盐/加液 - 载台移至涡旋位 - 涡旋压板下压 - 涡旋 - 停止 - 涡旋压板升起 - 载台移至拆盖位 - 夹紧离心管 - 合盖 - 松开离心管 - 载台移至上下料位 - 取下离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"拆盖加盐装盖涡旋\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.22, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.132, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YJ-002\", \"name\": \"50ml离心管加盐涡旋模块（无触摸屏版）\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 3.0, \"category\": \"加盐\", \"last_updated\": \"2026/2/27\", \"module_part_no\": \"HHM03B-050-V3.0\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YJ-002\n  module_part_no: HHM03B-050-V3.0\n  name: 50ml离心管加盐涡旋模块（无触摸屏版）\n  category: 加盐\n  version: 3.0\n  status: active\n  last_updated: 2026/2/27\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 21.4\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1000\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 223\n  function_description: 拆盖加盐装盖涡旋\n  operation_target: 50ml离心管,8g盐管\n  operation_workflow: 离心管放入载台 - 载台移至拆合盖位 - 夹紧离心管 - 拆盖（保持夹住瓶盖）- 松开离心管 - 载台移至加盐位/加液位 - 加盐/加液 - 载台移至涡旋位 - 涡旋压板下压 - 涡旋 - 停止 - 涡旋压板升起 - 载台移至拆盖位 - 夹紧离心管 - 合盖 - 松开离心管 - 载台移至上下料位 - 取下离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 97\n  consumables: \"尖底离心管-50ml / 盐管\"\n  sub_functions: [220-拆盖，221-装盖，222-拆盖加液装盖涡旋，223-拆盖加盐装盖涡旋，224-加液，225-加盐，227-装盖涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - 正压加液系统\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 涡旋底部胶皮，涡旋限位胶皮，拆盖爪指\ntags_meta:\n  tags: [加液，加盐，涡旋]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.132\n  power_kva_peak: 0.22\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml离心管加盐涡旋模块（无触摸屏版）\n\n## Purpose (用途说明)\n实现向50ml尖底试管定量添加固体粉末/液体，并通过涡旋的方式使样品液充分混合/溶解\n\n## Typical Scenarios (典型应用场景)\n1、核酸检测样本前处理（裂解盐添加\n2、生化 / 免疫检测试剂配制\n3、环境水样重金属检测前处理\n4、食品样品添加剂 / 盐分检测前处理\n5、生物制药缓冲液 / 培养基配制\n\n## Working Principle (工作原理)\n加盐涡旋模块依靠三轴联动定位 + 旋转夹紧 + 粉末重力下料 + 高速涡旋混匀 + 传感器闭环检测，实现 50ml 尖底离心管的自动开盖→加固体粉末→关盖→涡旋混匀全流程自动化，核心是机械精确定位、重力定量下料、机械摩擦夹紧、高速振动混匀、异常闭环检测\n\n## Limits & Cautions (限制与注意事项)\n1、容器限制：仅适配 50ml 尖底离心管 与专用粉末盐管，不支持其他规格试管、圆底管、异形管。\n2、粉末特性限制：仅适用于流动性好、干燥、无吸湿性、无结块的细粉末；潮湿、易吸潮、易结块、带静电、颗粒过大 / 过细粉末不可用，易堵塞、下料不均或残留。\n3、液体限制：试管内液体为水相、缓冲液、澄清样品液；高粘度、易起泡、强腐蚀、高固含液体不适用，影响混匀效果或损坏部件。\n4、加盐方式限制：采用重力落料，无精准计量，靠盐管容积定量；无法用于微量、高精度称量场景。\n5、涡旋限制：最大 3000rpm、100s，不可长时间超高速运行；超重 / 满管易振动移位、漏液。\n\n## Remarks (备注)\n', 'MOD-YJ-002.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YJ-003', '2ml离心管连续加盐模块', 'HHM11A-002', '加盐', '2.0', 'active', '高新章', '2025/1/13', '加盐', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加盐\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 2, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-2ml\", \"function_code\": 225, \"sub_functions\": [\"225 加盐\"], \"cycle_time_sec\": 100, \"operation_target\": \"2ml离心管\", \"operation_workflow\": \"盐罐放入浮动载台 - 齿盘啮合 - 2ml锥形瓶载台移至上下料位 - 称重传感器清零 - 2ml锥形瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 2ml锥形瓶载台移至上下料位 - 取下2ml锥形瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换2ml锥形瓶，重复测试\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"加盐\", \"absolute_accuracy_pct\": \"±5%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.38, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.228, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YJ-003\", \"name\": \"2ml离心管连续加盐模块\", \"owner\": \"高新章\", \"status\": \"active\", \"version\": 2.0, \"category\": \"加盐\", \"last_updated\": \"2025/1/13\", \"module_part_no\": \"HHM11A-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YJ-003\n  module_part_no: HHM11A-002\n  name: 2ml离心管连续加盐模块\n  category: 加盐\n  version: 2.0\n  status: active\n  last_updated: 2025/1/13\n  owner: 高新章\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 2\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 225\n  function_description: 加盐\n  operation_target: 2ml离心管\n  operation_workflow: \"盐罐放入浮动载台 - 齿盘啮合 - 2ml锥形瓶载台移至上下料位 - 称重传感器清零 - 2ml锥形瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 2ml锥形瓶载台移至上下料位 - 取下2ml锥形瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换2ml锥形瓶，重复测试\"\n  absolute_accuracy_pct: ±5%\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 100\n  consumables: 离心管-2ml\n  sub_functions: [225 加盐]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [加盐]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.228\n  power_kva_peak: 0.38\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 2ml离心管连续加盐模块\n\n## Purpose (用途说明)\n本模块实现往2ml离心管中加入指定重量的固体试剂，离心管不需要拆装盖，装载入模组后加入固体执行称重操作，并且可以更换盐罐。\n\n## Typical Scenarios (典型应用场景)\n1、核酸检测前处理（PCR 样本制备）\n2、生化 / 免疫检测试剂配制与样本混匀\n3、生物制药细胞上清 / 发酵液处理\n4、微生物 / 环境检测样品前处理\n\n## Working Principle (工作原理)\n模块由储料仓、定量送料机构、下料导向机构、瓶体定位工装组成，依靠电机驱动定量分度 / 螺旋送料结构，精准控制单次出料盐料重量；250ml 锥形瓶完成精准定位对位后，机构按程序连续定量投放固体盐类试剂，通过匀速送料、稳流下料方式将盐料平稳送入瓶内，可实现多瓶依次连续自动加盐，全程统一投料量，保障实验配比一致性。\n\n## Limits & Cautions (限制与注意事项)\n\n\n## Remarks (备注)\n', 'MOD-YJ-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YJ-004', '50ml离心管加盐涡旋模块', 'HHM03J-050', '加盐', '2.0', 'active', '高新章', '2025/5/9', '加盐，涡旋', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加盐，涡旋\"]}, \"peripherals\": {\"required_peripherals\": \"无\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"无\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 1, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"无\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": 223, \"sub_functions\": [\"220 拆盖，225 加盐，221 装盖，227 涡旋\"], \"cycle_time_sec\": 300, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"盐管装入载台 - 盐管载台滑板处于待料位 - 盐管载台滑板移至开盐管盖位 - 盐管盖打开 - 加盐 - 盐管载台滑板移至盐管合盖位 - 盐管盖关闭 - 盐管载台滑板移至待料位 - 取下盐管 /  / 离心管放入载台 - 载台移至拆合盖位 - 夹紧离心管 - 拆盖（保持夹住瓶盖）- 松开离心管 - 载台移至加盐位/加液位 - 加盐/加液 - 载台移至涡旋位 - 涡旋压板下压 - 涡旋 - 停止 - 涡旋压板升起 - 载台移至拆盖位 - 夹紧离心管 - 合盖 - 松开离心管 - 载台移至上下料位 - 取下离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"从自定的粉末容器向50ml尖底试管定量添加固体粉末，并通过涡旋的方式使加入的粉末与试管中原有的样品液充分混合/溶解\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 48, \"power_kva_peak\": 0.22, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.132, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YJ-004\", \"name\": \"50ml离心管加盐涡旋模块\", \"owner\": \"高新章\", \"status\": \"active\", \"version\": 2.0, \"category\": \"加盐\", \"last_updated\": \"2025/5/9\", \"module_part_no\": \"HHM03J-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YJ-004\n  module_part_no: HHM03J-050\n  name: 50ml离心管加盐涡旋模块\n  category: 加盐\n  version: 2.0\n  status: active\n  last_updated: 2025/5/9\n  owner: 高新章\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 3000\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 无\nprocess_capability_1:\n  function_code: 223\n  function_description: 从自定的粉末容器向50ml尖底试管定量添加固体粉末，并通过涡旋的方式使加入的粉末与试管中原有的样品液充分混合/溶解\n  operation_target: 50ml离心管\n  operation_workflow: \"盐管装入载台 - 盐管载台滑板处于待料位 - 盐管载台滑板移至开盐管盖位 - 盐管盖打开 - 加盐 - 盐管载台滑板移至盐管合盖位 - 盐管盖关闭 - 盐管载台滑板移至待料位 - 取下盐管 /  / 离心管放入载台 - 载台移至拆合盖位 - 夹紧离心管 - 拆盖（保持夹住瓶盖）- 松开离心管 - 载台移至加盐位/加液位 - 加盐/加液 - 载台移至涡旋位 - 涡旋压板下压 - 涡旋 - 停止 - 涡旋压板升起 - 载台移至拆盖位 - 夹紧离心管 - 合盖 - 松开离心管 - 载台移至上下料位 - 取下离心管\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 300\n  consumables: 离心管-50ml\n  sub_functions: [220 拆盖，225 加盐，221 装盖，227 涡旋]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 无\ntags_meta:\n  tags: [加盐，涡旋]\ndocumentation:\n  urs_url: 无\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.132\n  power_kva_peak: 0.22\n  voltage_v: 48\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml离心管加盐涡旋模块\n\n## Purpose (用途说明)\n从自定的粉末容器向50ml尖底试管定量添加固体粉末，并通过涡旋的方式使加入的粉末与试管中原有的样品液充分混合/溶解\n\n## Typical Scenarios (典型应用场景)\n样品前处理自动化加盐混匀\n适用于食品、环境、药品检测前处理，对50ml 尖底试管内样品液自动定量加盐→自动拆盖 / 加盖→高速涡旋溶解，全程无人操作，满足国标样品前处理中 “加盐 — 混匀 — 溶解” 的标准流程\n\n## Working Principle (工作原理)\n设备驱动定量送料机构完成固体盐类定量投放，将试剂加入 50ml 离心管内；随后电机带动承载工位做偏心圆周运动，转化为高频涡旋振荡，管内液体产生涡流翻滚冲击，使加入的盐料快速分散溶解，实现自动加盐与混匀一体化作业。\n\n## Limits & Cautions (限制与注意事项)\n1、仅适配50ml 尖底试管，必须放正、夹紧、无破损，禁止歪放、空管运行。\n2、拆盖 / 加盖必须传感器确认成功，未盖紧禁止涡旋，防止喷溅。\n3、加盐时盐管与试管对位准确，禁止漏盐、洒粉\n4、涡旋转速≤3000rpm，运行中禁止触碰试管与按压机构。\n5、运行时保持气缸压力正常、夹爪无松动，异常立即急停。\n6、维护需断电断气，清理残留盐粉，防止卡轴、腐蚀。\n\n## Remarks (备注)\n', 'MOD-YJ-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YJ-005', '125mlPP瓶连续加盐模块', 'HHM11C-125', '加盐', '1.0', 'active', '高新章', '2025/5/23', '连续加盐', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"连续加盐\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 125, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"PP瓶-125ml / 盐罐-150g / \", \"function_code\": 130, \"sub_functions\": [\"131-滑台气缸缩回，123-滑台气缸伸出，124-盐罐气缸缩回\"], \"cycle_time_sec\": 100, \"operation_target\": \"125mlPP瓶\", \"operation_workflow\": \"盐罐放入浮动载台 - 齿盘啮合 - 125mlPP瓶载台移至上下料位 - 称重传感器清零 - 125mlPP瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 125mlPP瓶载台移至上下料位 - 取下125mlPP瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换125mlPP瓶，重复测试\", \"repeat_accuracy_pct\": \"±0.05g\", \"function_description\": \"加盐\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.15, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.09, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YJ-005\", \"name\": \"125mlPP瓶连续加盐模块\", \"owner\": \"高新章\", \"status\": \"active\", \"version\": 1.0, \"category\": \"加盐\", \"last_updated\": \"2025/5/23\", \"module_part_no\": \"HHM11C-125\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YJ-005\n  module_part_no: HHM11C-125\n  name: 125mlPP瓶连续加盐模块\n  category: 加盐\n  version: 1.0\n  status: active\n  last_updated: 2025/5/23\n  owner: 高新章\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 125\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 130\n  function_description: 加盐\n  operation_target: 125mlPP瓶\n  operation_workflow: \"盐罐放入浮动载台 - 齿盘啮合 - 125mlPP瓶载台移至上下料位 - 称重传感器清零 - 125mlPP瓶放入载台 - 载台移至加盐位 - 齿盘转动 - 快速加盐 - 加盐量至95% - 慢速加盐 - 加盐量100% - 停止 - 加盐重量数值稳定 - 补充加盐 - 125mlPP瓶载台移至上下料位 - 取下125mlPP瓶； / 加盐过程中，无盐落下10s，振动盐罐浮动部件； / 更换125mlPP瓶，重复测试\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: ±0.05g\n  cycle_time_sec: 100\n  consumables: \"PP瓶-125ml / 盐罐-150g / \"\n  sub_functions: [131-滑台气缸缩回，123-滑台气缸伸出，124-盐罐气缸缩回]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [连续加盐]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.09\n  power_kva_peak: 0.15\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 125mlPP瓶连续加盐模块\n\n## Purpose (用途说明)\n向125mlPP瓶内添加指定重量的盐粉，并通过称重天平确定重量\n\n## Typical Scenarios (典型应用场景)\n1、水质检测 **125ml PP 瓶定量加盐（NaCl）** 前处理\n2、环境水样氯离子调节、固定、消解前加盐工艺场景\n3、COD、总氮、总磷等检测3g NaCl 精准定量添加\n4、实验室粉末试剂高精度定量加料自动化场景\n\n## Working Principle (工作原理)\n通过 Y 轴移位、螺杆送料与振动辅助下料，配合称重天平实时闭环控制，双路独立精准向 PP 瓶添加 3g NaCl，精度达 ±0.05g、单次加盐≤10s\n\n## Limits & Cautions (限制与注意事项)\n1、仅限125ml 标准 PP 瓶使用，禁止其他规格容器。\n2、仅适用于NaCl 盐粉，不可用于其他粉末、颗粒、腐蚀性物料。\n3、单次加盐量3g，精度要求 **±0.05g**，不可超量程加料。\n\n## Remarks (备注)\n', 'MOD-YJ-005.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-001', '自动化精密移液模块10ml（定量环）', 'HHM09G-010', '移液', '1.0', 'active', '黄锐', '2025/6/13', '精密移液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"精密移液\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 10, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶，125ml PP广口瓶\", \"function_code\": 600, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 0, \"operation_target\": \"25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶，125ml PP广口瓶\", \"operation_workflow\": \"放入容量瓶/PP瓶 - 夹紧 - 上样针移至吸液位 - 针头伸入瓶内液面下 - 吸入样品液 - 清除死体积 - 上样针移至放液位 - 针头伸入瓶内（瓶颈） - 放液 - 上样针移至清洗位 - 针头内外同时冲洗 - 上样针移至吹干位 - 吹干 - 取下容量瓶/PP瓶；\", \"repeat_accuracy_pct\": \"(1)1ml  ±0.7% / (2)2ml ±0.5% / (3)5ml ±0.3% / (4)10ml ±0.2%\", \"function_description\": \"移液\", \"absolute_accuracy_pct\": \"(1)1ml  ±0.7% / (2)2ml ±0.5% / (3)5ml ±0.3% / (4)10ml ±0.2%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.54, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.36, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-001\", \"name\": \"自动化精密移液模块10ml（定量环）\", \"owner\": \"黄锐\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2025/6/13\", \"module_part_no\": \"HHM09G-010\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-001\n  module_part_no: HHM09G-010\n  name: 自动化精密移液模块10ml（定量环）\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2025/6/13\n  owner: 黄锐\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 600\n  function_description: 移液\n  operation_target: 25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶，125ml PP广口瓶\n  operation_workflow: 放入容量瓶/PP瓶 - 夹紧 - 上样针移至吸液位 - 针头伸入瓶内液面下 - 吸入样品液 - 清除死体积 - 上样针移至放液位 - 针头伸入瓶内（瓶颈） - 放液 - 上样针移至清洗位 - 针头内外同时冲洗 - 上样针移至吹干位 - 吹干 - 取下容量瓶/PP瓶；\n  absolute_accuracy_pct: \"(1)1ml  ±0.7% / (2)2ml ±0.5% / (3)5ml ±0.3% / (4)10ml ±0.2%\"\n  repeat_accuracy_pct: \"(1)1ml  ±0.7% / (2)2ml ±0.5% / (3)5ml ±0.3% / (4)10ml ±0.2%\"\n  cycle_time_sec: 0\n  consumables: 25ml容量瓶，50ml容量瓶，100ml容量瓶，200ml容量瓶，125ml PP广口瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [精密移液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.36\n  power_kva_peak: 0.54\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 自动化精密移液模块10ml（定量环）\n\n## Purpose (用途说明)\n对心定位 + 精密移液（0.5~10ml）+ 自动清洗干燥，三位一体实现多瓶型、多规格的全自动精密移液，替代人工操作，避免交叉污染\n\n## Typical Scenarios (典型应用场景)\n精密移液（0.5~10ml）+ 多瓶型适配（25~200ml容量瓶/125ml PP瓶）+ 自动清洗干燥，三位一体，专为药物配制、环境检测、临床检验、批量QC等需要高精度小体积移液的自动化场景设计\n\n## Working Principle (工作原理)\nZ轴精确定位 + 注射泵定量吸排 + 多阀控制流路 + 正压清洗 + CDA内外吹干，五位一体实现0.5~10ml五档精密移液，每次操作后自动清洗干燥，完全替代人工移液，杜绝交叉污染\n\n## Limits & Cautions (限制与注意事项)\n瓶型只认5种、移液只认5档、每次必清洗必干燥、摆臂只认4个角度、上料必过光电检测——其余参数（清洗次数、吹干时长、取液高度）均可按需设定，但上述限制不可突破，否则精度失控或设备损坏\n\n## Remarks (备注)\n', 'MOD-YY-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-002', '1ml移液模块', 'HHM09N-001', '移液', '1.0', 'active', '徐翔宇', '2026/1/23', '移液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"移液\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 400, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 1, \"volume_ml_min\": 0.5, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"密封圈\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"西林瓶-4ml / 离心管-2ml / 枪头-1ml\", \"function_code\": 100, \"sub_functions\": [\"100 移液\"], \"cycle_time_sec\": 270, \"operation_target\": \"4ml西林瓶，2ml离心管，1ml枪头\", \"operation_workflow\": \"载台移至上下料位 - 机械臂依次放入枪头/西林瓶/离心管 - 移至上枪头位 - 下降取枪头 - 上升至安全位 - 载台移动至吸液位 - 枪头下降吸液 - 定量泵吸液 - 枪头上升至安全位 - 载台移动至移液位 - 枪头下降全部吐液 - 上升至安全位 - 载台移动至上枪头位 - 退枪头 - 载台移动至上下料位 - 机械臂依次取出枪头/西林瓶/离心管 - 放入托盘；停顿1分钟，重复工作流程\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"移液\", \"absolute_accuracy_pct\": \"±1%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.16, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.096, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-002\", \"name\": \"1ml移液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2026/1/23\", \"module_part_no\": \"HHM09N-001\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-002\n  module_part_no: HHM09N-001\n  name: 1ml移液模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2026/1/23\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 400\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.5\n  volume_ml_max: 1\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 100\n  function_description: 移液\n  operation_target: 4ml西林瓶，2ml离心管，1ml枪头\n  operation_workflow: 载台移至上下料位 - 机械臂依次放入枪头/西林瓶/离心管 - 移至上枪头位 - 下降取枪头 - 上升至安全位 - 载台移动至吸液位 - 枪头下降吸液 - 定量泵吸液 - 枪头上升至安全位 - 载台移动至移液位 - 枪头下降全部吐液 - 上升至安全位 - 载台移动至上枪头位 - 退枪头 - 载台移动至上下料位 - 机械臂依次取出枪头/西林瓶/离心管 - 放入托盘；停顿1分钟，重复工作流程\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 270\n  consumables: \"西林瓶-4ml / 离心管-2ml / 枪头-1ml\"\n  sub_functions: [100 移液]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 密封圈\ntags_meta:\n  tags: [移液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.096\n  power_kva_peak: 0.16\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 1ml移液模块\n\n## Purpose (用途说明)\n实现容器间液体样品/试剂的转移，可双通道转移，可单通道转移。\n\n## Typical Scenarios (典型应用场景)\n成都食检院\n\n## Working Principle (工作原理)\n1ml 移液模块依托气压活塞式吸排液原理工作，通过模组内置精密驱动机构带动活塞上下往复运动，利用密闭腔体形成正负气压差；下移活塞排出内部空气产生负压，精准吸取 1ml 定量液体，上推活塞形成正压，平稳完成液体定量排液释放，配合机械定位与行程限位结构，精准控制吸液、排液行程距离，从而稳定实现1ml 固定量程精准移取、加注液体，可搭配自动化设备完成批量、标准化连续移液作业。\n\n## Limits & Cautions (限制与注意事项)\n不同的移液量，移液参数不是线性关系，需要做测试进行调整\n\n## Remarks (备注)\n', 'MOD-YY-002.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
