ssed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-003\", \"name\": \"10ml移液模块\", \"owner\": \"徐翔宇\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2026/1/23\", \"module_part_no\": \"HHM09N-002\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-003\n  module_part_no: HHM09N-002\n  name: 10ml移液模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2026/1/23\n  owner: 徐翔宇\nphysical_specs:\n  length_mm: 400\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 10\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 100\n  function_description: 移液\n  operation_target: 10ml枪头，50ml离心管，35ml西林瓶\n  operation_workflow: 载台移至上下料位 - 机械臂依次放入枪头/西林瓶/离心管 - 移至上枪头位 - 下降取枪头 - 上升至安全位 - 载台移动至吸液位 - 枪头下降吸液 - 定量泵吸液 - 枪头上升至安全位 - 载台移动至移液位 - 枪头下降全部吐液 - 上升至安全位 - 载台移动至上枪头位 - 退枪头 - 载台移动至上下料位 - 机械臂依次取出枪头/西林瓶/离心管 - 放入托盘；停顿1分钟，重复工作流程\n  absolute_accuracy_pct: ±1%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 275\n  consumables: \"西林瓶-2ml / 西林瓶-10ml / 西林瓶-35ml / 西林瓶-50ml / 离心管-15ml / 离心管-50ml / 枪头-10ml\"\n  sub_functions: [100 移液]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 密封圈\ntags_meta:\n  tags: [移液]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.096\n  power_kva_peak: 0.16\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 10ml移液模块\n\n## Purpose (用途说明)\n实现容器间液体样品/试剂的转移，可双通道转移，可单通道转移。\n\n## Typical Scenarios (典型应用场景)\n成都食检院\n\n## Working Principle (工作原理)\n该模块采用活塞气压式定量移液原理，由驱动机构带动内部活塞做精准往复直线运动，在密闭液腔内部形成负压与正压。活塞上行形成负压，依靠气压差将液体精准吸入管路及腔体，完成 10ml 定量吸液；活塞下行挤压腔体内空间形成正压，匀速将内部液体平稳推出，实现定量排液。通过机械限位精准锁定活塞运动行程，固定单次吸排液容积为 10ml，配合管路接头与吸液嘴定位结构，完成标准化、自动化批量定量吸取与加注液体动作。\n\n## Limits & Cautions (限制与注意事项)\n不同的移液量，移液参数不是线性关系，需要做测试进行调整\n\n## Remarks (备注)\n', 'MOD-YY-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-004', '50ml全量液体转移模块', 'HHM09F-050', '移液', '1.0', 'active', '宾俊', '2026/1/30', '拆盖，全量转移', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"拆盖，全量转移\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 50, \"volume_ml_min\": 0, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"离心管-50ml\", \"function_code\": \"155 / \", \"sub_functions\": [\"160 拆盖\", \"倒液\", \"装盖\"], \"cycle_time_sec\": \"40S\", \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"载台移至上下料位 - 放入样品离心管（有盖）- 放入空离心管（无盖）- 载台移至拆合盖位 - 气缸推出夹紧离心管 - 钧舵夹爪下降至拆合盖位置 - 夹紧瓶盖 - 均舵夹爪旋转并向上运动打开瓶盖 - 钧舵夹爪上移至拆盖等待位（夹爪保持夹住瓶盖）- 载台移至旋转倒液位 - 旋转倒液（旋转速度）- 接液离心管随倒液离心管动作下降（下降速度）- 倒液离心管旋转到95°停顿1s - 倒液离心管回正（旋转速度） - 接液离心管回升 - 载台移至拆合盖位 - 均舵夹爪下降至离心管拆合盖位置 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 均舵夹爪松开瓶盖并上升至等待位 - 载台移至上下料位 - 取下离心管\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \" 50ml离心管 液体转移：\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.52, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.312, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-004\", \"name\": \"50ml全量液体转移模块\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2026/1/30\", \"module_part_no\": \"HHM09F-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-004\n  module_part_no: HHM09F-050\n  name: 50ml全量液体转移模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2026/1/30\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: \"155 / \"\n  function_description: \" 50ml离心管 液体转移：\"\n  operation_target: 50ml离心管\n  operation_workflow: 载台移至上下料位 - 放入样品离心管（有盖）- 放入空离心管（无盖）- 载台移至拆合盖位 - 气缸推出夹紧离心管 - 钧舵夹爪下降至拆合盖位置 - 夹紧瓶盖 - 均舵夹爪旋转并向上运动打开瓶盖 - 钧舵夹爪上移至拆盖等待位（夹爪保持夹住瓶盖）- 载台移至旋转倒液位 - 旋转倒液（旋转速度）- 接液离心管随倒液离心管动作下降（下降速度）- 倒液离心管旋转到95°停顿1s - 倒液离心管回正（旋转速度） - 接液离心管回升 - 载台移至拆合盖位 - 均舵夹爪下降至离心管拆合盖位置 - 钧舵夹爪旋转并向下运动盖上瓶盖 - 均舵夹爪松开瓶盖并上升至等待位 - 载台移至上下料位 - 取下离心管\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 40S\n  consumables: 离心管-50ml\n  sub_functions: [160 拆盖, 倒液, 装盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指胶皮\ntags_meta:\n  tags: [拆盖，全量转移]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.312\n  power_kva_peak: 0.52\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml全量液体转移模块\n\n## Purpose (用途说明)\n全量液体转移模块是适配50ml 尖底离心管的自动化液体处理单元，核心用于离心后样本的全量液体精准转移，集成上下料、开合盖、旋转倒液、接液等一体化功能，实现样本处理全流程自动化，避免人工操作误差与污染，适配实验室自动化样本处理场景\n\n## Typical Scenarios (典型应用场景)\n1、临床生化 / 免疫检测样本前处理\n2、核酸检测样本处理（PCR 前处理\n3、生物制药 / 细胞培养上清液转移\n4、食品 / 环境检测样品前处理\n\n## Working Principle (工作原理)\n该模块通过三轴联动 + 旋转倒液 + 气动夹紧 + 电动夹爪组合，实现 50ml 尖底离心管从上下料、自动开 / 关盖、旋转倒液、精准接液到下料的全自动流程，核心是机械定位 + 精准旋转 + 动态随动接液 + 闭环检测\n\n## Limits & Cautions (限制与注意事项)\n1、严禁手动干预运行中设备：运行时开盖、伸手、拨管易造成夹伤、撞机、样品污染。\n2、定期校准：各轴零点、夹爪行程、旋转角度、传感器位置需定期校准，防止定位不准、拆盖失败、漏液。\n3、清洁要求：接触样品区域每次运行后清洁，避免交叉污染、残留结晶影响夹紧与旋转。\n4、异常处理：拆盖失败、掉管、漏液、电机报错时，先断电 ，停气再处理，禁止带电排查。\n5、负载限制：夹爪、气缸、电机不可超额定负载，长期重载会导致打滑、变形、寿命缩短。\n\n## Remarks (备注)\n', 'MOD-YY-004.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-005', '15ml离心管液体全量转移模块V1.0', 'HHM09H-015', '移液', '1.0', 'active', '宾俊', '2025/7/25', '全量转移，15ml离心管', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"全量转移，15ml离心管\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 15, \"volume_ml_min\": 0, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指胶皮\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"离心管-15ml / 离心管-50ml\", \"function_code\": 160, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": \"\", \"operation_target\": \"15ml带盖离心管，50ml不带盖离心管\", \"operation_workflow\": \"上料：两个不带盖的空50ml离心管，两个带盖带料的15ml离心管；拆盖：带盖带料15ml离心管拆盖；倒液：抓起两个带料离心管，移到空离心管上方，带料离心管倾斜，将上层清液倒入空离心管后立起；装盖：带料离心管装盖；下料：2个带盖带料的15ml离心管，两个带料不带盖的50ml离心管。\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"全量转移\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.52, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.31, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-005\", \"name\": \"15ml离心管液体全量转移模块V1.0\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2025/7/25\", \"module_part_no\": \"HHM09H-015\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-005\n  module_part_no: HHM09H-015\n  name: 15ml离心管液体全量转移模块V1.0\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2025/7/25\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0\n  volume_ml_max: 15\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 160\n  function_description: 全量转移\n  operation_target: 15ml带盖离心管，50ml不带盖离心管\n  operation_workflow: 上料：两个不带盖的空50ml离心管，两个带盖带料的15ml离心管；拆盖：带盖带料15ml离心管拆盖；倒液：抓起两个带料离心管，移到空离心管上方，带料离心管倾斜，将上层清液倒入空离心管后立起；装盖：带料离心管装盖；下料：2个带盖带料的15ml离心管，两个带料不带盖的50ml离心管。\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: \"\"\n  consumables: \"离心管-15ml / 离心管-50ml\"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指胶皮\ntags_meta:\n  tags: [全量转移，15ml离心管]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.31\n  power_kva_peak: 0.52\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 15ml离心管液体全量转移模块V1.0\n\n## Purpose (用途说明)\n15ml全量转移模块是实现上层清液从一个容器全部倒入另一个容器的操作。\n\n## Typical Scenarios (典型应用场景)\n1、分子生物学：核酸提取前处理\n2、生化与蛋白：离心后上清转移\n3、微生物：样本富集与除菌\n4、药物研发：发酵液 / 中间体处理\n\n## Working Principle (工作原理)\n以正向置换式注射泵为核心，配合高精度 XYZ 运动 + 多传感器闭环，通过 “精准吸液→无残留排液 + 强吹” 流程，实现15 mL 液体 100% 转移、残留 < 5 μL、精度 ±0.5%，广泛用于生化、免疫、样品前处理等场景。\n\n## Limits & Cautions (限制与注意事项)\n本模块仅适配 15ml 带盖管上清全量转入 50ml 无盖管，固定 2 管并行；仅适用于分层、流动性好的上清，禁高粘、腐蚀、易燃液。单批约 50 秒、无计量精度、微量残留；尺寸固定，需 DC24V 供电与 6mm 气源，通信仅支持 MODBUS TCP，流程自定义受限\n\n## Remarks (备注)\n', 'MOD-YY-005.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-006', '250ml锥形瓶全量转移模块', 'HHM09L-250', '移液', '1.0', 'active', '蔡勤超', '2025/8/29', '全量转移', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"全量转移\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 15, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": [\"250ml锥形瓶恒温振荡模块\"]}, \"process_capability_1\": {\"consumables\": \"250ml锥形瓶 / 250ml萃取瓶/100ml容量瓶\", \"function_code\": 580, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 507, \"operation_target\": \"250ml锥形瓶，接收容器：250ml萃取瓶/100ml容量瓶\", \"operation_workflow\": \"上料：一个不带盖的空250ml萃取瓶或不带盖的100ml容量瓶，一个带盖带料的250ml锥形瓶； / 全量转移：通过管路将锥形瓶中的样品抽到接收容器中。注意：底部带磁吸，可将磁力搅拌子吸在锥形瓶底部的中间位置，同时倾斜锥形瓶，用管路将样品吸干净（就是磁力搅拌子不能影响管理针头吸样品）； / 清洗：向锥形瓶中喷加一定量的液体清洗瓶壁，（如30ml水或20ml乙醇-水溶液）加液通道2，加液量：20-100ml可设置，精度±2% / 下料：2个带盖带料的15ml离心管，两个带料不带盖的50ml离心管。 / 下料：一个不带盖的250ml萃取瓶或不带盖的100ml容量瓶，一个带盖的250ml锥形瓶；\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"250ml锥形瓶液体全量转移模块是实现将皂化后的样品从一个容器全部抽入另一个容器，并加一定量的溶剂清洗原容器后再次抽入接收容器的操作。\", \"absolute_accuracy_pct\": \"250ml\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.167, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.1, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-006\", \"name\": \"250ml锥形瓶全量转移模块\", \"owner\": \"蔡勤超\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2025/8/29\", \"module_part_no\": \"HHM09L-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-006\n  module_part_no: HHM09L-250\n  name: 250ml锥形瓶全量转移模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2025/8/29\n  owner: 蔡勤超\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 15\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 580\n  function_description: 250ml锥形瓶液体全量转移模块是实现将皂化后的样品从一个容器全部抽入另一个容器，并加一定量的溶剂清洗原容器后再次抽入接收容器的操作。\n  operation_target: 250ml锥形瓶，接收容器：250ml萃取瓶/100ml容量瓶\n  operation_workflow: \"上料：一个不带盖的空250ml萃取瓶或不带盖的100ml容量瓶，一个带盖带料的250ml锥形瓶； / 全量转移：通过管路将锥形瓶中的样品抽到接收容器中。注意：底部带磁吸，可将磁力搅拌子吸在锥形瓶底部的中间位置，同时倾斜锥形瓶，用管路将样品吸干净（就是磁力搅拌子不能影响管理针头吸样品）； / 清洗：向锥形瓶中喷加一定量的液体清洗瓶壁，（如30ml水或20ml乙醇-水溶液）加液通道2，加液量：20-100ml可设置，精度±2% / 下料：2个带盖带料的15ml离心管，两个带料不带盖的50ml离心管。 / 下料：一个不带盖的250ml萃取瓶或不带盖的100ml容量瓶，一个带盖的250ml锥形瓶；\"\n  absolute_accuracy_pct: 250ml\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 507\n  consumables: \"250ml锥形瓶 / 250ml萃取瓶/100ml容量瓶\"\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    - 250ml锥形瓶恒温振荡模块\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [全量转移]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.1\n  power_kva_peak: 0.167\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: true\n  requires_drain: true', '# 250ml锥形瓶全量转移模块\n\n## Purpose (用途说明)\n用于实验室样品前处理，自动将 250ml 锥形瓶内液体全量转移至 250ml 萃取瓶，集成瓶体定位、注射泵抽排液、锥形瓶与管路自动清洗功能。适配食品、环境、医药等检测场景，实现全量移液自动化，减少人工操作误差，降低污染风险，提升样品处理效率与标准化水平\n\n## Typical Scenarios (典型应用场景)\n用于实验室前处理，适配 250ml 锥形瓶→萃取瓶全量转移。典型案例：食品农残 / 真菌毒素提取液转移、环境水样萃取分相、医药中间体 / 发酵液转瓶、固相萃取后洗脱液归集、化工样品净化液转移。自动化全量移液、自带清洗，防污染、降误差、提通量\n\n## Working Principle (工作原理)\n由 Y/Z 轴电机、注射泵、电磁阀、定位载台及清洗组件构成。载台定位瓶位，Z 轴带动取液针下移，注射泵抽液，电磁阀切换管路排至萃取瓶；重复抽排实现全量转移。转移后自动喷淋清洗瓶体与管路，排废回收，完成自动化移液与清洗流程\n\n## Limits & Cautions (限制与注意事项)\n仅适配标准 250ml 锥形瓶与萃取瓶，固定规格不兼容非标容器。仅适用于低粘度、无固体颗粒、不易结晶液体；禁强腐蚀、高粘度、易堵样品。依赖 DC24V 供电与稳定气源，全量转移存在微量残留；管路易堵，需定期清洗维护，安装需水平稳固防漏液。\n\n## Remarks (备注)\n', 'MOD-YY-006.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-008', '250ml锥形瓶加内标模块', 'HHM12A-250', '移液', '1.0', 'active', '宾俊', '2025/9/12', '加内标', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"加内标\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 0.4, \"volume_ml_min\": 0.1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"加液电磁阀\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"锥形瓶-250ml\", \"function_code\": 250, \"sub_functions\": [\"251-清洗标针\"], \"cycle_time_sec\": 97, \"operation_target\": \"250ml锥形瓶\", \"operation_workflow\": \"定位治具移至上下料位 - 放入锥形瓶/内标瓶 - 定位治具移至加内标品位 - 加标针对准内标瓶 - 加标针降至吸内标位 - 吸取内标准品 - 加标针上升 - 加标针对准锥形瓶 - 加标针降至加内标位 - 加内标准品 - 加标针上升 - 加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加纯水清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 加标针上升 - 定位治具移至上下料位 - 取下锥形瓶/内标瓶\", \"repeat_accuracy_pct\": \"±0.5%\", \"function_description\": \"加内标\", \"absolute_accuracy_pct\": \"±2%\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.45, \"requires_drain\": true, \"requires_water\": true, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.27, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-YY-008\", \"name\": \"250ml锥形瓶加内标模块\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2025/9/12\", \"module_part_no\": \"HHM12A-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-008\n  module_part_no: HHM12A-250\n  name: 250ml锥形瓶加内标模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2025/9/12\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 0.1\n  volume_ml_max: 0.4\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 250\n  function_description: 加内标\n  operation_target: 250ml锥形瓶\n  operation_workflow: 定位治具移至上下料位 - 放入锥形瓶/内标瓶 - 定位治具移至加内标品位 - 加标针对准内标瓶 - 加标针降至吸内标位 - 吸取内标准品 - 加标针上升 - 加标针对准锥形瓶 - 加标针降至加内标位 - 加内标准品 - 加标针上升 - 加标针对准清洗槽 - 加标针下降至清洗位 - 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加纯水清洗加标针 - 排废液 - 注射泵排空（两次）- 清洗槽内加有机溶剂清洗加标针 - 排废液 - 注射泵排空（两次）- 加标针上升 - 定位治具移至上下料位 - 取下锥形瓶/内标瓶\n  absolute_accuracy_pct: ±2%\n  repeat_accuracy_pct: ±0.5%\n  cycle_time_sec: 97\n  consumables: 锥形瓶-250ml\n  sub_functions: [251-清洗标针]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 加液电磁阀\ntags_meta:\n  tags: [加内标]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.27\n  power_kva_peak: 0.45\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: true\n  requires_drain: true', '# 250ml锥形瓶加内标模块\n\n## Purpose (用途说明)\n广泛用于环境监测、食品检测、化工、医药、科研实验室，为水质、土壤、食品、化工原料等样品的色谱、质谱分析，提供精准内标添加，保障定量分析准确性\n\n## Typical Scenarios (典型应用场景)\n该模块是实验室样品前处理自动化设备，双通道适配 250ml 锥形瓶，精准添加 100μL/400μL 内标液，精度 ±2%。自动完成吸标、加标、有机 - 水 - 有机三步洗针，杜绝交叉污染。广泛用于环境、食品、化工、医药等领域，为色谱、质谱分析提供精准内标添加，高效稳定、数据可靠。\n\n## Working Principle (工作原理)\n由 PLC 控制 Y/Z 轴定位、加标泵与洗针组件，双通道自动作业。精准吸取 100μL/400μL 内标液并注入锥形瓶，完成后经有机 - 水 - 有机三步洗针、气吹防交叉污染，全流程自动化、精度高\n\n## Limits & Cautions (限制与注意事项)\n100ul/400ul，通过更换注射器实现\n\n## Remarks (备注)\n', 'MOD-YY-008.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-YY-009', '50-250ml容量瓶拆盖倒液模块', 'HHM09Q-901', '移液', '1.0', 'active', '唐宋', '2026/5/22', '容量瓶，PP瓶，拆盖，倒液', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"容量瓶，PP瓶，拆盖，倒液\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"单工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 250, \"volume_ml_min\": 50, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"手指\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml容量瓶，100ml容量瓶，200ml容量瓶，250ml容量瓶，50mlpp瓶\", \"function_code\": 160, \"sub_functions\": [\"161-PP拆盖，162-PP装盖，163-拆盖/倒液/不装PP盖\"], \"cycle_time_sec\": 230, \"operation_target\": \"50ml容量瓶，100ml容量瓶，200ml容量瓶，250ml容量瓶，50mlpp瓶\", \"operation_workflow\": \"机械臂放入PP瓶和容量瓶-模块执行先拆PP盖-将PP盖放在瓶盖过渡位-模块检测容量瓶瓶瓶盖盖度-夹紧气缸走到位置拆盖-将容量瓶抬起-Y轴走到PP瓶接液位-夹紧气缸Z轴走到倒液位-点推杆走到倒液角度-倒液完PP瓶和容量瓶装盖-机械臂先搬走容量瓶再搬走PP瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"拆盖/倒液/装盖\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.6, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.36, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-YY-009\", \"name\": \"50-250ml容量瓶拆盖倒液模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2026/5/22\", \"module_part_no\": \"HHM09Q-901\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-YY-009\n  module_part_no: HHM09Q-901\n  name: 50-250ml容量瓶拆盖倒液模块\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2026/5/22\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"单工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 50\n  volume_ml_max: 250\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 160\n  function_description: 拆盖/倒液/装盖\n  operation_target: 50ml容量瓶，100ml容量瓶，200ml容量瓶，250ml容量瓶，50mlpp瓶\n  operation_workflow: 机械臂放入PP瓶和容量瓶-模块执行先拆PP盖-将PP盖放在瓶盖过渡位-模块检测容量瓶瓶瓶盖盖度-夹紧气缸走到位置拆盖-将容量瓶抬起-Y轴走到PP瓶接液位-夹紧气缸Z轴走到倒液位-点推杆走到倒液角度-倒液完PP瓶和容量瓶装盖-机械臂先搬走容量瓶再搬走PP瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 230\n  consumables: 50ml容量瓶，100ml容量瓶，200ml容量瓶，250ml容量瓶，50mlpp瓶\n  sub_functions: [161-PP拆盖，162-PP装盖，163-拆盖/倒液/不装PP盖]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 手指\ntags_meta:\n  tags: [容量瓶，PP瓶，拆盖，倒液]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.36\n  power_kva_peak: 0.6\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50-250ml容量瓶拆盖倒液模块\n\n## Purpose (用途说明)\n50-250ml容量瓶倒液模块是实现从容量瓶将液体倒入50mlPP瓶的操作，同时具备50mlPP瓶拆盖功能\n\n## Typical Scenarios (典型应用场景)\n自动化定容平台\n\n## Working Principle (工作原理)\n设备接收上位机 Modbus TCP 指令，依靠机械夹持机构 + 旋转拧盖机构 + 伺服翻转机构，依次完成 PP 瓶拆盖→容量瓶夹持翻转定量倒液→PP 瓶旋盖，全流程自动化。\n\n## Limits & Cautions (限制与注意事项)\n1、瓶体规格受限：仅适配 50/100/200/250ml 普兰德、百泉容量瓶与指定型号 50ml 垒固 PP 瓶，非标瓶体无法使用。\n2、分装容量约束：倒液量只能在 1~15mL 区间调节，超出量程无法精准定量。\n3、液体依赖自重出料：高粘度、易挂壁粘稠液体易出现残液、滴漏，不适用。\n\n## Remarks (备注)\n', 'MOD-YY-009.md', '2026-06-11 18:33:13', '2026-06-12 11:33:37');
INSERT INTO `smartlabos-module` VALUES ('MOD-ZD-001', '50ml垂直震荡模块', 'HHM01A-050', '震荡', '2.0', 'active', '宾俊', '2026/1/30', '垂直震荡', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"垂直震荡\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"未找到\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 500, \"speed_rpm_min\": 1, \"volume_ml_max\": 50, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"工位硅胶条\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"50ml离心管\", \"function_code\": \"140 / \", \"sub_functions\": [\"140 震荡\"], \"cycle_time_sec\": 220, \"operation_target\": \"50ml离心管\", \"operation_workflow\": \"载台移动到最高点-电推杆向前推动离心管抱夹-抱夹打开-放入离心管-电推杆向后运动-抱夹夹紧-振荡-载台移动到最高点-电推杆向前推动离心管抱夹-抱夹打开-取下离心管；更换样品，重复测试\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"垂直震荡\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.2, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.2, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-ZD-001\", \"name\": \"50ml垂直震荡模块\", \"owner\": \"宾俊\", \"status\": \"active\", \"version\": 2.0, \"category\": \"震荡\", \"last_updated\": \"2026/1/30\", \"module_part_no\": \"HHM01A-050\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-ZD-001\n  module_part_no: HHM01A-050\n  name: 50ml垂直震荡模块\n  category: 震荡\n  version: 2.0\n  status: active\n  last_updated: 2026/1/30\n  owner: 宾俊\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 50\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 500\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: \"140 / \"\n  function_description: 垂直震荡\n  operation_target: 50ml离心管\n  operation_workflow: 载台移动到最高点-电推杆向前推动离心管抱夹-抱夹打开-放入离心管-电推杆向后运动-抱夹夹紧-振荡-载台移动到最高点-电推杆向前推动离心管抱夹-抱夹打开-取下离心管；更换样品，重复测试\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 220\n  consumables: 50ml离心管\n  sub_functions: [140 震荡]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: 工位硅胶条\ntags_meta:\n  tags: [垂直震荡]\ndocumentation:\n  urs_url: 未找到\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.2\n  power_kva_peak: 0.2\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 50ml垂直震荡模块\n\n## Purpose (用途说明)\n50ml离心管垂直震荡\n\n## Typical Scenarios (典型应用场景)\n北京海关项目\n\n## Working Principle (工作原理)\n50ml 离心管垂直震荡模块（垂直振荡混匀仪）的核心工作原理，是通过电机驱动机械传动机构，将旋转运动转化为高频、垂直方向的直线往复振动，带动离心管内液体因惯性产生剧烈翻滚与冲击，从而实现快速、均匀混合。\n\n## Limits & Cautions (限制与注意事项)\n最高转速不要超过500\n\n## Remarks (备注)\n', 'MOD-ZD-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:38');
INSERT INTO `smartlabos-module` VALUES ('MOD-ZD-002', '250ml锥形瓶恒温振荡模块', 'HHM01G-250', '振荡', '1.0', 'active', '唐宋', '2025/8/22', '控温振荡、皂化反应', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"控温振荡、皂化反应\"]}, \"peripherals\": {\"required_peripherals\": \"NA\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 250, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 25, \"mount_type\": \"标准模块位\", \"tray_slots\": \"四工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 300, \"speed_rpm_min\": 0, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"80℃\", \"temperature_c_min\": \"室温\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [], \"dependencies\": [], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"250ml锥形瓶\", \"function_code\": 140, \"sub_functions\": [\"NA\"], \"cycle_time_sec\": 1800, \"operation_target\": \"250ml锥形瓶\", \"operation_workflow\": \"Step1：Y轴移动到锥形瓶上下料位，机械手单批次先放2个锥形瓶； / Step2：Y轴移栽至合盖振荡位，合盖气缸伸出完成合盖，接近传感器感应记录锥形瓶所在恒温加热台上位置； / Step3：控制固态继电器使加热片通电发热达到设定温度，并恒温保持设定温度，恒温时间可设置(30min作为参考)。 / Step4：打开R轴电机，锥形瓶恒温加热同时振荡混匀； / Step5：恒温振荡完成后，y轴回到上下料位，合盖气缸退回，机械手下料；\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"该模块实现将250ml锥形瓶在恒温条件下振荡，完成皂化反应\", \"absolute_accuracy_pct\": \"控温精度±3℃\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 220, \"power_kva_peak\": 0.625, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"true\", \"power_kva_nominal\": 0.375, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-ZD-002\", \"name\": \"250ml锥形瓶恒温振荡模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"振荡\", \"last_updated\": \"2025/8/22\", \"module_part_no\": \"HHM01G-250\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-ZD-002\n  module_part_no: HHM01G-250\n  name: 250ml锥形瓶恒温振荡模块\n  category: 振荡\n  version: 1.0\n  status: active\n  last_updated: 2025/8/22\n  owner: 唐宋\nphysical_specs:\n  length_mm: 450\n  width_mm: 250\n  height_mm: 600\n  weight_kg: 25\n  module_slots: 1\n  tray_slots: \"四工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"室温\"\n  temperature_c_max: \"80℃\"\n  speed_rpm_min: 0\n  speed_rpm_max: 300\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: NA\nprocess_capability_1:\n  function_code: 140\n  function_description: 该模块实现将250ml锥形瓶在恒温条件下振荡，完成皂化反应\n  operation_target: 250ml锥形瓶\n  operation_workflow: \"Step1：Y轴移动到锥形瓶上下料位，机械手单批次先放2个锥形瓶； / Step2：Y轴移栽至合盖振荡位，合盖气缸伸出完成合盖，接近传感器感应记录锥形瓶所在恒温加热台上位置； / Step3：控制固态继电器使加热片通电发热达到设定温度，并恒温保持设定温度，恒温时间可设置(30min作为参考)。 / Step4：打开R轴电机，锥形瓶恒温加热同时振荡混匀； / Step5：恒温振荡完成后，y轴回到上下料位，合盖气缸退回，机械手下料；\"\n  absolute_accuracy_pct: 控温精度±3℃\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 1800\n  consumables: 250ml锥形瓶\n  sub_functions: [NA]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    []\n  conflicts:\n    []\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [控温振荡、皂化反应]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.375\n  power_kva_peak: 0.625\n  voltage_v: 220\n  noise_db: 65\n  heat_generating: \"true\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 250ml锥形瓶恒温振荡模块\n\n## Purpose (用途说明)\n用于控温振荡，皂化反应\n\n## Typical Scenarios (典型应用场景)\n维生素检测样品前处理中的皂化反应\n\n## Working Principle (工作原理)\n皂化反应是热驱动反应，温度控制皂化反应的终点，振荡解决油水两不相溶的问题。\n\n## Limits & Cautions (限制与注意事项)\n仅适配 250ml 标准带盖锥形瓶，单批次 2 瓶；温控仅室温至 80℃、精度 ±3℃，振荡幅度固定 10mm、转速 0–300rpm。DC24V/AC220V 供电、总功率 625W，合盖压力 0.5MPa；禁超规格 / 破损瓶，需避光防溢，安装水平，定期校准温控与传感器\n\n## Remarks (备注)\n', 'MOD-ZD-002.md', '2026-06-11 18:33:13', '2026-06-12 11:33:38');
INSERT INTO `smartlabos-module` VALUES ('MOD-ZD-003', '15ml离心管垂直振荡模块', 'HHM01A-015', '振荡', '1.0', 'active', '何向东', '2025/5/23', '垂直振荡', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"垂直振荡\"]}, \"peripherals\": {\"required_peripherals\": \"空压机\"}, \"documentation\": {\"urd_url\": \"URD连接\", \"urs_url\": \"URS连接\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 15, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 500, \"speed_rpm_min\": 1, \"volume_ml_max\": \"NA\", \"volume_ml_min\": \"NA\", \"amplitude_mm_max\": 53, \"amplitude_mm_min\": 1, \"pressure_bar_max\": 6, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": []}, \"process_capability_1\": {\"consumables\": \"离心管-15ml / \", \"function_code\": 140, \"sub_functions\": [], \"cycle_time_sec\": 30, \"operation_target\": \"15ml离心管\", \"operation_workflow\": \"载台移至最高点 - 电推杆推动抱夹打开 - 机械臂放入离心管 - 夹紧 - 振荡（500rpm/5min）- 停止 - 载台移至最高点 - 机械臂夹持离心管（两个同时） - 电推杆推动抱夹打开 - 取下离心管 - 电推杆返回； / 停顿1分钟，重复工作流程\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"振荡\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.36, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.216, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-ZD-003\", \"name\": \"15ml离心管垂直振荡模块\", \"owner\": \"何向东\", \"status\": \"active\", \"version\": 1.0, \"category\": \"振荡\", \"last_updated\": \"2025/5/23\", \"module_part_no\": \"HHM01A-015\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-ZD-003\n  module_part_no: HHM01A-015\n  name: 15ml离心管垂直振荡模块\n  category: 振荡\n  version: 1.0\n  status: active\n  last_updated: 2025/5/23\n  owner: 何向东\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 15\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: \"NA\"\n  volume_ml_max: \"NA\"\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 1\n  speed_rpm_max: 500\n  pressure_bar_min: 1\n  pressure_bar_max: 6\n  amplitude_mm_min: 1\n  amplitude_mm_max: 53\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: 空压机\nprocess_capability_1:\n  function_code: 140\n  function_description: 振荡\n  operation_target: 15ml离心管\n  operation_workflow: \"载台移至最高点 - 电推杆推动抱夹打开 - 机械臂放入离心管 - 夹紧 - 振荡（500rpm/5min）- 停止 - 载台移至最高点 - 机械臂夹持离心管（两个同时） - 电推杆推动抱夹打开 - 取下离心管 - 电推杆返回； / 停顿1分钟，重复工作流程\"\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 30\n  consumables: \"离心管-15ml / \"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    []\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [垂直振荡]\ndocumentation:\n  urs_url: URS连接\n  urd_url: URD连接\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.216\n  power_kva_peak: 0.36\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 15ml离心管垂直振荡模块\n\n## Purpose (用途说明)\n实现15ml尖底离心管的上下振荡\n\n## Typical Scenarios (典型应用场景)\n1、水质检测15ml 离心管样品垂直振荡混匀前处理\n2、环境水样、土壤浸提液、固废提取液垂直振荡萃取\n3、食品 / 农产品样品15ml 离心管振荡均匀化处理\n4、生化试剂、标准溶液、缓冲液垂直振荡充分溶解\n5、实验室小体积样品高速垂直振荡、充分反应场景\n\n## Working Principle (工作原理)\n通过伺服电机驱动、电动推杆夹紧试管，并由光电开关检测定位，自动完成放瓶、夹紧、上下振荡、取瓶的全流程作业\n\n## Limits & Cautions (限制与注意事项)\n1、仅适用于15ml 标准离心管，不得使用其他规格。\n2、仅适配带盖密封的 15ml 离心管，无盖、裂盖、变形管禁止使用。\n3、振荡幅度、转速、时间按工艺参数设定，禁止超范围运行\n4、仅用于常规水样 / 提取液 / 非危险样品，严禁用于强酸、强碱、易燃易爆、易挥发、剧毒液体。\n\n## Remarks (备注)\n', 'MOD-ZD-003.md', '2026-06-11 18:33:13', '2026-06-12 11:33:38');
INSERT INTO `smartlabos-module` VALUES ('MOD-ZY-001', '150ml面包瓶锥形瓶振摇模块', 'HHM01K-150', '振摇', '1.0', 'active', '唐宋', '2026/4/17', '振摇，混匀，面包瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"振摇\", \"混匀\", \"面包瓶\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 224, \"height_mm\": 165, \"length_mm\": 469, \"weight_kg\": 40, \"mount_type\": \"托盘位\", \"tray_slots\": \"四工位\", \"module_slots\": 3}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": 3000, \"speed_rpm_min\": 100, \"volume_ml_max\": 150, \"volume_ml_min\": 1, \"pressure_bar_max\": \"NA\", \"pressure_bar_min\": \"NA\", \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\"]}, \"process_capability_1\": {\"consumables\": \"150ml面包瓶,150ml锥形瓶\", \"function_code\": 590, \"sub_functions\": [\"591-搅拌中途上料\"], \"cycle_time_sec\": 1200, \"operation_target\": \"150ml面包瓶/锥形瓶\", \"operation_workflow\": \"初始化 -放第一批2个面包瓶 - 振摇- 停止 - 放第二批2个面包瓶-振摇-第一批振摇时间到-下料第一批面包瓶-振摇-第二批振摇时间到-下料第二批面包瓶\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"面包瓶/锥形瓶振摇\", \"absolute_accuracy_pct\": \"NA\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.22, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.13, \"requires_ventilation\": false, \"requires_compressed_air\": false}, \"identification_version\": {\"id\": \"MOD-ZY-001\", \"name\": \"150ml面包瓶锥形瓶振摇模块\", \"owner\": \"唐宋\", \"status\": \"active\", \"version\": 1.0, \"category\": \"振摇\", \"last_updated\": \"2026/4/17\", \"module_part_no\": \"HHM01K-150\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-ZY-001\n  module_part_no: HHM01K-150\n  name: 150ml面包瓶锥形瓶振摇模块\n  category: 振摇\n  version: 1.0\n  status: active\n  last_updated: 2026/4/17\n  owner: 唐宋\nphysical_specs:\n  length_mm: 469\n  width_mm: 224\n  height_mm: 165\n  weight_kg: 40\n  module_slots: 3\n  tray_slots: \"四工位\"\n  mount_type: 托盘位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 150\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: 100\n  speed_rpm_max: 3000\n  pressure_bar_min: \"NA\"\n  pressure_bar_max: \"NA\"\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 590\n  function_description: 面包瓶/锥形瓶振摇\n  operation_target: 150ml面包瓶/锥形瓶\n  operation_workflow: 初始化 -放第一批2个面包瓶 - 振摇- 停止 - 放第二批2个面包瓶-振摇-第一批振摇时间到-下料第一批面包瓶-振摇-第二批振摇时间到-下料第二批面包瓶\n  absolute_accuracy_pct: NA\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 1200\n  consumables: 150ml面包瓶,150ml锥形瓶\n  sub_functions: [591-搅拌中途上料]\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: \"\"\ntags_meta:\n  tags: [振摇, 混匀, 面包瓶]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.13\n  power_kva_peak: 0.22\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: false\n  requires_water: false\n  requires_drain: false', '# 150ml面包瓶锥形瓶振摇模块\n\n## Purpose (用途说明)\n实现150ml面包瓶和锥形瓶的振摇/水平振摇，使样品充分混匀\n\n## Typical Scenarios (典型应用场景)\n1、微生物 / 菌种培养振荡\n2、样品萃取与固液混匀\n3、试剂反应加速混匀\n\n\n## Working Principle (工作原理)\n依靠传感器识别物料，通过旋转轴运转带动瓶体晃动，配合机械手上下料，分时控时完成多批次物料交替振摇\n\n## Limits & Cautions (限制与注意事项)\n1、放瓶要求：瓶子底部放平、直立放稳，紧贴定位槽，防止振摇滑动、倾倒。\n2、参数设置：根据样品粘度与性质选择转速，低粘度用中高速、高粘度用低速。\n3、中途上下料：仅在平台回待机位时放取瓶子，避免碰撞、夹手。\n4、运行观察：振摇中留意瓶子是否移位、液体是否溢出，异常立即停机。\n5、日常维护：保持平台清洁干燥；定期检查电机、传感器；长期不用断电。\n\n## Remarks (备注)\n', 'MOD-ZY-001.md', '2026-06-11 18:33:13', '2026-06-12 11:33:38');
INSERT INTO `smartlabos-module` VALUES ('MOD-ZY-008', '150ml锥形瓶全量转移', 'HHM09L-150', '移液', '1.0', 'active', '蔡勤超/深圳', '2025/6/6', '全量，转移，150ml锥形瓶', '{\"price\": {\"quote_rmb\": \"\", \"sales_floor_rmb\": \"\", \"cost_internal_rmb\": null}, \"tags_meta\": {\"tags\": [\"全量\", \"转移\", \"150ml锥形瓶\"]}, \"peripherals\": {\"required_peripherals\": \"\"}, \"documentation\": {\"urd_url\": \"\", \"urs_url\": \"\", \"plc_source_url\": \"PLC源程序连接\"}, \"physical_specs\": {\"width_mm\": 180, \"height_mm\": 600, \"length_mm\": 450, \"weight_kg\": 20, \"mount_type\": \"标准模块位\", \"tray_slots\": \"双工位\", \"module_slots\": 1}, \"module_performance\": {\"vacuum_kpa\": \"NA\", \"speed_rpm_max\": \"NA\", \"speed_rpm_min\": \"NA\", \"volume_ml_max\": 150, \"volume_ml_min\": 1, \"pressure_bar_max\": 4, \"pressure_bar_min\": 1, \"temperature_c_max\": \"NA\", \"temperature_c_min\": \"NA\"}, \"delivery_maintenance\": {\"wear_parts\": \"NA\", \"lead_time_weeks\": 8, \"maintenance_cycle_months\": 6}, \"module_relationships\": {\"conflicts\": [\"--相互影响模块\"], \"dependencies\": [\"--前置/后置模块\"], \"typical_pairings\": [\"--和模块配合使用\", \"正压加液\"]}, \"process_capability_1\": {\"consumables\": \"锥形瓶-150ml / 容量瓶-50ml\", \"function_code\": 580, \"sub_functions\": [], \"cycle_time_sec\": 180, \"operation_target\": \"150ml锥形瓶\", \"operation_workflow\": \"载台移至上下料位 - 放入锥形瓶/容量瓶 - 真空吸紧 - 载台移至取液位 - 破真空 - 取液钢针下降伸入锥形瓶底部 - 注射泵吸取样品 - 切换排液管路 - 注射泵将样品排入容量瓶 - 重复吸取至样品取净 - 清洗气缸下压 - 加清洗液 - 吸取清洗后样品 - 排入容量瓶 - 重复清洗并吸取至样品取净 - 取液钢针返回 - 真空吸紧 - 载台移至上下料位 - 破真空 - 取下锥形瓶/容量瓶 - 清洗管路 - 载台移至排废位 - 排废液\", \"repeat_accuracy_pct\": \"NA\", \"function_description\": \"全量转移启动\", \"absolute_accuracy_pct\": \"200ul\"}, \"module_up_unload_time\": {\"up_unload_time\": \"60s\"}, \"electrical_environment\": {\"noise_db\": 65, \"voltage_v\": 24, \"power_kva_peak\": 0.17, \"requires_drain\": false, \"requires_water\": false, \"heat_generating\": \"false\", \"power_kva_nominal\": 0.11, \"requires_ventilation\": false, \"requires_compressed_air\": true}, \"identification_version\": {\"id\": \"MOD-ZY-008\", \"name\": \"150ml锥形瓶全量转移\", \"owner\": \"蔡勤超/深圳\", \"status\": \"active\", \"version\": 1.0, \"category\": \"移液\", \"last_updated\": \"2025/6/6\", \"module_part_no\": \"HHM09L-150\"}, \"platform_compatibility\": {\"compatible_platforms\": [\"PLT-800\", \"PLT-1200\", \"PLT-1400\"], \"incompatible_platforms\": []}}', 'identification_version:\n  id: MOD-ZY-008\n  module_part_no: HHM09L-150\n  name: 150ml锥形瓶全量转移\n  category: 移液\n  version: 1.0\n  status: active\n  last_updated: 2025/6/6\n  owner: 蔡勤超/深圳\nphysical_specs:\n  length_mm: 450\n  width_mm: 180\n  height_mm: 600\n  weight_kg: 20\n  module_slots: 1\n  tray_slots: \"双工位\"\n  mount_type: 标准模块位\nmodule_performance:\n  volume_ml_min: 1\n  volume_ml_max: 150\n  temperature_c_min: \"NA\"\n  temperature_c_max: \"NA\"\n  speed_rpm_min: \"NA\"\n  speed_rpm_max: \"NA\"\n  pressure_bar_min: 1\n  pressure_bar_max: 4\n  vacuum_kpa: NA\nperipherals:\n  required_peripherals: \"\"\nprocess_capability_1:\n  function_code: 580\n  function_description: 全量转移启动\n  operation_target: 150ml锥形瓶\n  operation_workflow: 载台移至上下料位 - 放入锥形瓶/容量瓶 - 真空吸紧 - 载台移至取液位 - 破真空 - 取液钢针下降伸入锥形瓶底部 - 注射泵吸取样品 - 切换排液管路 - 注射泵将样品排入容量瓶 - 重复吸取至样品取净 - 清洗气缸下压 - 加清洗液 - 吸取清洗后样品 - 排入容量瓶 - 重复清洗并吸取至样品取净 - 取液钢针返回 - 真空吸紧 - 载台移至上下料位 - 破真空 - 取下锥形瓶/容量瓶 - 清洗管路 - 载台移至排废位 - 排废液\n  absolute_accuracy_pct: 200ul\n  repeat_accuracy_pct: NA\n  cycle_time_sec: 180\n  consumables: \"锥形瓶-150ml / 容量瓶-50ml\"\n  sub_functions: []\nmodule_up_unload_time:\n  up_unload_time: 60s\nplatform_compatibility:\n  compatible_platforms:\n    - PLT-800\n    - PLT-1200\n    - PLT-1400\n  incompatible_platforms:\n    []\nmodule_relationships:\n  dependencies:\n    - --前置/后置模块\n  conflicts:\n    - --相互影响模块\n  typical_pairings:\n    - --和模块配合使用\n    - 正压加液\ndelivery_maintenance:\n  lead_time_weeks: 8\n  maintenance_cycle_months: 6\n  wear_parts: NA\ntags_meta:\n  tags: [全量, 转移, 150ml锥形瓶]\ndocumentation:\n  urs_url: \"\"\n  urd_url: \"\"\n  plc_source_url: PLC源程序连接\nprice:\n  cost_internal_rmb: null\n  sales_floor_rmb: \"\"\n  quote_rmb: \"\"\nelectrical_environment:\n  power_kva_nominal: 0.11\n  power_kva_peak: 0.17\n  voltage_v: 24\n  noise_db: 65\n  heat_generating: \"false\"\n  requires_ventilation: false\n  requires_compressed_air: true\n  requires_water: false\n  requires_drain: false', '# 150ml锥形瓶全量转移\n\n## Purpose (用途说明)\n实现150ml锥形瓶的液体全量移液至50ml容量瓶，模块里包含，全量移液、锥形瓶清洗、管路清洗等功能。\n\n## Typical Scenarios (典型应用场景)\n实验室自动化液体全量转移与清洗一体化案例\n适用于生物、医药、检测实验室，将150ml 锥形瓶内的样本 / 试剂完全转移至 50ml 容量瓶，并自动完成锥形瓶清洗 + 管路清洗，实现无残留、无污染、全流程自动化移液。\n\n## Working Principle (工作原理)\n通过机械手（或人工）上料后，真空吸附固定容器，取液轴移位、钢针下移，注射泵配合电磁阀切换取液 / 排液回路，循环完成瓶内液体全量转移；转移结束后，启动气缸与电磁阀联动清洗管路，最后载台归位、释放容器，全程自动化实现液体无残留转移与管路清洁。\n\n## Limits & Cautions (限制与注意事项)\n1、仅适配150ml 锥形瓶、50ml 容量瓶，必须精准定位、真空吸紧再运行。\n2、取液 / 排液针必须到位后再动作，禁止空撞、空抽、空排。3、移液前检查管路无堵塞、无漏液，电磁阀切换正常。\n4、移液完成必须执行瓶体 + 管路清洗，防止残留与交叉污染。\n5、运行中禁止触碰运动轴、针头、载台；异常立即急停。\n6、维护需断电、断气、排空管路，禁止带压检修。\n\n## Remarks (备注)\n第一：液量转移基本完成，转移能够达到95％以上\n第二：喷淋效果不佳，更改150ml锥形瓶吸液位置后，喷淋效果一半瓶壁能喷淋清洗到，另外一半瓶壁没有喷淋清洗到，淋洗效果并不理想，清洗效果不好', 'MOD-ZY-008.md', '2026-06-11 18:33:13', '2026-06-12 11:33:38');

-- ----------------------------
-- Table structure for smartlabos-platformbase
-- ----------------------------
DROP TABLE IF EXISTS `smartlabos-platformbase`;
CREATE TABLE `smartlabos-platformbase`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '卡片ID，如 PLT-800',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '平台名称',
  `platform_part_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '平台物料号',
  `version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '版本',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态',
  `owner` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '负责人',
  `last_updated` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新',
  `tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签',
  `data_json` json NULL COMMENT 'front-matter 全量 JSON',
  `raw_frontmatter` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原始 YAML front-matter',
  `body_markdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Markdown 正文',
  `source_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源文件名',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_platform_name`(`name` ASC) USING BTREE,
  INDEX `idx_platform_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'SmartLabOS 平台基类主数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of smartlabos-platformbase
-- ----------------------------
