-- Records of smartlabos-solution
-- ----------------------------
INSERT INTO `smartlabos-solution` VALUES ('SOL-PEST-CDSJY-01', '成都食检院-127种药物残留-肉类', 'A', '已验证', '1.0', 'active', '林雪平', '2026-05-25', '食品检测，兽残，127种药物残留-肉类', '{\"tags\": [\"食品检测\", \"兽残，127种药物残留-肉类\"], \"upgrades\": [], \"commercial\": {\"price_rmb\": {\"total\": null, \"hardware\": null, \"training\": null, \"installation\": null, \"first_year_service\": null}, \"lead_time_weeks\": 4, \"warranty_months\": 12}, \"deployments\": [{\"date\": \"2026-05-25\", \"customer\": \"成都食检院\", \"feedback\": \"客户反馈良好\", \"location\": \"成都\", \"contact_available\": true, \"sample_throughput\": \"48样/天\"}], \"performance\": {\"rsd_percent\": \"NA\", \"recovery_rate\": \"NA\", \"detection_limit\": \"NA\"}, \"alternatives\": [], \"workstations\": [{\"role\": \"提取\", \"ws_id\": \"WS-PEST-Extract-SJY-01\", \"quantity\": 1, \"sequence\": 1}, {\"role\": \"提取\", \"ws_id\": \"WS-PEST-Extract-SJY-02\", \"quantity\": 1, \"sequence\": 2}, {\"role\": \"水解\", \"ws_id\": \"WS-PEST-Hydrolysis-SJY-03\", \"quantity\": 1, \"sequence\": 3}, {\"role\": \"提取净化\", \"ws_id\": \"WS-PEST-Cleanup-SJY-04\", \"quantity\": 1, \"sequence\": 4}, {\"role\": \"SPE净化\", \"ws_id\": \"WS-PEST-SPE-SJY-05\", \"quantity\": 1, \"sequence\": 5}, {\"role\": \"提取净化\", \"ws_id\": \"WS-PEST-Concentrate-SJY-06\", \"quantity\": 1, \"sequence\": 6}, {\"role\": \"离心净化\", \"ws_id\": \"WS-PEST-Centrifuge-SJY-07\", \"quantity\": 1, \"sequence\": 7}], \"business_context\": {\"target_samples\": [\"肉类\"], \"target_analytes\": [\"127种药物残留\"], \"matches_standards\": [\"GB 31658.26-2025《食品安全国家标准 动物性食品中 127 种药物残留量的筛查 液相色谱 - 高分辨质谱法》\"], \"target_industries\": [\"食品安全检测\"]}, \"throughput_target\": {\"throughput_8h\": 32, \"throughput_12h\": 48, \"samples_per_day\": 48, \"parallel_capacity\": 4, \"samples_per_batch\": 32, \"total_cycle_time_min\": 186}, \"identification_version\": {\"id\": \"SOL-PEST-CDSJY-01\", \"name\": \"成都食检院-127种药物残留-肉类\", \"owner\": \"林雪平\", \"status\": \"active\", \"version\": 1.0, \"maturity\": \"已验证\", \"last_updated\": \"2026-05-25\", \"proposal_type\": \"A\"}}', 'identification_version:\n  id: SOL-PEST-CDSJY-01\n  name: 成都食检院-127种药物残留-肉类\n  version: 1.0\n  status: active\n  last_updated: 2026-05-25\n  owner: 林雪平\n  maturity: 已验证\n  proposal_type: A\nbusiness_context:\n  target_industries:\n    - 食品安全检测\n  target_samples:\n    - 肉类\n  target_analytes:\n    - 127种药物残留\n  matches_standards:\n    - GB 31658.26-2025《食品安全国家标准 动物性食品中 127 种药物残留量的筛查 液相色谱 - 高分辨质谱法》\nworkstations:\n  - ws_id: WS-PEST-Extract-SJY-01\n    sequence: 1\n    role: 提取\n    quantity: 1\n  - ws_id: WS-PEST-Extract-SJY-02\n    sequence: 2\n    role: 提取\n    quantity: 1\n  - ws_id: WS-PEST-Hydrolysis-SJY-03\n    sequence: 3\n    role: 水解\n    quantity: 1\n  - ws_id: WS-PEST-Cleanup-SJY-04\n    sequence: 4\n    role: 提取净化\n    quantity: 1\n  - ws_id: WS-PEST-SPE-SJY-05\n    sequence: 5\n    role: SPE净化\n    quantity: 1\n  - ws_id: WS-PEST-Concentrate-SJY-06\n    sequence: 6\n    role: 提取净化\n    quantity: 1\n  - ws_id: WS-PEST-Centrifuge-SJY-07\n    sequence: 7\n    role: 离心净化\n    quantity: 1\nthroughput_target:\n  samples_per_day: 48\n  samples_per_batch: 32\n  total_cycle_time_min: 186\n  parallel_capacity: 4\n  throughput_8h: 32\n  throughput_12h: 48\nperformance:\n  recovery_rate: NA\n  rsd_percent: NA\n  detection_limit: NA\ncommercial:\n  price_rmb:\n    hardware: null\n    installation: null\n    training: null\n    first_year_service: null\n    total: null\n  lead_time_weeks: 4\n  warranty_months: 12\ndeployments:\n  - customer: 成都食检院\n    location: 成都\n    date: 2026-05-25\n    sample_throughput: 48样/天\n    feedback: 客户反馈良好\n    contact_available: true\nalternatives:\n  []\nupgrades:\n  []\ntags: [食品检测, 兽残，127种药物残留-肉类]', '# 成都食检院-127种药物残留-肉类\n\n## 方案定位\n面向食品安全检测的兽残前处理全自动化产线，覆盖提取平台→均质&加内标&调PH平台→恒温反应平台→提取平台→浓缩和复溶平台→2ml离心净化平台→LC-MS/MS检测平台\n\n## 适用客户画像\n1. 各级食品检验检测机构\n2. 海关、农业农村部门技术中心\n3. 大型食品/水产企业 QC 实验室\n\n## 工艺选择理由\n依据 GB 31658.26-2025《食品安全国家标准 动物性食品中 127 种药物残留量的筛查 液相色谱 - 高分辨质谱法》，结合客户日通量 48 样需求，选用 PLT-1200 + 7 模块组合……\n\n## 配置说明\n产线由 7 个 Workstation 组成\n\n## 部署要求\n占地约 12 ㎡，220V/24V 电源，需通风、压缩空气、地排，环境温度 4~40 ℃\n\n## 已知限制\nNA\n\n## 关键风险\nNA', 'SOL-PEST-CDSJY-01.md', '2026-06-11 18:33:13', '2026-06-11 18:33:13');
