 name: 加液\n        module_id: MOD-WX-006\n        duration_min: 1\n        parameters:\n          甲醇+水: 10.0ml\n      - step: 2\n        name: 振荡\n        module_id: MOD-ZD-001\n        duration_min: 1\n        parameters:\n          振荡时间: 600S\n      - step: 3\n        name: 离心\n        module_id: MOD-LX-005\n        duration_min: 1\n        parameters:\n          离心转速: 4000RPM\n        note: 离心时间=300S\n      - step: 4\n        name: 弃去液体\n        module_id: MOD-YY-004\n        duration_min: 1\n    total_cycle_time_min: 36\n    parallel_capacity: 4\n    batch_capacity: 16\n    target_industries:\n      - 1.食品安全检测行业\n    throughput_8h: 42\n    throughput_12h: 80\n    target_analytes:\n      - 硝基呋喃\n    target_samples:\n      - 肌肉\n  - name: 工站实验流程4\n    matches_standards:\n      - 1.GB/T 21311-2007《动物源性食品中硝基呋喃类药物代谢物残留量检测方法 高效液相色谱 / 串联质谱法》\n    step_description: 加液涡旋-振荡-离心-取上层收集合并，重复两次\n    consumables:\n      - 50ML离心管\n    workflow_steps:\n      - step: 1\n        name: 加液\n        module_id: MOD-WX-006\n        duration_min: 1\n        parameters:\n          乙酸乙酯: 10-20ml\n      - step: 2\n        name: 振荡\n        module_id: MOD-ZD-001\n        duration_min: 1\n        parameters:\n          振荡时间: 600S\n      - step: 3\n        name: 离心\n        module_id: MOD-LX-005\n        duration_min: 1\n        parameters:\n          离心转速: 10000RPM\n        note: 离心时间=300S\n      - step: 4\n        name: 全量转移\n        module_id: MOD-YY-004\n        duration_min: 1\n    total_cycle_time_min: 79\n    parallel_capacity: 4\n    batch_capacity: 16\n    target_industries:\n      - 1.食品安全检测行业\n    throughput_8h: 24\n    throughput_12h: 36\n    target_analytes:\n      - 硝基呋喃\n    target_samples:\n      - 肌肉\n  - name: 工站实验流程5\n    matches_standards:\n      - 1.GB 31656.13-2021《食品安全国家标准 水产品中硝基呋喃类代谢物多残留的测定 液相色谱 - 串联质谱法》\n    step_description: 加液-涡旋-离心-取上层\n    consumables:\n      - 50ML离心管\n    workflow_steps:\n      - step: 1\n        name: 加液\n        module_id: MOD-WX-006\n        duration_min: 1\n        parameters:\n          乙酸乙酯: 8ml\n      - step: 2\n        name: 涡旋\n        module_id: MOD-WX-006\n        duration_min: 1\n        parameters:\n          涡旋时间: 30S\n      - step: 3\n        name: 离心\n        module_id: MOD-LX-005\n        duration_min: 1\n        parameters:\n          离心转速: 6000RPM\n        note: 离心时间=300S\n      - step: 4\n        name: 全量转移\n        module_id: MOD-YY-004\n        duration_min: 1\n    total_cycle_time_min: 39\n    parallel_capacity: 4\n    batch_capacity: 16\n    target_industries:\n      - 1.食品安全检测行业\n    throughput_8h: 48\n    throughput_12h: 72\n    target_analytes:\n      - 硝基呋喃\n    target_samples:\n      - 鱼肉\ncommercial:\n  price_rmb:\n    hardware: null\n    installation: null\n    training: null\n    first_year_service: null\n    total: null\n  lead_time_weeks: 12\n  warranty_months: 12\ndeployments:\n  - customer: 成都食检院\n    location: 成都\n    date: 2026-05-25\n    sample_throughput: 44样/天\n    feedback: 客户反馈良好\n    contact_available: true\nalternatives:\n  []\nupgrades:\n  []\ntags: [提取清洗平台]', '# 食检院-兽残提取平台\n\n## 方案定位\n实现各类样品基质的自动化提取，一站式完成扫码、开关盖、移液、液体 / 固体试剂添加、涡旋混匀、振荡提取、离心分离、上清转移等操作；支持多标准提取操作整合，多样品并行处理，可 24 小时不间断运行，适配高通量、复杂前处理需求。\n\n## 适用客户画像\n平台适配畜禽肉、水产、果蔬等不同基质样品的前处理需求\n\n## 配置说明\n实现各类样品基质的自动化提取，一站式完成扫码、开关盖、移液、液体 / 固体试剂添加、涡旋混匀、振荡提取、离心分离、上清转移等操作；支持多标准提取操作整合，多样品并行处理，可 24 小时不间断运行，适配高通量、复杂前处理需求。\n\n\n## 部署要求\n占地 1.5㎡，220V电压，通风系统、排废系统', 'WS-PEST-Extract-SJY-02.md', '2026-06-11 18:33:13', '2026-06-11 18:33:13');
